EMPTY_DEFINITION = {'schema_version': 1, 'abilities': []}


def attack(instance_id, owner, *, code=None, frame=5, damage=400, position='상단', special=None, hit='0', counter='0'):
    return {
        'instance_id': instance_id, 'kind': 'card', 'owner': owner,
        'code': code or instance_id.upper(), 'name': instance_id, 'type': '공격',
        'frame': frame, 'damage': damage, 'pos': position, 'special': special,
        'hit': hit, 'guard': '0', 'counter': counter, 'face_up': False,
    }


def defense(instance_id, owner, *, top='방어', mid=None, bottom=None):
    return {
        'instance_id': instance_id, 'kind': 'card', 'owner': owner,
        'code': instance_id.upper(), 'name': instance_id, 'type': '수비',
        'frame': None, 'damage': None, 'g_top': top, 'g_mid': mid, 'g_bot': bottom,
        'hit': '0', 'guard': '0', 'counter': '0', 'face_up': False,
    }


def base_state(p1_cards=None, p2_cards=None, *, p1_fp=0, p2_fp=0, hp=5000):
    players = {}
    for side, cards, fp in (('p1', p1_cards or [], p1_fp), ('p2', p2_cards or [], p2_fp)):
        players[side] = {
            'name': side, 'hp': hp, 'fp': fp, 'passive_state': {},
            'zones': {
                'character': [], 'passive': [], 'battle': [], 'list': [],
                'hand': cards, 'side': [], 'break': [], 'lumen': [], 'ultimate': [],
            },
        }
    return {'turn': 1, 'phase': 'lumen', 'priority_player': 'p1', 'players': players}


def ruleset(*cards):
    return {
        'version': 'test-v1',
        'cards': {
            card['code']: {
                **{key: card.get(key) for key in ('code', 'name', 'type', 'frame', 'damage', 'pos', 'special', 'hit', 'guard', 'counter', 'g_top', 'g_mid', 'g_bot')},
                'effect_definition': EMPTY_DEFINITION,
            }
            for card in cards
        },
    }


def damage_limited_choice_definition(code='DAMAGE-LIMITED-CHOICE-REVIEW'):
    definition = build_effect_draft(
        code,
        '①배틀 페이즈 종료 시, 사이드 덱에서 [[token:parts]]를 4장까지 '
        '루멘 존에 배치할 수 있다. 이번 턴 데미지를 받았다면 '
        '[[token:parts]]를 1장까지 배치할 수 있다.',
    )
    ability = definition['abilities'][0]
    normal = ability['effects'][0]
    normal['optional'] = True
    damaged = json.loads(json.dumps(normal))
    damaged['selector']['max'] = 1
    damaged['selection_key'] = 'damaged_parts'
    damaged['then'][0]['selection_key'] = 'damaged_parts'
    ability['effects'] = [{
        'op': 'conditional',
        'condition': {
            'op': 'gt', 'left': 'context.controller_turn_damage_received',
            'right': 0,
        },
        'then': [damaged], 'else': [normal],
    }]
    return definition


class AutomaticEngineTests(SimpleTestCase):
    def test_console_json_escapes_only_glyphs_unsupported_by_windows_console(self):
        stream = SimpleNamespace(_out=SimpleNamespace(encoding='cp949'))

        rendered = console_safe_json({'marker': '•', 'text': '한글'}, stream)

        self.assertIn('\\u2022', rendered)
        self.assertIn('한글', rendered)

    def test_effect_schema_accepts_general_qna_and_rejects_invalid_ids(self):
        definition = {
            'schema_version': 1, 'reviewed': False,
            'source_refs': {'general_qna_ids': [139]},
            'abilities': [],
        }
        self.assertEqual(validate_effect_definition(definition), [])

        definition['source_refs']['general_qna_ids'] = [0]
        issues = validate_effect_definition(definition)
        self.assertIn(
            '$.source_refs.general_qna_ids',
            {issue.path for issue in issues},
        )

    def test_combo_reuse_schema_requires_an_explicit_usage_limit(self):
        definition = {
            'schema_version': 1, 'abilities': [],
            'combo_rules': [{
                'allow_zones': ['battle'], 'allow_reuse': True,
            }],
        }
        issues = validate_effect_definition(definition)
        self.assertIn(
            '$.combo_rules[0].allow_reuse',
            {issue.path for issue in issues},
        )

        definition['combo_rules'][0].update({
            'usage_key': 'limited-battle-reuse',
            'usage_scope': 'turn', 'max_uses': 1,
            'respect_speed_window': True,
        })
        self.assertEqual(validate_effect_definition(definition), [])

