    def test_mutual_combo_ends_after_both_ready_cards_without_catch(self):
        p1_ready = attack('p1-ready', 'p1', frame=5, damage=200, hit='콤보')
        p2_ready = attack('p2-ready', 'p2', frame=5, damage=200, hit='콤보')
        p1_extra = attack('p1-extra', 'p1', frame=6, damage=500)
        p2_extra = attack('p2-extra', 'p2', frame=6, damage=500)
        engine = self.make_engine(
            [p1_ready, p1_extra],
            [p2_ready, p2_extra],
            p1_fp=2,
            p2_fp=2,
        )
        self.enter_ready(engine)
        for side, card_id in (('p1', 'p1-ready'), ('p2', 'p2-ready')):
            action = next(
                item for item in engine.legal_actions(side)
                if item['type'] == 'ready_card'
                and item['payload']['card_instance_id'] == card_id
            )
            engine.submit_action(side, action['action_id'], {}, command_id=f'ready-{side}')

        self.assertEqual(engine.state['phase'], 'get')
        self.assertIsNone(engine.engine_state.get('combo'))
        self.assertFalse(any(event['type'] == 'combo_card_used' for event in engine.events))
        self.assertFalse(any(event['type'] == 'catch_started' for event in engine.events))
        self.assertIn('p1-ready', [card['instance_id'] for card in engine.state['players']['p1']['zones']['list']])
        self.assertIn('p2-ready', [card['instance_id'] for card in engine.state['players']['p2']['zones']['list']])
        self.assertIn('p1-extra', [card['instance_id'] for card in engine.state['players']['p1']['zones']['hand']])
        self.assertIn('p2-extra', [card['instance_id'] for card in engine.state['players']['p2']['zones']['hand']])

