    def test_non_owner_can_pause_and_either_player_can_resume_clock(self):
        engine = self.make_engine(
            [attack('p1-a', 'p1')],
            [attack('p2-a', 'p2')],
        )
        self.enter_ready(engine)
        self.act(engine, 'p1', 'ready_card')

        self.act(engine, 'p1', 'pause_clock', {'reason': '연결 상태 확인'})
        paused = engine.engine_state['clock']
        self.assertTrue(paused['paused'])
        self.assertEqual(paused['pause_reason'], '연결 상태 확인')

        self.act(engine, 'p2', 'resume_clock')
        self.assertFalse(engine.engine_state['clock']['paused'])
        self.assertTrue(engine.engine_state['clock']['deadline'])

    def test_ability_target_uses_server_candidates_and_resumes_effect(self):
        source = attack('p1-source', 'p1', code='TARGET', damage=100)
        target = attack('p1-target', 'p1', damage=300)
        defender = defense('p2-defense', 'p2')
        release = ruleset(source, target, defender)
        release['cards']['TARGET']['effect_definition'] = {
            'schema_version': 1,
            'abilities': [{
                'id': 'move-target', 'kind': 'effect', 'mode': 'mandatory',
                'trigger': {'event': 'use'}, 'timing': 'use', 'source_refs': {'rulebook_pages': [36]},
                'targets': [{
                    'id': 'chosen', 'kind': 'card', 'player': {'controller': True},
                    'zone': 'hand', 'min': 1, 'max': 1,
                }],
                'effects': [{'op': 'move_card', 'selection_key': 'chosen', 'to_zone': 'list'}],
            }],
        }
        engine = AutomaticGameEngine.initialize(base_state([source, target], [defender]), release, seed='target')
        self.enter_ready(engine)
        ready = next(
            action for action in engine.legal_actions('p1')
            if action['type'] == 'ready_card' and action['payload']['card_instance_id'] == 'p1-source'
        )
        engine.submit_action('p1', ready['action_id'], {}, command_id='source-ready')
        self.act(engine, 'p2', 'ready_card')

        decision = engine.state['engine']['pending_decision']
        self.assertEqual([option['id'] for option in decision['options']], ['p1-target'])
        self.act(engine, 'p1', 'submit_decision', {'selected': ['p1-target']})
        self.assertIn('p1-target', [card['instance_id'] for card in engine.state['players']['p1']['zones']['list']])

