    def test_ready_timeout_counts_no_response_and_third_is_disqualification(self):
        engine = self.make_engine(
            [attack('p1-a', 'p1')],
            [attack('p2-a', 'p2'), attack('p2-b', 'p2')],
        )
        self.enter_ready(engine)
        self.act(engine, 'p1', 'ready_card')
        engine.state['engine']['no_response']['p2'] = 2
        deadline = datetime.fromisoformat(engine.state['engine']['clock']['deadline'])
        engine.now = deadline + timedelta(seconds=1)

        self.assertTrue(engine.reconcile_clock())
        self.assertEqual(engine.state['engine']['no_response']['p2'], 3)
        self.assertEqual(engine.state['engine']['status'], 'finished')
        self.assertEqual(engine.state['engine']['winner'], 'p1')

    def test_no_response_effect_resolves_before_forced_card_choice(self):
        p1 = attack('p1-a', 'p1')
        p2 = attack('p2-a', 'p2')
        passive = attack('p2-passive', 'p2', code='NO-RESPONSE-EFFECT')
        passive['type'] = '특성'
        release = ruleset(p1, p2, passive)
        release['cards']['NO-RESPONSE-EFFECT']['effect_definition'] = {
            'schema_version': 1,
            'abilities': [{
                'id': 'optional-no-response', 'kind': 'effect', 'mode': 'optional',
                'visibility': 'private', 'active_zones': ['passive'],
                'trigger': {'event': 'no_response'}, 'timing': 'result',
                'source_refs': {'rulebook_pages': [27]},
                'effects': [{'op': 'change_fp', 'player': {'controller': True}, 'amount': 1}],
            }],
        }
        state = base_state([p1], [p2])
        state['players']['p2']['zones']['passive'].append(passive)
        engine = AutomaticGameEngine.initialize(state, release, seed='no-response-effect')
        self.enter_ready(engine)
        self.act(engine, 'p1', 'ready_card')
        deadline = datetime.fromisoformat(engine.engine_state['clock']['deadline'])
        engine.now = deadline + timedelta(seconds=1)

        engine.reconcile_clock()
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p2', 'submit_decision', {'selected': ['decline']})

        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'no_response_card')
        self.assertEqual(engine.engine_state['pending_decision']['owner'], 'p1')

    def test_no_response_chooser_receives_card_images_without_hand_leak(self):
        p1 = attack('p1-ready', 'p1')
        p2 = attack('p2-secret', 'p2')
        p2.update({'card_id': 42, 'img': '/media/cards/p2-secret.webp'})
        engine = self.make_engine([p1], [p2])
        self.enter_ready(engine)
        self.act(engine, 'p1', 'ready_card')
        deadline = datetime.fromisoformat(engine.engine_state['clock']['deadline'])
        engine.now = deadline + timedelta(seconds=1)

        engine.reconcile_clock()

        chooser = engine.observe('p1')
        decision_action = next(
            action for action in chooser['legal_actions']
            if action['type'] == 'submit_decision'
        )
        option_card = decision_action['options'][0]['card']
        self.assertEqual(option_card['card_id'], 42)
        self.assertEqual(option_card['img'], '/media/cards/p2-secret.webp')
        self.assertTrue(all(
            card.get('hidden')
            for card in chooser['state']['players']['p2']['zones']['hand']
        ))

        non_chooser = engine.observe('p2')
        self.assertNotIn('options', non_chooser['pending_decision'])

