    def test_policy_self_play_completes_through_public_engine_api(self):
        state = base_state()
        cards = []
        for side in ('p1', 'p2'):
            side_cards = [
                attack(f'{side}-{index}', side, frame=4 + index % 5, damage=200 + index * 20)
                for index in range(14)
            ]
            state['players'][side]['zones']['hand'] = side_cards[:5]
            state['players'][side]['zones']['list'] = side_cards[5:]
            cards.extend(side_cards)

        result = run_policy_game(state, ruleset(*cards), seed='self-play-test', max_commands=500)

        self.assertTrue(result.completed, result.error)
        self.assertIn(result.winner, ('p1', 'p2'))

    def test_policy_self_play_quarantines_effect_resolution_error(self):
        card = attack('broken-effect', 'p1')
        broken_ruleset = ruleset(card)
        broken_ruleset['cards'][card['code']]['effect_definition'] = {
            'schema_version': 1,
            'abilities': [{
                'id': 'broken-choice', 'kind': 'effect', 'mode': 'mandatory',
                'timing': 'function', 'visibility': 'public',
                'active_zones': ['hand'], 'trigger': {'event': 'phase_start'},
                'effects': [{'op': 'choose_effect', 'options': []}],
            }],
        }
        state = base_state([card], [])

        result = run_policy_game(state, broken_ruleset, seed='broken-effect')

        self.assertFalse(result.completed)
        self.assertEqual(result.reason, 'engine_error')
        self.assertIn('EffectResolutionError', result.error)

    def test_self_play_evaluation_pairs_the_same_seed_across_both_seats(self):
        p1 = attack('p1-ai', 'p1', code='AI-P1', frame=5, damage=400)
        p2 = attack('p2-ai', 'p2', code='AI-P2', frame=5, damage=400)

        metrics = _evaluate_candidate(
            base_state([p1], [p2], hp=800),
            ruleset(p1, p2),
            DEFAULT_POLICY_WEIGHTS,
            DEFAULT_POLICY_WEIGHTS,
            games=4,
            seed='paired-evaluation',
        )

        self.assertEqual(metrics['score'], 0.5)
        self.assertEqual(metrics['incomplete'], 0)

    def test_self_play_evaluation_rotates_training_states_by_seat_pair(self):
        states = [
            {**base_state(), 'corpus_marker': marker}
            for marker in ('first', 'second')
        ]
        completed = SimpleNamespace(
            completed=True, winner=None, commands=10, reason='', error='',
        )

        with patch(
            'battlelog.game.training.run_policy_game', return_value=completed,
        ) as runner:
            metrics = _evaluate_candidate(
                states, {}, DEFAULT_POLICY_WEIGHTS, DEFAULT_POLICY_WEIGHTS,
                games=8, seed='corpus-evaluation',
            )

        self.assertEqual(
            [call.args[0]['corpus_marker'] for call in runner.call_args_list],
            ['first', 'first', 'second', 'second'] * 2,
        )
        self.assertEqual(metrics['training_state_count'], 2)

    def test_current_policy_replays_better_than_v12_across_paired_seats(self):
        previous_weights = importlib.import_module(
            'battlelog.migrations.0026_seed_trained_ai_policy'
        ).WEIGHTS
        state = base_state()
        cards = []
        for side in ('p1', 'p2'):
            side_cards = [
                attack(
                    f'{side}-benchmark-{index}', side,
                    frame=4 + index % 5, damage=200 + index * 20,
                )
                for index in range(14)
            ]
            state['players'][side]['zones']['hand'] = side_cards[:5]
            state['players'][side]['zones']['list'] = side_cards[5:]
            cards.extend(side_cards)

        metrics = _evaluate_candidate(
            state,
            ruleset(*cards),
            DEFAULT_POLICY_WEIGHTS,
            previous_weights,
            games=20,
            seed='sudden-fixed-selfplay-20260818:evaluation',
        )

        self.assertEqual(metrics['incomplete'], 0)
        self.assertGreater(metrics['score'], 0.5)
        self.assertEqual(
            (metrics['wins'], metrics['losses'], metrics['draws']),
            (7, 5, 8),
        )

