    def test_rulebook_verification_rejects_wrong_page_count(self):
        from pypdf import PdfWriter

        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'rulebook.pdf'
            writer = PdfWriter()
            writer.add_blank_page(width=100, height=100)
            writer.add_blank_page(width=100, height=100)
            with path.open('wb') as output:
                writer.write(output)
            digest = hashlib.sha256(path.read_bytes()).hexdigest().upper()

            with (
                patch('battlelog.game.catalog.RULEBOOK_SHA256', digest),
                patch('battlelog.game.catalog.RULEBOOK_PAGE_COUNT', 3),
                self.assertRaisesRegex(ValueError, '페이지 수가 다릅니다'),
            ):
                verify_rulebook_source(path)

