    def test_effect_draft_compiles_only_common_safe_commands(self):
        commands = infer_effect_commands(
            '판정 전, 2FP를 얻고 300데미지를 받는다. 그 후, 이 기술을 브레이크한다.',
        )
        restrictions = infer_effect_commands(
            '상대는 이 기술을 방어 및 상쇄할 수 없다.',
            continuous=True,
        )

        self.assertEqual(
            [command['op'] for command in commands],
            ['change_fp', 'deal_damage', 'break_card'],
        )
        self.assertEqual([command['kind'] for command in restrictions], ['guard', 'clash'])
        self.assertTrue(all(command['duration'] == 'continuous' for command in restrictions))

        opponent_fp = infer_effect_commands('상대는 4FP를 얻는다.')
        counters = infer_effect_commands('[[token:howling]]카운터를 2개 올린다.(최대 5개)')
        self.assertEqual(opponent_fp[0]['player'], {'opponent': True})
        self.assertEqual(counters[0]['counter'], 'howling')
        self.assertEqual(counters[0]['max'], 5)

        movement = infer_effect_commands('리스트에서 기술 1장을 루멘 존으로 보낸다.')
        breaking = infer_effect_commands('루멘 존에 있는 기술 2장을 브레이크한다.')
        self.assertEqual(movement[0]['selector']['zones'], ['list'])
        self.assertEqual(movement[0]['then'][0]['to_zone'], 'lumen')
        self.assertEqual(breaking[0]['selector']['zones'], ['lumen'])
        self.assertEqual(breaking[0]['then'][0]['op'], 'break_card')

        random_discard = infer_effect_commands('상대는 패 1장을 무작위로 버린다.')
        self.assertEqual([command['op'] for command in random_discard], ['random_select', 'discard'])
        self.assertEqual(random_discard[0]['selector']['player'], {'opponent': True})
        self.assertEqual(random_discard[0]['selection_key'], random_discard[1]['selection_key'])

        repeated = infer_effect_commands('카운터 시 상대에게 100데미지를 2번 준다.')
        self.assertEqual(repeated, [{
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': 100, 'repeat': 2,
        }])

