        self.assertEqual(engine.engine_state['card_use_history'][0]['use_context'], 'ready')
        self.assertEqual(definition['catch_rules'][0]['fixed_speed'], 2)
        self.assertEqual(definition['catch_rules'][0]['condition']['op'], 'used_card')
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

