    def test_dodge_and_clash_rules_support_speed_damage_body_and_hit_gates(self):
        combined = infer_defense_rules(
            '이 기술은 <8속도 이하, 500데미지 이하>기술만 상쇄할 수 있다.',
        )
        shared = infer_defense_rules(
            '이 기술은 9속도 이하 기술만 회피 및 상쇄할 수 있다.',
        )
        body_gate = infer_defense_rules(
            '이 기술은 <손>판정 기술만 상쇄한다.',
        )
        hit_gate = infer_defense_rules(
            '이 기술은 히트 판정이 <+4>이상, 또는 <콤보>인 기술을 회피할 수 있다.',
        )
        conditional = infer_defense_rules(
            '이 기술은 5속도 이하 기술만 회피할 수 있다. '
            '①[[state:harmony]]: 이 기술은 10속도 이하 기술만 회피할 수 있다.',
        )

        self.assertEqual(combined, [{
            'judgment': 'clash', 'max_speed': 8, 'max_damage': 500,
        }])
        self.assertIn({'max_speed': 9}, shared)
        self.assertIn({'judgment': 'clash', 'max_speed': 9}, shared)
        self.assertEqual(body_gate, [{
            'judgment': 'clash', 'where': {'body': '손'},
        }])
        self.assertEqual(hit_gate, [
            {'judgment': 'dodge', 'min_hit': 4},
            {'judgment': 'dodge', 'hit_values': ['콤보']},
        ])
        self.assertEqual(conditional, [
            {'max_speed': 5},
            {
                'max_speed': 10,
                'condition': {
                    'op': 'has_state', 'player': {'controller': True},
                    'state': 'harmony',
                },
            },
        ])

    def test_clash_gate_is_applied_to_attack_card_special_judgment(self):
        clashing = attack(
            'clashing', 'p1', code='CLASHING', frame=10, damage=400,
            position='상단', special='상단 상쇄',
        )
        allowed = attack(
            'allowed', 'p2', code='ALLOWED', frame=8, damage=500,
            position='상단',
        )
        too_fast = attack(
            'too-fast', 'p2', code='TOO-FAST', frame=9, damage=500,
            position='상단',
        )
        wrong_body = attack(
            'wrong-body', 'p2', code='WRONG-BODY', frame=8, damage=500,
            position='상단',
        )
        allowed['body'] = '손'
        too_fast['body'] = '손'
        wrong_body['body'] = '발'
        release = ruleset(clashing, allowed, too_fast, wrong_body)
        definition = build_effect_draft(
            'CLASHING',
            '이 기술은 <8속도 이하, 500데미지 이하 손 판정>기술만 상쇄할 수 있다.',
        )
        release['cards']['CLASHING']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(
            base_state([], []), release, seed='clash-gate',
        )

        self.assertTrue(engine._defense_judgment_allowed(
            clashing, allowed, 'clash', 'p2',
        ))
        self.assertFalse(engine._defense_judgment_allowed(
            clashing, too_fast, 'clash', 'p2',
        ))
        self.assertFalse(engine._defense_judgment_allowed(
            clashing, wrong_body, 'clash', 'p2',
        ))
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

