    def test_opponent_card_effect_immunity_blocks_stat_move_and_rule_effects(self):
        protected = attack('protected', 'p1', code='PROTECTED', damage=400)
        enemy = attack('enemy', 'p2', code='ENEMY')
        release = ruleset(protected, enemy)
        release['cards']['PROTECTED']['effect_definition'] = build_effect_draft(
            'PROTECTED', '이 기술은 상대 기술의 영향을 받지 않는다.',
        )
        engine = AutomaticGameEngine.initialize(
            base_state([protected], [enemy]), release, seed='opponent-immunity',
        )
        live = engine._find_card('protected')
        engine.add_modifier({
            'op': 'modify_stat', 'stat': 'damage', 'amount': 300,
            'controller': 'p2', 'player': 'p1', 'source': 'enemy',
        })
        engine.engine_state['replacements'].append({
            'op': 'prevent', 'kind': 'use_card', 'controller': 'p2',
            'player': 'p1', 'source': 'enemy', 'duration': 'continuous',
        })

        self.assertEqual(engine.card_stat(live, 'damage', 'p1'), 400)
        self.assertFalse(engine._rule_blocked('use_card', 'p1', live))
        self.assertIsNone(engine.move_card(
            'protected', 'list', reason='effect', effect_controller='p2',
            effect_source='enemy',
        ))
        self.assertIsNotNone(engine._find_card('protected', owner='p1', zone='hand'))
        self.assertEqual(engine.events[-1]['type'], 'card_effect_ignored')

        engine.add_modifier({
            'op': 'modify_stat', 'stat': 'damage', 'amount': 100,
            'controller': 'p1', 'player': 'p1', 'source': 'protected',
        })
        self.assertEqual(engine.card_stat(live, 'damage', 'p1'), 500)

