        release = ruleset(direct, enemy_protected, enemy)
        release['cards']['DIRECT']['effect_definition'] = build_effect_draft(
            'DIRECT', '이 기술은 자신이 직접 브레이크할 수 없다.',
        )
        release['cards']['ENEMY-PROTECTED']['effect_definition'] = build_effect_draft(
            'ENEMY-PROTECTED', '이 기술은 상대 기술의 효과로 브레이크 되지 않는다.',
        )
        engine = AutomaticGameEngine.initialize(
            base_state([direct, enemy_protected], [enemy]), release,
            seed='break-scopes',
        )

        self.assertIsNone(engine.break_card(
            'direct', reason='direct', direct_controller='p1',
        ))
        self.assertIsNotNone(engine._find_card('direct', owner='p1', zone='hand'))
        self.assertIsNotNone(engine.break_card('direct', reason='core'))
        self.assertIsNone(engine.break_card(
            'enemy-protected', reason='effect', effect_controller='p2',
            effect_source='enemy',
        ))
        self.assertIsNotNone(engine._find_card(
            'enemy-protected', owner='p1', zone='hand',
        ))
        self.assertIsNotNone(engine.break_card(
            'enemy-protected', reason='effect', effect_controller='p1',
            effect_source='direct',
        ))

