    def test_jump_exact_review_covers_defense_fp_and_break_qnas(self):
        text = (
            '중단은 <7속도>이하 기술 회피할 수 있다.\n'
            '①회피 시, 상대의 기술 속도-2만큼 FP를 얻는다.(최대 8FP)\n'
            '②사용 후, 상대 기술에 <그랩>판정이 있는 경우 '
            '이 기술과 해당 기술을 브레이크한다.'
        )
        definition = build_effect_draft(
            'ST1-014', text, qna_ids=[69, 655, 656],
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'ST1-014', 'name': '점프', 'type': '수비',
                'text': text, 'frame': None, 'damage': None, 'pos': None,
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 3)
        self.assertTrue(all(
            len(ability.scenarios) >= 3 and ability.passed
            for ability in result.abilities
        ))
        fp_names = {
            scenario['name'] for scenario in result.abilities[1].scenarios
        }
        break_names = {
            scenario['name'] for scenario in result.abilities[2].scenarios
        }
        self.assertIn('qna-655-speed-eight-gains-six', fp_names)
        self.assertIn('qna-656-protected-opponent-cancels-both', break_names)
        self.assertIn('qna-69-grab-negation-skips-after-use', break_names)
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

