    def test_phase_skip_specific_card_movement_and_counter_groups_are_structured(self):
        own_get = infer_effect_commands(
            '사용 후, 이번 턴 자신의 겟 페이즈를 스킵한다.',
        )
        both_get = infer_effect_commands(
            '이 카드의 브레이크 시, 이번 턴 서로의 겟 페이즈를 스킵한다.',
        )
        next_both_lumen = infer_effect_commands(
            '그 경우, 다음 턴 서로의 루멘 페이즈를 스킵한다.',
        )
        next_own_lumen = infer_effect_commands(
            '상태 해제 시, 다음 자신 루멘 페이즈를 스킵한다.',
        )
        placement = infer_effect_commands(
            '히트 시, 사이드 덱에서 [[card:LMI-AT-041]] 1장을 루멘 존에 배치할 수 있다.',
        )
        source_move = infer_effect_commands(
            '루멘 페이즈 시, 이 기술을 얼티밋 존에서 루멘 존에 배치할 수 있다.',
        )
        counters = infer_effect_commands(
            '사용 후, [[token:yin]], [[token:yang]]카운터를 각각 2개씩 제거한다.',
        )
        clear = infer_effect_commands(
            '판정 전, 상대 기술의 특수 판정을 제거한다.',
        )

        self.assertEqual(own_get, [{
            'op': 'skip_get', 'player': {'controller': True},
        }])
        self.assertEqual([command['player'] for command in both_get], [
            {'controller': True}, {'opponent': True},
        ])
        self.assertTrue(all(command['op'] == 'skip_get' for command in both_get))
        self.assertEqual(next_both_lumen, [
            {
                'op': 'skip_phase', 'player': {'controller': True},
                'phase': 'lumen',
            },
            {
                'op': 'skip_phase', 'player': {'opponent': True},
                'phase': 'lumen',
            },
        ])
        self.assertEqual(next_own_lumen, [{
            'op': 'skip_phase', 'player': {'controller': True},
            'phase': 'lumen',
        }])
        self.assertEqual(placement[0]['selector']['where'], {'code': 'LMI-AT-041'})
        self.assertEqual(placement[0]['selector']['zones'], ['side'])
        self.assertEqual(placement[0]['then'][0]['to_zone'], 'lumen')
        self.assertEqual(source_move, [{'op': 'move_card', 'to_zone': 'lumen'}])
        self.assertEqual([(command['counter'], command['amount']) for command in counters], [
            ('yin', -2), ('yang', -2),
        ])
        self.assertEqual(clear, [{
            'op': 'modify_judgment', 'player': {'opponent': True},
            'field': 'special', 'value': '', 'mode': 'clear',
        }])

