    def test_speed_use_block_and_character_body_damage_filter_execute(self):
        fast = attack('fast', 'p1', frame=12)
        slow = attack('slow', 'p1', frame=11)
        matching = attack('matching', 'p1', frame=6, damage=400)
        matching.update({'character_key': 'wolf', 'body': '손'})
        wrong = attack('wrong', 'p1', frame=6, damage=400)
        wrong.update({'character_key': 'wolf', 'body': '발'})
        engine = self.make_engine([fast, slow, matching, wrong], [])
        commands = infer_effect_commands(
            '사용 후, 이번 턴 자신은 <12속도 이상>기술을 사용할 수 없으며 '
            '이번 턴 종료 시까지 <[[character:wolf]] 손>판정 기술 데미지+100',
        )
        for command in commands:
            engine.resolver.execute_effect(command, {'controller': 'p1'})

        self.assertFalse(engine._card_use_allowed(fast, 'p1', 'ready'))
        self.assertTrue(engine._card_use_allowed(slow, 'p1', 'ready'))
        self.assertEqual(engine.card_stat(matching, 'damage', 'p1'), 500)
        self.assertEqual(engine.card_stat(wrong, 'damage', 'p1'), 400)
        self.assertEqual([item['op'] for item in commands], ['prevent', 'modify_stat'])

