    def test_combo_end_and_opponent_combo_end_resolve_for_the_correct_owner(self):
        own = attack('own-end', 'p1', code='OWN-END')
        opposing = attack('opposing-end', 'p2', code='OPPOSING-END')
        state = base_state([], [])
        state['players']['p1']['zones']['lumen'].append(own)
        state['players']['p2']['zones']['lumen'].append(opposing)
        release = ruleset(own, opposing)
        release['cards']['OWN-END']['effect_definition'] = build_effect_draft(
            'OWN-END', '①콤보 타임 종료 시, 1FP를 얻는다.',
        )
        release['cards']['OPPOSING-END']['effect_definition'] = build_effect_draft(
            'OPPOSING-END', '①상대의 콤보 타임 종료 후, 2FP를 얻는다.',
        )
        engine = AutomaticGameEngine.initialize(state, release, seed='combo-end-events')
        engine.grant_combo('p1')

        engine.end_combo()
        pipeline = engine.engine_state['pipeline']
        self.assertEqual(pipeline['kind'], 'combo_end')
        engine._advance_combo_end_pipeline(pipeline)
        engine.resolver.drain()
        engine._advance_combo_end_pipeline(pipeline)
        engine.resolver.drain()

        self.assertEqual(engine.state['players']['p1']['fp'], 1)
        self.assertEqual(engine.state['players']['p2']['fp'], 2)
        self.assertEqual(
            release['cards']['OWN-END']['effect_definition']['abilities'][0]['trigger']['event'],
            'combo_end',
        )
        self.assertEqual(
            release['cards']['OPPOSING-END']['effect_definition']['abilities'][0]['trigger']['event'],
            'opponent_combo_end',
        )

