        self.assertEqual(kiss['supplements'][0]['same_name_limit'], 3)
        self.assertEqual(no_minimum['character_card_minimum'], 0)
        self.assertEqual(chimera['main_size'], {'min': 30, 'max': 30})
        self.assertEqual(chimera['other_character_cards']['allowed_types'], ['공격'])
        self.assertEqual(chimera['other_character_cards']['max_per_character'], 3)
        self.assertTrue(chimera['other_character_cards']['negate_effects'])
        definition = build_effect_draft('CB02-PS-001', '[[character:chimera]]는 덱에 기술을 10장 추가로 편성한다.')
