    def test_imported_character_card_rules_negate_and_break_the_card(self):
        imported = attack('imported-card', 'p1', code='IMPORTED')
        opponent_card = attack('opponent-card', 'p2', code='OPPONENT')
        state = base_state([imported], [opponent_card])
        state['players']['p1']['character'] = {'id': 15}
        state['players']['p2']['character'] = {'id': 2}
        release = ruleset(imported, opponent_card)
        release['cards']['IMPORTED']['character_id'] = 3
        release['cards']['IMPORTED']['effect_definition'] = build_effect_draft(
            'IMPORTED', '①사용 시, 5FP를 얻는다.',
        )
        release['characters'] = {
            '2': {'id': 2, 'key': 'opponent'},
            '3': {'id': 3, 'key': 'foreign'},
            '15': {
                'id': 15,
                'key': 'chimera',
                'deck_rules': {
                    'other_character_cards': {
                        'allowed_types': ['공격'],
                        'exclude_ultimate': True,
                        'exclude_character_ids': [1],
                        'max_per_character': 3,
                        'treat_as_own_character': True,
                        'negate_effects': True,
                        'break_after_use': True,
                    },
                },
            },
        }
        engine = AutomaticGameEngine.initialize(
            state, release,
            now=datetime(2026, 8, 17, tzinfo=timezone.utc), seed='imported-rule',
        )
        live = engine._find_card('imported-card')

        self.assertEqual(live['original_character_id'], 3)
        self.assertEqual(live['character_id'], 15)
        self.assertEqual(live['character_key'], 'chimera')
        self.assertTrue(live['effects_negated'])
        self.assertEqual(engine._definition_for_card(live), {})

        engine.move_card('imported-card', 'battle', reason='test')
        engine.engine_state['battle'] = {
            'p1': {'instance_id': 'imported-card', 'card': live},
        }
        engine._cleanup_battle()
        while engine._continue():
            pass
        self.assertIn(
            'imported-card',
            [card['instance_id'] for card in engine.state['players']['p1']['zones']['break']],
        )

    def test_common_optional_movement_healing_and_prohibitions_are_structured(self):
        placement = infer_effect_commands(
            '히트 시, 사이드 덱에서 [[card:RFS-AT-002]]을 2장까지 루멘 존에 배치할 수 있다.',
        )
        healing = infer_effect_commands('히트 시, 체력 400을 회복한다.')
        source_move = infer_effect_commands('히트 시, 이 기술을 루멘 존에 배치할 수 있다.')
        counter_clear = infer_effect_commands(
            '사용 후, [[token:yin]]카운터를 모두 제거한다.',
        )

        self.assertEqual(placement[0]['selector']['min'], 0)
        self.assertEqual(placement[0]['selector']['max'], 2)
        self.assertEqual(placement[0]['selector']['where'], {'code': 'RFS-AT-002'})
        self.assertEqual(healing[0]['op'], 'change_hp')
        self.assertEqual(healing[0]['amount'], 400)
        self.assertEqual(source_move, [{'op': 'move_card', 'to_zone': 'lumen'}])
        self.assertEqual(counter_clear[0]['op'], 'set_counter')

        for text, kinds in (
            ('이 기술은 상대가 방어 및 상쇄할 수 없다.', {'guard', 'clash'}),
            ('상대는 이 기술을 특수 판정으로 회피 및 상쇄할 수 없다.', {'dodge', 'clash'}),
            ('이 기술은 회피할 수 없다.', {'dodge'}),
        ):
            commands = infer_effect_commands(text, continuous=True)
            self.assertEqual({command['kind'] for command in commands}, kinds)

    def test_blue_flame_fp_is_delayed_until_recovery_and_uses_named_lumen_count(self):
        source = attack('blue-flame-source', 'p1', code='CB03-AT-027')
        lumen_cards = [
            attack(f'blue-flame-lumen-{index}', 'p1', code='RFS-AT-002')
            for index in range(4)
        ]
        unrelated = attack('blue-flame-unrelated', 'p1', code='OTHER')
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        state['players']['p1']['zones']['lumen'] = [*lumen_cards, unrelated]
        definition = build_effect_draft(
            'CB03-AT-027',
            '①판정 전, 체력 200을 지불한다. 그 후, <7속도 이상 중단 회피 '
            '특수 판정을 추가한다.\n'
            '②[[state:blue_flame]]: 히트/카운터/콤보 시, 이번 턴 리커버리 '
            '페이즈에 루멘 존의 [[card:RFS-AT-002]] 1장당 1FP를 얻는다. (최대 3)',
        )
        release = ruleset(source, *lumen_cards, unrelated)
        release['cards']['CB03-AT-027']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='blue-flame-recovery')
        engine.state['phase'] = 'battle'
        engine.set_passive('p1', 'blue_flame', value=True)

        engine._fire('hit', {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
        })

        self.assertEqual(engine.state['players']['p1']['fp'], 0)
        self.assertEqual(len(engine.engine_state['scheduled']), 1)
        engine.state['phase'] = 'recovery'
        engine._fire('phase_start', {'phase': 'recovery'})
        self.assertEqual(engine.state['players']['p1']['fp'], 3)
        self.assertEqual(engine.engine_state['scheduled'], [])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_repeating_schedule_applies_to_each_matching_use_and_expires(self):
        source = attack('repeating-schedule-source', 'p1')
        first = attack(
            'repeating-schedule-first', 'p1', code='RFS-AT-002', damage=500,
        )
        second = attack(
            'repeating-schedule-second', 'p1', code='RFS-AT-002', damage=500,
        )
        opponent_card = attack(
            'repeating-schedule-opponent', 'p2', code='RFS-AT-002', damage=500,
        )
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source, first, second]
        state['players']['p2']['zones']['battle'] = [opponent_card]
        engine = AutomaticGameEngine.initialize(
            state, ruleset(source, first, second, opponent_card),
            seed='repeating-schedule',
        )
        schedule = {
            'op': 'schedule',
            'when': {
                'event': 'use', 'controller': 'self',
                'where_event_card': {'code': 'RFS-AT-002'},
            },
            'duration': 'turn', 'repeat': True,
            'effect': {
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'damage', 'amount': 100, 'duration': 'battle',
            },
        }
        engine.resolver.execute_effect(schedule, {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
        })

        engine._fire('use', {
            'controller': 'p1', 'source_card': first,
            'source_card_instance_id': first['instance_id'],
        })
        engine._fire('use', {
            'controller': 'p2', 'source_card': opponent_card,
            'source_card_instance_id': opponent_card['instance_id'],
        })
        engine._fire('use', {
            'controller': 'p1', 'source_card': second,
            'source_card_instance_id': second['instance_id'],
        })

        self.assertEqual(engine.card_stat(first, 'damage', 'p1'), 600)
        self.assertEqual(engine.card_stat(second, 'damage', 'p1'), 600)
        self.assertEqual(engine.card_stat(opponent_card, 'damage', 'p2'), 500)
        self.assertEqual(len(engine.engine_state['scheduled']), 1)
        engine._expire_modifiers('turn')
        self.assertEqual(engine.engine_state['scheduled'], [])
        self.assertEqual(validate_effect_definition({
            'schema_version': 1, 'reviewed': False, 'draft': True,
            'no_effect': False, 'source_refs': {'rulebook_pages': [1]},
            'abilities': [{
                'id': 'repeating-schedule-test', 'label': '반복 예약',
                'kind': 'effect', 'mode': 'mandatory', 'timing': 'hit_counter',
                'visibility': 'public',
                'source_refs': {'rulebook_pages': [1]},
                'trigger': {'event': 'hit'}, 'effects': [schedule],
            }],
        }, card_has_text=True), [])

    def test_temporary_combo_judgment_restores_at_battle_expiration(self):
        card = attack(
            'temporary-judgment-card', 'p1', code='RFS-AT-002', hit='3',
        )
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [card]
        engine = AutomaticGameEngine.initialize(
            state, ruleset(card), seed='temporary-judgment',
        )
        live = engine._find_card(card['instance_id'], owner='p1', zone='battle')
        engine.engine_state['pipeline'] = {
            'kind': 'combo_resolution', 'owner': 'p1',
            'card_instance_id': card['instance_id'],
            'card': copy.deepcopy(live),
        }

        self.assertTrue(engine.modify_judgment(
            'p1', 'hit', '+1', source=card['instance_id'], duration='battle',
        ))
        self.assertEqual(live['hit'], '+1')
        self.assertEqual(engine.engine_state['pipeline']['card']['hit'], '+1')
        engine._expire_modifiers('battle')
        self.assertEqual(live['hit'], '3')
        self.assertEqual(engine.engine_state['pipeline']['card']['hit'], '3')
        self.assertEqual(engine.engine_state['temporary_judgments'], [])

