    def test_thermodynamics_uses_live_hp_and_lumen_counts_then_cleans_up_at_turn_end(self):
        source = attack('thermo-source', 'p1', code='DFR-AT-012')
        ready_attack = attack('thermo-ready-attack', 'p1', damage=400)
        ready_defense = defense('thermo-ready-defense', 'p1')
        lumen_cards = [
            attack(f'thermo-lumen-{index}', 'p1') for index in range(2)
        ]
        state = base_state([ready_attack, ready_defense], [], hp=1500)
        state['players']['p1']['zones']['ultimate'] = [source]
        state['players']['p1']['zones']['lumen'] = lumen_cards
        state['players']['p1']['passive_state']['over_limit'] = {
            'value': True, 'label': 'over_limit',
        }
        release = ruleset(
            source, ready_attack, ready_defense, *lumen_cards,
        )
        definition = build_effect_draft(
            'DFR-AT-012',
            '①루멘 페이즈 시, 자신의 체력이 2000 이하라면 600데미지를 받고 '
            '얼티밋 존의 이 기술을 브레이크할 수 있다.\n'
            '그 경우 이하의 효과를 적용한다.\n'
            '-이번 턴 배틀 페이즈 종료 시까지 [[state:over_limit]]이 해제되지 않는다.\n'
            '-루멘 존의 기술 1장당 1FP를 얻는다.\n'
            '-이번 턴 레디하는 공격 기술의 기술 데미지+300 자신의 체력이 '
            '1000 이하일 경우 대신+600\n'
            '-이번 턴 종료 시, 루멘 존의 기술을 모두 리스트로 보낸다. '
            '그 후, 보낸 기술 1장당 200데미지를 받는다.',
        )
        release['cards']['DFR-AT-012']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='thermodynamics')

        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.assertEqual(engine.state['players']['p1']['hp'], 900)
        self.assertEqual(engine.state['players']['p1']['fp'], 2)
        self.assertIsNotNone(engine._find_card(source['instance_id'], owner='p1', zone='break'))

        engine._fire('ready', {
            'controller': 'p1', 'source_card': ready_defense,
            'source_card_instance_id': ready_defense['instance_id'],
        })
        self.assertEqual(len(engine.engine_state['scheduled']), 2)
        engine._fire('ready', {
            'controller': 'p1', 'source_card': ready_attack,
            'source_card_instance_id': ready_attack['instance_id'],
        })
        self.assertEqual(engine.card_stat(
            engine._find_card(ready_attack['instance_id']), 'damage', 'p1',
        ), 1000)
        self.assertEqual(len(engine.engine_state['scheduled']), 1)

        self.assertFalse(engine.set_passive('p1', 'over_limit', value=False))
        self.assertTrue(engine.state['players']['p1']['passive_state']['over_limit']['value'])
        engine._complete_turn()
        self.assertEqual(engine.state['players']['p1']['hp'], 500)
        self.assertTrue(all(
            engine._find_card(card['instance_id'], owner='p1', zone='list')
            for card in lumen_cards
        ))
        engine._expire_modifiers('battle')
        self.assertTrue(engine.set_passive('p1', 'over_limit', value=False))
        self.assertFalse(engine.state['players']['p1']['passive_state']['over_limit']['value'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

