    def test_exact_token_cost_precedes_optional_judgment_branch(self):
        source = attack('dagger-source', 'p1', code='CB02-AT-030')
        opponent_card = attack('dagger-opponent', 'p2', hit='+3')
        tokens = [
            {
                'instance_id': f'dagger-token-{index}', 'kind': 'token',
                'owner': 'p1', 'code': f'DAGGER-{index}',
                'name': 'Dagger', 'token_key': 'dagger', 'face_up': True,
            }
            for index in range(2)
        ]
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        state['players']['p2']['zones']['battle'] = [opponent_card]
        state['players']['p1']['zones']['lumen'] = tokens
        release = ruleset(source, opponent_card, *tokens)
        definition = build_effect_draft(
            'CB02-AT-030',
            '①히트 및 카운터 시, 루멘 존의 [[token:dagger]]토큰 2장을 '
            '브레이크할 수 있다.\n그 경우, 이하의 효과 중 하나를 적용한다.\n'
            '-이 기술의 히트 및 카운터 판정을 <콤보>로 변경한다.\n'
            '-상대 기술의 히트 판정을 <+0>으로 변경한다.',
        )
        release['cards']['CB02-AT-030']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='dagger-cost')
        engine.state['phase'] = 'battle'
        engine.engine_state['battle'] = {
            'p1': {'instance_id': source['instance_id'], 'card': source},
            'p2': {
                'instance_id': opponent_card['instance_id'],
                'card': opponent_card,
            },
        }

        engine._fire('hit', {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
            'opponent_card': opponent_card,
        })
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.act(engine, 'p1', 'submit_decision', {
            'selected': [token['instance_id'] for token in tokens],
        })
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'effect_branch')
        self.act(engine, 'p1', 'submit_decision', {
            'selected': ['opponent_zero'],
        })

        self.assertTrue(all(
            engine._find_card(token['instance_id'], owner='p1', zone='break')
            for token in tokens
        ))
        self.assertEqual(engine.engine_state['battle']['p2']['card']['hit'], '+0')
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

        rfs = build_effect_draft(
            'RFS-AT-039',
            '①히트 시, 루멘 존의 [[token:dagger]]토큰 3장을 브레이크할 수 있다.\n'
            '그 경우, 상대 기술의 히트 판정을 <+2>로 변경한다.',
        )
        pmp = build_effect_draft(
            'PMP-AT-010',
            '②방어 시, 루멘 존의 [[token:spider]]토큰 8장을 브레이크할 수 있다.\n'
            '그 경우, 자신은 3콤보까지 콤보 타임을 할 수 있다.',
        )
        self.assertEqual(rfs['abilities'][0]['condition']['min'], 3)
        pmp_spider_condition = next(
            condition
            for condition in pmp['abilities'][0]['condition']['conditions']
            if condition.get('op') == 'zone_count'
        )
        self.assertEqual(pmp_spider_condition['min'], 8)
        self.assertEqual(validate_effect_definition(rfs, card_has_text=True), [])
        self.assertEqual(validate_effect_definition(pmp, card_has_text=True), [])

