    def test_next_catch_modifier_waits_for_its_controller_and_expires(self):
        catch_card = attack('catch-card', 'p1', code='RFS-AT-002', damage=300)
        wrong_own_card = attack('wrong-own-catch', 'p1', code='WRONG-CATCH', damage=300)
        opponent_card = attack('opponent-catch', 'p2', code='OTHER-CATCH', damage=300)
        engine = self.make_engine([catch_card, wrong_own_card], [opponent_card])
        command = infer_effect_commands(
            '회피 시, 이번 턴 다음에 캐치하는 [[card:RFS-AT-002]] 1장의 데미지+200',
        )[0]

        self.assertEqual(command['op'], 'schedule')
        self.assertEqual(command['when'], {
            'event': 'catch', 'controller': 'self',
            'where_event_card': {'code': 'RFS-AT-002'},
        })
        engine.resolver.execute_effect(command, {'controller': 'p1'})
        engine._fire('catch', {
            'controller': 'p2', 'source_card': opponent_card,
            'source_card_instance_id': 'opponent-catch',
        })
        self.assertEqual(len(engine.engine_state['scheduled']), 1)
        self.assertEqual(engine.card_stat(catch_card, 'damage', 'p1'), 300)

        engine._fire('catch', {
            'controller': 'p1', 'source_card': wrong_own_card,
            'source_card_instance_id': 'wrong-own-catch',
        })
        self.assertEqual(len(engine.engine_state['scheduled']), 1)
        self.assertEqual(engine.card_stat(wrong_own_card, 'damage', 'p1'), 300)

        engine._fire('catch', {
            'controller': 'p1', 'source_card': catch_card,
            'source_card_instance_id': 'catch-card',
        })
        self.assertEqual(engine.engine_state['scheduled'], [])
        self.assertEqual(engine.card_stat(catch_card, 'damage', 'p1'), 500)

        engine.resolver.execute_effect(command, {'controller': 'p1'})
        engine._expire_modifiers('turn')
        self.assertEqual(engine.engine_state['scheduled'], [])

    def test_delayed_ready_block_and_recovery_break_fire_at_declared_windows(self):
        source = attack('source-card', 'p1', code='SOURCE-CARD')
        named = attack('named-card', 'p1', code='NAMED-CARD')
        named['name'] = '엔드리스 발라레'
        engine = self.make_engine([source, named], [])
        ready_command = infer_effect_commands(
            '사용 후, 다음 턴 레디 페이즈에서 이 기술을 사용할 수 없다.',
        )[0]
        break_command = infer_effect_commands(
            '사용 시, 이번 턴 리커버리 페이즈 종료 시에 '
            '패/리스트/사이드 덱의 [엔드리스 발라레]를 브레이크한다.',
        )[0]

        engine.resolver.execute_effect(ready_command, {
            'controller': 'p1', 'source_card_instance_id': 'source-card',
        })
        engine.resolver.execute_effect(break_command, {
            'controller': 'p1', 'source_card_instance_id': 'source-card',
        })
        self.assertEqual(len(engine.engine_state['scheduled']), 2)
        engine._fire('turn_start', {'turn': 2})
        self.assertFalse(engine._legal_ready_card(source))
        self.assertIsNotNone(engine._find_card('named-card', owner='p1', zone='hand'))

        engine.state['phase'] = 'recovery'
        engine._fire('phase_end', {'phase': 'recovery'})
        self.assertIsNotNone(engine._find_card('named-card', owner='p1', zone='break'))
        self.assertEqual(engine.engine_state['scheduled'], [])

    def test_random_opponent_hand_card_returns_from_lumen_at_recovery(self):
        stolen = attack('stolen-card', 'p2', code='STOLEN-CARD')
        engine = self.make_engine([], [stolen])
        definition = build_effect_draft(
            'RANDOM-LUMEN',
            '①회피 시, 상대의 패 무작위 1장을 자신의 루멘 존으로 보낸다. '
            '그 후, 리커버리 페이즈 시 해당 기술을 상대 리스트로 보낸다.',
        )
        effects = definition['abilities'][0]['effects']

        engine.resolver.execute_effects(effects, {'controller': 'p1'})
        holder, zone, _index, moved = engine._find_location('stolen-card')
        self.assertEqual((holder, zone, moved['owner']), ('p1', 'lumen', 'p2'))
