    def test_structured_choice_review_includes_insufficient_candidate_scenario(self):
        definition = {
            'schema_version': 1, 'reviewed': False, 'draft': True,
            'source_refs': {
                'rulebook_pages': [48], 'qna_ids': [], 'card_text': True,
            },
            'abilities': [{
                'id': 'structured-choice', 'kind': 'effect',
                'mode': 'mandatory', 'timing': 'use',
                'trigger': {'event': 'use'}, 'visibility': 'public',
                'source_refs': {
                    'rulebook_pages': [48], 'qna_ids': [], 'card_text': True,
                },
                'effects': [{
                    'op': 'request_choice',
                    'player': {'controller': True},
                    'selector': {
                        'kind': 'card', 'player': {'controller': True},
                        'zones': ['list'], 'min': 1, 'max': 1,
                        'where': {'token_key': 'review_token'},
                    },
                    'selection_key': 'chosen', 'default': [],
                    'then': [{
                        'op': 'move_card', 'selection_key': 'chosen',
                        'to_zone': 'hand',
                    }],
                }],
            }],
        }

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'STRUCTURED-REVIEW', 'name': '구조화 검토',
                'type': '공격', 'frame': 5, 'damage': 400, 'pos': '상단',
            },
        )

        self.assertTrue(result.passed)
        self.assertFalse(result.simple)
        self.assertEqual(result.method, 'automatic-effect-v2')
        self.assertEqual(
            [scenario['name'] for scenario in result.abilities[0].scenarios],
            [
                'owner-p1', 'owner-p2',
                'insufficient-candidates', 'wrong-trigger',
            ],
        )
        self.assertGreaterEqual(
            result.abilities[0].scenarios[0]['decision_count'], 1,
        )
        self.assertIn(
            'card_moved', result.abilities[0].scenarios[0]['domain_events'],
        )
        insufficient = result.abilities[0].scenarios[2]
        self.assertTrue(insufficient['choice_skipped'])
        self.assertEqual(insufficient['events_after_choice_skip'], [])

