    def test_conditional_value_expression_uses_live_state(self):
        state = base_state([], [])
        expression = {
            'op': 'if',
            'condition': {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'blue_flame',
            },
            'then': 5, 'else': 3,
        }
        context = {'controller': 'p1'}

        self.assertEqual(resolve_value(expression, state, context), 3)
        state['players']['p1']['passive_state']['blue_flame'] = {'value': True}
        self.assertEqual(resolve_value(expression, state, context), 5)
        self.assertEqual(validate_effect_definition({
            'schema_version': 1,
            'abilities': [{
                'id': 'conditional-value', 'kind': 'effect', 'mode': 'mandatory',
                'timing': 'hit_counter', 'trigger': {'event': 'hit'},
                'effects': [{
                    'op': 'deal_damage', 'player': {'opponent': True},
                    'amount': 100, 'repeat': expression,
                }],
            }],
        }), [])

