    def test_damage_limited_clash_and_triggered_catch_review_six_cases(self):
        text = (
            '이 기술은 500데미지 이하 기술만 상쇄할 수 있다.\n'
            '①상쇄 시, <8속도 이하>기술로 캐치할 수 있다.'
        )
        definition = build_effect_draft('CB02-AT-009', text)

        self.assertEqual(definition['defense_rules'], [{
            'judgment': 'clash', 'max_damage': 500,
        }])
        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'CB02-AT-009', 'name': '크로스 카운터',
                'type': '수비', 'text': text, 'frame': 5, 'damage': 0,
                'g_top': '상쇄', 'g_mid': '상쇄', 'g_bot': '상쇄',
            },
        )

        self.assertTrue(result.passed)
        self.assertEqual(result.as_dict()['scenario_count'], 6)
        defense, catch = result.abilities
        self.assertEqual(
            [item['name'] for item in defense.scenarios],
            ['owner-p1-boundary', 'owner-p2-boundary', 'outside-rule'],
        )
        self.assertEqual(defense.scenarios[0]['result'], ['clash', 'clash'])
        self.assertEqual(defense.scenarios[2]['result'], ['hit', 'failed_defense'])
        for scenario in catch.scenarios[:2]:
            self.assertEqual(
                scenario['legal_ids'], [scenario['expected_boundary_id']],
            )
            self.assertNotIn(scenario['excluded_slow_id'], scenario['legal_ids'])
            self.assertNotIn(scenario['excluded_list_id'], scenario['legal_ids'])
        self.assertEqual(catch.scenarios[2]['grant_count'], 0)

