    def test_automatic_review_keeps_unproven_source_semantics_pending(self):
        examples = (
            (
                'FOLLOW-UP-REVIEW',
                '①판정 전, 리스트에서 2장까지 브레이크할 수 있다. '
                '그 후, 브레이크한 기술 1장당 2FP를 얻는다.',
            ),
            (
                'QUOTED-NAME-REVIEW',
                '①판정 전, 루멘 존에서 "ARM"명을 포함하는 기술 1장을 '
                '사이드 덱으로 보낸다.',
            ),
        )
        for code, text in examples:
            with self.subTest(code=code):
                result = review_automatic_definition(
                    build_effect_draft(code, text), card_has_text=True,
                )
                self.assertFalse(result.passed)
                self.assertIn('카드별 검토', result.reason)

        qna_definition = build_effect_draft(
            'QNA-REVIEW', '①사용 시, 1FP를 얻는다.', qna_ids=[139],
        )
        qna_result = review_automatic_definition(
            qna_definition, card_has_text=True,
        )
        self.assertFalse(qna_result.passed)
        self.assertIn('카드별 검토', qna_result.reason)

