    def test_st1_019_reviews_grab_negation_late_combo_and_recovery_qnas(self):
        text = (
            '상대는 이 기술을 방어 및 상쇄할 수 없다.\n'
            '①이 기술이 그랩 무효되었을 경우 자신은 4FP를 잃는다.\n'
            '②콤보 시, 3콤보 후 사용할 수 있으며 사용 후 콤보 타임을 종료한다.\n'
            '그 후, 다음 리커버리 페이즈 자신은 1FP를 얻는다.'
        )
        qna_ids = [69, 260, 408, 675]
        definition = build_effect_draft(
            'ST1-019', text, qna_ids=qna_ids,
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'ST1-019', 'name': '캐치 드롭', 'type': '공격',
                'text': text, 'frame': 10, 'damage': 500,
                'pos': '상단', 'special': '그랩',
                'hit': '5', 'guard': 'X', 'counter': '5',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 3)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        grab = {
            item['name']: item for item in result.abilities[1].scenarios
        }
        self.assertEqual(
            grab['owner-p1-qna-408-zero-then-minus-four']['owner_fp'], -4,
        )
        self.assertEqual(
            grab['qna-260-dodge-is-not-grab-negation']['owner_fp'], 0,
        )
        self.assertFalse(
            grab['qna-675-other-invalidation-is-not-grab-negation']['resolved'],
        )
        combo = {
            item['name']: item for item in result.abilities[2].scenarios
        }['owner-p1-fourth-combo-ends-and-schedules']
        self.assertTrue(combo['legal_chain'])
        self.assertFalse(combo['source_alone_legal'])
        self.assertFalse(combo['short_chain_legal'])
        self.assertTrue(combo['combo_ended'])
        self.assertEqual(
            combo['fp_after_recovery'], combo['fp_before_recovery'] + 1,
        )
        self.assertEqual(combo['fp_after_second_recovery'], combo['fp_after_recovery'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

