            card_snapshot={
                'code': 'ST1-009', 'name': '라이! 레피! 로켓!',
                'type': '공격', 'text': text, 'frame': 13, 'damage': 1200,
                'pos': '상단', 'body': '', 'special': '',
                'hit': '3', 'guard': 'X', 'counter': '4',
            },
