        invalid = copy.deepcopy(definition)
        invalid['play_condition']['exclude_source'] = 'yes'
        self.assertTrue(any(
            issue.path == '$.play_condition.exclude_source'
            for issue in validate_effect_definition(
                invalid, card_has_text=True,
            )
        ))

