    def test_unc_at_011_reviews_negation_dodge_late_combo_and_over_limit(self):
        text = (
            '상대는 이 기술을 방어 및 상쇄할 수 없다.\n'
            '이 기술은 특수 판정으로 회피할 수 없다.\n'
            '①이 기술이 무효 및 회피된다면 상대는 2FP를 얻는다.\n'
            '②콤보 시, 이 기술은 3콤보 후 사용할 수 있다.\n'
            '③콤보 시, 속도에 관계없이 [[keyword:rai]] 혹은 '
            '[[keyword:lefi]]명이 들어간 기술 다음으로 이을 수 있다.\n'
            '④[[state:over_limit]]: 콤보 시, 처리 후 콤보 타임을 종료하고 '
            '다음 리커버리 페이즈 시, 자신은 1FP를 얻는다.'
        )
        definition = build_effect_draft(
            'UNC-AT-011', text,
            detail_text=(
                '①의 무효는 그랩 무효만 뜻하며 다른 카드 효과에 의한 '
                '무효화는 포함하지 않습니다. ④는 이 기술 처리 후 콤보를 '
                '종료하고 다음 리커버리에 FP를 얻습니다.'
            ),
            qna_ids=[532, 675],
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'UNC-AT-011', 'name': '라이! 레피! 캐치!',
                'type': '공격', 'text': text, 'frame': 12, 'damage': 500,
                'pos': '상단', 'body': '손', 'special': '그랩',
                'hit': '5', 'guard': 'X', 'counter': '6',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 6)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        by_id = {ability.ability_id: ability for ability in result.abilities}
        prevent = {
            item['name']: item
            for item in by_id['unc-at-011-function'].scenarios
        }
        self.assertTrue(
            prevent['owner-p1-special-dodge-is-blocked']['dodge_blocked'],
        )
        self.assertFalse(
            prevent['ordinary-dodge-remains-available']['dodge_blocked'],
        )
        grab = {
            item['name']: item
            for item in by_id['unc-at-011-n1-grab-negated'].scenarios
        }
        self.assertEqual(
            grab['owner-p1-grab-negated-gives-opponent-two']['opponent_fp'],
            2,
        )
        self.assertFalse(
            grab['qna-675-other-invalidation-does-not-trigger']['resolved'],
        )
        late = {
            item['name']: item for item in by_id['unc-at-011-n2'].scenarios
        }
        self.assertFalse(late['three-combo-is-illegal']['legal'])
        self.assertTrue(late['owner-p1-four-combo-is-legal']['legal'])
        link = {
            item['name']: item for item in by_id['unc-at-011-n3'].scenarios
        }
        self.assertTrue(link['owner-p1-after-rai-ignores-speed']['legal'])
        self.assertFalse(link['unrelated-name-does-not-ignore-speed']['legal'])
        self.assertTrue(
            link['qna-532-owner-p1-simultaneous-rai-then-catch']
            ['pair_available'],
        )
        over = {
            item['name']: item for item in by_id['unc-at-011-n4'].scenarios
        }
        active = over[
            'owner-p1-over-limit-stops-before-fifth-and-schedules'
        ]
        self.assertTrue(active['source_used'])
        self.assertFalse(active['followup_used'])
        self.assertEqual(
            active['fp_after_recovery'], active['fp_before_recovery'] + 1,
        )
        inactive = over[
            'without-over-limit-fifth-continues-and-no-schedule'
        ]
        self.assertTrue(inactive['followup_used'])
        self.assertEqual(inactive['scheduled_before_recovery'], 0)
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

