    def test_st5_010_reviews_mixed_defense_damage_and_fp_adjustment(self):
        text = (
            '이 기술은 9속도 이하 기술만 회피 및 상쇄할 수 있다.\n'
            '①회피 시 상대에게 300데미지를 주고 자신은 5FP를 얻는다. '
            '이번 턴 자신은 캐치할 수 없다.\n'
            '②상쇄 시 상대 기술 데미지-400, 상대에게 200데미지를 준다. '
            '그 후 상대 FP를 <+1>로 조정한다.'
        )
        definition = build_effect_draft(
            'ST5-010', text,
            detail_text=(
                '상단 회피와 중단 상쇄는 각각 효과 적용 속도 9 이하만 '
                '허용합니다. 상쇄의 200은 기술 데미지와 별도이며 상대 FP는 '
                '기존 값과 관계없이 +1이 됩니다. 콤보 종료 후 양쪽 FP를 0으로 '
                '초기화합니다.'
            ),
            qna_ids=[171, 341, 575],
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'ST5-010', 'name': '타뷸라',
                'type': '수비', 'text': text,
                'frame': None, 'damage': None,
                'g_top': '회피', 'g_mid': '상쇄', 'g_bot': '',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 3)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        by_id = {ability.ability_id: ability for ability in result.abilities}
        defense = {
            item['name']: item
            for item in by_id['st5-010-function'].scenarios
        }
        self.assertEqual(
            defense['upper-speed-nine-dodges']['result'],
            ['opponent_dodge', 'dodge'],
        )
        self.assertEqual(
            defense['middle-speed-nine-clashes']['result'],
            ['clash', 'clash'],
        )
        self.assertEqual(
            defense['qna-341-empty-lower-remains-no-defense']['result'],
            ['hit', 'failed_defense'],
        )
        clash = {
            item['name']: item for item in by_id['st5-010-n2'].scenarios
        }
        adjusted = clash[
            'owner-p1-clash-reduces-damage-and-adjusts-fp'
        ]
        self.assertEqual(adjusted['opponent_damage'], 300)
        self.assertEqual(adjusted['fp_after_effect'], 1)
        reset = clash['qna-171-combo-end-clears-adjusted-fp']
        self.assertEqual(reset['fp_after_combo'], 0)
        self.assertEqual(reset['controller_fp_after_combo'], 0)
        lethal = clash[
            'qna-575-effect-damage-wins-before-clash-damage'
        ]
        self.assertEqual(lethal['winner'], 'p1')
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

