    def test_st6_002_reviews_fp_gate_and_speed_eight_low_dodge(self):
        text = (
            '①판정 전 상대가 FP가 유리하다면\n'
            '이 기술에 8속도 이상 <하단 회피>특수 판정을 추가한다.'
        )
        definition = build_effect_draft('ST6-002', text)
        snapshot = {
            'code': 'ST6-002', 'name': '스피어 주테',
            'type': '공격', 'text': text, 'frame': 6, 'damage': 500,
            'pos': '상단', 'body': '손', 'special': None, 'hit': '2',
            'guard': '-2', 'counter': '3', 'character_key': 'viola',
        }

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 1)
        self.assertEqual(len(result.abilities[0].scenarios), 12)
        scenarios = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        speed_eight = scenarios[
            'owner-p1-opponent-ahead-speed-eight-dodges'
        ]
        self.assertTrue(speed_eight['dodge_allowed'])
        self.assertEqual(speed_eight['battle_result'], 'counter')
        self.assertFalse(
            scenarios['equal-fp-does-not-grant-dodge']['resolved'],
        )
        self.assertFalse(
            scenarios['speed-seven-is-outside-granted-dodge']
            ['dodge_allowed'],
        )
        self.assertFalse(
            scenarios['effect-lowered-nine-to-seven-is-outside']
            ['dodge_allowed'],
        )
        self.assertTrue(
            scenarios['effect-raised-seven-to-nine-dodges']['dodge_allowed'],
        )
        fp_boundary = scenarios[
            'fp-does-not-lower-reference-speed-boundary'
        ]
        self.assertTrue(fp_boundary['dodge_allowed'])
        self.assertEqual(fp_boundary['reference_speed'], 9)
        self.assertEqual(fp_boundary['final_speed'], 6)
        self.assertFalse(
            scenarios['middle-position-does-not-use-lower-dodge']
            ['dodge_allowed'],
        )
        self.assertFalse(
            scenarios['wrong-timing-does-not-grant-dodge']['resolved'],
        )
        self.assertFalse(
            scenarios['source-in-hand-does-not-grant-dodge']['resolved'],
        )
        self.assertFalse(
            scenarios['numbered-negation-does-not-grant-dodge']['resolved'],
        )
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

        mutations = []
        with_rechecked_fp = copy.deepcopy(definition)
        with_rechecked_fp['defense_rules'][0]['condition'] = copy.deepcopy(
            definition['abilities'][0]['condition']
        )
        mutations.append(with_rechecked_fp)
        wrong_speed = copy.deepcopy(definition)
        wrong_speed['defense_rules'][0]['min_speed'] = 7
        mutations.append(wrong_speed)
        not_numbered = copy.deepcopy(definition)
        not_numbered['defense_rules'][0].pop('numbered_effect')
        mutations.append(not_numbered)
        wrong_zone = copy.deepcopy(definition)
        wrong_zone['abilities'][0].pop('active_zones')
        mutations.append(wrong_zone)
        incomplete_judgment = copy.deepcopy(definition)
        incomplete_judgment['abilities'][0]['effects'][0][
            'value'
        ] = '하단 회피'
        mutations.append(incomplete_judgment)
        for mutated in mutations:
            self.assertFalse(review_automatic_definition(
                mutated, card_has_text=True, card_snapshot=snapshot,
            ).passed)

        for key, value in (
            ('pos', '하단'), ('body', '다리'), ('frame', 7),
            ('damage', 400), ('hit', '1'), ('guard', '-1'), ('counter', '2'),
        ):
            wrong_snapshot = copy.deepcopy(snapshot)
            wrong_snapshot[key] = value
            self.assertFalse(review_automatic_definition(
                definition, card_has_text=True, card_snapshot=wrong_snapshot,
            ).passed)

