    def test_unc_at_038_reviews_combo_range_and_catch_bonus_break(self):
        text = (
            '①콤보 시 6~9속도로 사용할 수 있다.\n'
            '②캐치 시 8속도로 사용할 수 있다. 그 경우, '
            '[[state:hidden_bond]] 카운터를 1개 얻고 이 기술의 '
            '데미지+100. 그 후, 이 기술을 브레이크한다.'
        )
        definition = build_effect_draft('UNC-AT-038', text)

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'UNC-AT-038', 'name': 'Quick Accent',
                'type': '공격', 'text': text, 'frame': 5, 'damage': 400,
                'pos': '상단', 'body': '손', 'special': '',
                'hit': '+2', 'guard': '-3', 'counter': '+3',
                'character_key': 'viola',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 2)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        by_id = {ability.ability_id: ability for ability in result.abilities}
        combo = {
            item['name']: item
            for item in by_id['unc-at-038-n1'].scenarios
        }
        self.assertTrue(combo['owner-p1-combo-min-speed-is-legal']['legal'])
        self.assertTrue(combo['owner-p2-combo-max-speed-is-legal']['legal'])
        self.assertFalse(
            combo['printed-speed-five-is-not-a-combo-option']['legal'],
        )
        self.assertFalse(combo['speed-ten-is-outside-combo-range']['legal'])

        catch = {
            item['name']: item
            for item in by_id['unc-at-038-n2'].scenarios
        }
        resolved = catch[
            'owner-p1-catch-gains-bond-deals-five-hundred-then-breaks'
        ]
        self.assertEqual(resolved['fixed_speed'], 8)
        self.assertEqual(resolved['hidden_bond'], 1)
        self.assertEqual(resolved['opponent_hp'], 3500)
        self.assertEqual(resolved['source_zone'], 'break')
        self.assertTrue(resolved['damage_before_break'])
        rejected = catch[
            'catch-maximum-seven-keeps-printed-speed-five'
        ]
        self.assertEqual(rejected['action_count'], 1)
        self.assertEqual(rejected['available_speeds'], [5])
        negated = catch[
            'numbered-effects-negated-use-printed-speed-without-bonus-or-break'
        ]
        self.assertEqual(negated['fixed_speed'], 5)
        self.assertEqual(negated['hidden_bond'], 0)
        self.assertEqual(negated['opponent_hp'], 3600)
        self.assertNotEqual(negated['source_zone'], 'break')
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

