    def test_awl_ps_001_reviews_clash_damage_duration_and_special_suppression(self):
        text = (
            '①자신이나 상대가 상쇄 시, 자신이 데미지를 줬다면 상대에게 '
            '100데미지를 주고, 다음 배틀 페이즈 종료 시까지 '
            '[[state:dark_night]]상태가 된다.\n'
            '②[[state:dark_night]]: 상대 기술의 특수 판정을 제거한다.'
        )
        qna_ids = [190, 193, 220, 370, 404, 552, 584, 615]
        definition = build_effect_draft(
            'AWL-PS-001', text, qna_ids=qna_ids,
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'AWL-PS-001', 'name': '「장막을 두른 칼날」',
                'type': '특성', 'text': text, 'frame': None,
                'damage': None, 'pos': '', 'body': '', 'special': '',
                'hit': '', 'guard': '', 'counter': '',
                'character_key': 'reve',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 2)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        by_id = {ability.ability_id: ability for ability in result.abilities}
        trigger = {
            item['name']: item
            for item in by_id['awl-ps-001-n1'].scenarios
        }
        clash = trigger[
            'owner-p1-clash-difference-damage-triggers-once'
        ]
        self.assertEqual(clash['resolved_count'], 1)
        self.assertEqual(clash['damage_amounts'][:2], [300, 100])
        self.assertTrue(clash['after_current_battle'])
        self.assertFalse(clash['after_next_battle'])
        effect = trigger[
            'qna-190-owner-p2-clash-effect-damage-triggers'
        ]
        self.assertEqual(effect['damage_amounts'], [150, 100])
        self.assertTrue(effect['dark_night_after_trigger'])
        self.assertFalse(
            trigger[
                'opponent-clash-damage-does-not-trigger-owner-trait'
            ]['dark_night_after_trigger'],
        )
        restart = trigger[
            'qna-404-ready-restart-does-not-advance-expiration'
        ]
        self.assertTrue(restart['after_restart'])
        self.assertEqual(
            restart['expiration_before'], restart['expiration_after_restart'],
        )

        suppression = {
            item['name']: item
            for item in by_id['awl-ps-001-n2'].scenarios
        }
        active = suppression[
            'owner-p1-dark-night-clears-battle-hand-and-list-special'
        ]
        self.assertEqual(active['owner_special'], '그랩')
        self.assertEqual(active['opponent_special'], '')
        self.assertEqual(active['hand_special'], '')
        self.assertEqual(active['list_special'], '')
        self.assertFalse(active['grab_negation_offered'])
        inactive = suppression[
            'state-disabled-keeps-special-and-offers-hand-grab-only'
        ]
        self.assertTrue(inactive['grab_negation_offered'])
        self.assertEqual(
            inactive['grab_option_ids'], ['p2-veiled-blade-hand-grab'],
        )
        reapplied = suppression[
            'qna-552-reapplied-special-is-cleared-again'
        ]
        self.assertEqual(reapplied['opponent_special'], '')
        negated = suppression[
            'qna-220-trait-negation-keeps-technique-state-but-stops-removal'
        ]
        self.assertTrue(negated['dark_night'])
        self.assertEqual(negated['opponent_special'], '그랩 · 상단 회피')
        self.assertTrue(negated['grab_negation_offered'])
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

