        self.assertEqual(expired['damage']['wolf_hand_12'], 300)

        wrong_threshold = copy.deepcopy(definition)
        wrong_threshold['abilities'][1]['effects'][0]['condition'][
            'right'
        ] = 4
        self.assertFalse(review_automatic_definition(
            wrong_threshold, card_has_text=True, card_snapshot=snapshot,
        ).passed)
        wrong_expiry = copy.deepcopy(definition)
