        broken = skip['owner-p1-source-break-skips-both-get-phases']
        self.assertTrue(broken['owner_skip_get'])
        self.assertTrue(broken['opponent_skip_get'])
        unrelated = skip['unrelated-card-break-does-not-skip-get']
        self.assertFalse(unrelated['owner_skip_get'])
        self.assertFalse(unrelated['opponent_skip_get'])
