        self.assertEqual(qna444['rubiette_resolved'], 2)
        self.assertEqual(qna444['owner_fp'], 4)
        self.assertEqual(qna444['speed_with_fp'], 6)
        qna116 = broken[
            'qna-116-kissing-break-and-rubiette-total-four-fp'
        ]
        self.assertEqual(qna116['owner_fp'], 4)
        self.assertEqual(qna116['kissing_resolved'], 1)

        threshold = {
            item['name']: item
            for item in by_id['awl-sp-002-fp-threshold'].scenarios
        }
        self.assertEqual(
            threshold['owner-p1-positive-seven-difference-moves-side'][
                'source_zone'
            ],
            'side',
        )
        qna361 = threshold[
            'qna-361-threshold-moves-before-later-fp-reset'
        ]
        self.assertEqual(qna361['zone_at_threshold'], 'side')
        self.assertEqual(qna361['final_fp'], (0, 0))
        self.assertEqual(
            threshold['qna-72-invalid-special-destination-breaks-card'][
                'source_zone'
            ],
            'break',
        )
        self.assertEqual(
            threshold[
                'qna-484-five-calling-cards-have-no-card-deck-limit'
            ]['calling_card_count'],
            5,
        )
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

