        ordered = dark['p2-same-timing-effects-use-selected-order']
        self.assertEqual(
            ordered['resolution_order'],
            ['unc-at-043-n2', 'unc-at-043-n1'],
        )
        self.assertEqual(ordered['opponent_damage'], 500)

        combo = {
            item['name']: item
            for item in by_id['unc-at-043-n3'].scenarios
        }
        self.assertFalse(
            combo['owner-p1-first-combo-keeps-seven-hundred']['resolved'],
        )
        self.assertEqual(
            combo['owner-p1-second-combo-reduces-to-five-hundred']
            ['source_damage'],
            500,
        )
        self.assertEqual(
            combo['owner-p2-third-combo-reduces-to-five-hundred']
            ['source_damage'],
            500,
        )
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

