        filtered = acquire[
            'initially-protected-candidate-is-filtered'
        ]
        self.assertNotIn(filtered['candidate_ids'][0], filtered['option_ids'])
        late = acquire['late-protection-keeps-selected-card-in-place']
        self.assertEqual(late['selected_zone'], 'list')
        self.assertTrue(late['move_ignored'])
