    def test_cb03_at_028_reviews_repeating_guisum_bonus_and_blue_flame_expiry(self):
        text = (
            '①히트 및 카운터 시, 루멘 존의 [[card:RFS-AT-002]]이 3장 '
            '이상일 경우, 이번 턴 사용하는 [[card:RFS-AT-002]]의 '
            '데미지+100, 히트 판정을 <+1>로 변경한다. 그 후, 다음 턴 '
            '종료시까지 [[state:blue_flame]] 상태를 부여한다.'
        )
        snapshot = {
            'code': 'CB03-AT-028', 'name': '벽귀난무', 'type': '공격',
            'text': text, 'detail_text': '', 'frame': 9, 'damage': 500,
            'pos': '중단', 'body': '', 'special': None,
            'hit': '2', 'guard': '-9', 'counter': '콤보',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 16, 'ultimate': False,
        }
        definition = build_effect_draft('CB03-AT-028', text)
        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 1)
        self.assertEqual(result.as_dict()['scenario_count'], 8)
        scenarios = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        repeated = scenarios[
            'owner-p1-two-guisum-uses-both-receive-bonus'
        ]
        self.assertEqual(
            [trace['damage'] for trace in repeated['traces']], [600, 600],
        )
        self.assertEqual(
            [trace['live_hit'] for trace in repeated['traces']], ['+1', '+1'],
        )
        self.assertEqual(
            [trace['restored_hit'] for trace in repeated['traces']], ['2', '2'],
        )
        self.assertTrue(repeated['blue_after_current_recovery'])
        self.assertFalse(repeated['blue_after_next_recovery'])
        opponent = scenarios['opponent-guisum-use-does-not-consume-or-apply']
        self.assertEqual(opponent['traces'][0]['damage'], 500)
        self.assertEqual(opponent['scheduled_before_turn_expiry'], 2)
        mutated = copy.deepcopy(definition)
        mutated['abilities'][0]['effects'][0]['repeat'] = False
        self.assertFalse(review_automatic_definition(
            mutated, card_has_text=True, card_snapshot=snapshot,
        ).passed)
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

