    def test_dfr_at_012_reviews_cost_live_hp_and_successful_cleanup(self):
        text = (
            '①루멘 페이즈 시, 자신의 체력이 2000 이하라면 600데미지를 '
            '받고 얼티밋 존의 이 기술을 브레이크할 수 있다.\n'
            '그 경우 이하의 효과를 적용한다.\n'
            '-이번 턴 배틀 페이즈 종료 시까지 [[state:over_limit]]이 '
            '해제되지 않는다.\n'
            '-루멘 존의 기술 1장당 1FP를 얻는다.\n'
            '-이번 턴 레디하는 공격 기술의 기술 데미지+300 자신의 체력이 '
            '1000 이하일 경우 대신+600\n'
            '-이번 턴 종료 시, 루멘 존의 기술을 모두 리스트로 보낸다. '
            '그 후, 보낸 기술 1장당 200데미지를 받는다.'
        )
        definition = build_effect_draft('DFR-AT-012', text)
        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'DFR-AT-012', 'name': '열역학 제2법칙',
                'type': '특수', 'text': text, 'ultimate': True,
                'hit': '0', 'guard': '0', 'counter': '0',
                'character_key': 'cmyk',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 1)
        self.assertTrue(result.abilities[0].passed)
        self.assertEqual(len(result.abilities[0].scenarios), 21)
        scenarios = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        boundary = scenarios['owner-p1-hp-boundary-activates']
        self.assertEqual(
            (boundary['hp'], boundary['fp'], boundary['source_zone']),
            (1400, 2, 'break'),
        )
        self.assertTrue(boundary['state_loss_blocked'])
        self.assertTrue(boundary['state_loss_after_expiry'])
        self.assertIsNone(
            scenarios['wrong-phase-does-not-activate']['activation_kind'],
        )
        protected = scenarios[
            'break-protected-before-resolution-cancels-activation'
        ]
        self.assertFalse(protected['break_prevented'])
        self.assertEqual(
            (protected['hp'], protected['fp'], protected['scheduled_count']),
            (1500, 0, 0),
        )
        self.assertEqual(
            scenarios['ready-at-900-hp-gains-six-hundred']['attack_damage'],
            1000,
        )
        self.assertEqual(
            scenarios['ready-at-1400-hp-gains-three-hundred']['attack_damage'],
            700,
        )
        self.assertEqual(
            scenarios['ready-uses-live-lowered-hp']['attack_damage'], 1000,
        )
        cleanup = scenarios['owner-p1-moves-two-techniques-not-tokens']
        self.assertEqual(
            (cleanup['moved_count'], cleanup['damage_received']), (2, 400),
        )
        self.assertTrue(all(
            zone == 'lumen' for zone in cleanup['token_zones'].values()
        ))
        immune = scenarios['one-immune-technique-reduces-damage-count']
        self.assertTrue(immune['move_ignored'])
        self.assertEqual(
            (immune['moved_count'], immune['damage_received']), (1, 200),
        )
        overflow = scenarios[
            'full-list-breaks-overflow-but-counts-sent-cards'
        ]
        self.assertEqual(
            (
                overflow['moved_count'], overflow['broken_count'],
                overflow['damage_received'],
            ),
            (0, 2, 400),
        )

        ability = definition['abilities'][0]
        self.assertEqual(ability['condition']['conditions'][0], {
            'op': 'phase_is', 'phase': 'lumen',
        })
        self.assertEqual(
            ability['availability_selector']['as_operation'], 'break_card',
        )
        followups = ability['effects'][2]['then']
        self.assertEqual(
            followups[1]['amount']['where'], {'is_technique': True},
        )
        cleanup_effects = followups[3]['effect']['effects']
        self.assertEqual(
            cleanup_effects[0]['selector']['where'],
            {'is_technique': True},
        )
        self.assertEqual(
            cleanup_effects[1]['result_key'],
            'thermodynamics_moved_lumen_cards',
        )
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

