        self.assertTrue(changed_token['move_ignored'])
        self.assertEqual(
            (changed_token['calling_lumen_count'], changed_token['hand_count']),
            (2, 5),
        )
        self.assertIsNone(
            replenish['game-limit-blocks-second-activation'][
                'second_activation_kind'
            ],
        )

        limit = {
            item['name']: item for item in by_id['dfr-at-018-n2'].scenarios
        }
        self.assertEqual(
            limit['owner-p1-third-succeeds-fourth-is-blocked']['results'],
            [True, False],
        )
        self.assertEqual(
            limit['inactive-outside-ultimate-allows-four']['calling_counts'],
            {'p1': 4, 'p2': 0},
        )
        self.assertEqual(
            limit['numbered-negation-removes-three-card-limit']['results'],
            [True, True],
        )
        self.assertEqual(
            limit['non-calling-token-ignores-calling-card-limit']['wrong_zone'],
            'lumen',
        )
        self.assertTrue(
            limit['exchange-replacing-calling-card-keeps-three']['results'][0],
        )
        self.assertFalse(
            limit[
                'exchange-replacing-unrelated-card-cannot-create-fourth'
            ]['results'][0],
        )

