        self.assertEqual(definition['abilities'][1]['mode'], 'continuous')
        self.assertEqual(definition['zone_limits'], [{
            'zone': 'lumen', 'max': 3,
            'where': {'token_key': 'calling_card'},
        }])
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

