    def test_st1_ps1_reviews_forced_choices_state_and_release(self):
        text = (
            '①[[keyword:rai]] 및 [[keyword:lefi]]명이 들어간 기술의 사용 후, '
            '패나 리스트에서 기술 1장을 루멘 존으로 보낸다.\n'
            '②루멘 존에 공격·수비 기술이 4장 이상일 때 '
            '[[state:over_limit]]상태가 되며 이하의 효과를 적용한다.\n'
            '-모든 <[[character:nya]] 공격> 기술 데미지+100\n'
            '-리커버리 페이즈 시 루멘 존에 있는 <[[character:nya]]> 기술 '
            '1장을 브레이크 하거나 패나 리스트에서 기술 2장을 루멘 존으로 보낸다.\n'
            '-루멘 페이즈 시 루멘 존의 기술이 8장 이상일 경우 그 기술 1장당 '
            '100데미지를 받고 공격·수비 기술을 모두 리스트로 보낸다.\n'
            '그 후, 2FP를 잃고 [[state:over_limit]]을 해제한다.'
        )
        qna_ids = [
            73, 74, 75, 76, 77, 78, 80, 95, 143, 281, 290, 328, 331,
            354, 358, 376, 387, 410, 530, 566, 581,
        ]
        definition = build_effect_draft('ST1-PS1', text, qna_ids=qna_ids)

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'ST1-PS1', 'name': '「오버 리밋」',
                'type': '특성', 'text': text, 'frame': None, 'damage': None,
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 5)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        by_id = {ability.ability_id: ability for ability in result.abilities}
        after_use = {
            item['name']: item for item in by_id['st1-ps1-n1'].scenarios
        }
        self.assertFalse(
            after_use['owner-p1-rai-selects-second-technique']['token_offered'],
        )
        self.assertTrue(
            after_use['qna-76-290-no-technique-skips-safely']['choice_skipped'],
        )
        recovery = {
            item['name']: item
            for item in by_id['st1-ps1-over-limit-recovery'].scenarios
        }
        self.assertEqual(
            recovery['qna-530-exceed-removes-break-branch']['branch_ids'],
            ['send_two'],
        )
        release = {
            item['name']: item
            for item in by_id['st1-ps1-over-limit-release'].scenarios
        }
        self.assertEqual(
            release['owner-p1-eight-releases-and-keeps-special']['hp'], 3200,
        )
        self.assertTrue(
            release['qna-354-hidden-eighth-does-not-release']['active'],
        )
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def _assert_st2_technique_review(
        self, code, text, qna_ids, snapshot, ability_count,
    ):
        definition = build_effect_draft(code, text, qna_ids=qna_ids)
        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={**snapshot, 'text': text},
        )
        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), ability_count)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )
        invalid_definition = copy.deepcopy(definition)
        invalid_definition['abilities'][0]['effects'] = []
        self.assertFalse(review_automatic_definition(
            invalid_definition, card_has_text=True,
            card_snapshot={**snapshot, 'text': text},
        ).passed)
        invalid_snapshot = {**snapshot, 'text': text, 'character_id': 999}
        self.assertFalse(review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot=invalid_snapshot,
        ).passed)
        return result

