    def test_lmi_at_049_reviews_dodge_catch_lock_and_forced_list_choice(self):
        text = (
            '이 기술은 히트 판정이 <+4>이상, 또는 <콤보>인 기술을 '
            '회피할 수 있다.\n'
            '①회피 시, 5FP를 얻는다.\n'
            '그 후, 이번 턴 자신은 캐치할 수 없다.\n'
            '②사용 후, 500데미지 이상 받았다면 자신의 리스트에서 '
            '기술 1장을 획득한다.'
        )
        definition = build_effect_draft(
            'LMI-AT-049', text, qna_ids=[146, 441],
        )

        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'LMI-AT-049', 'name': '플렉시블 닷지',
                'type': '수비', 'text': text,
                'g_top': '회피', 'g_mid': '회피', 'g_bot': '',
            },
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 3)
        self.assertTrue(all(
            ability.passed and len(ability.scenarios) >= 3
            for ability in result.abilities
        ))
        defense = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        self.assertEqual(defense['owner-p1-plus-four-is-dodged']['result'], ['opponent_dodge', 'dodge'])
        self.assertEqual(defense['owner-p2-combo-is-dodged']['result'], ['opponent_dodge', 'dodge'])
        self.assertEqual(defense['plus-three-is-not-dodged']['result'], ['hit', 'failed_defense'])
        dodge = {
            item['name']: item for item in result.abilities[1].scenarios
        }['owner-p1-dodge-gains-five-and-blocks-catch']
        self.assertEqual(dodge['after_fp'], dodge['before_fp'] + 5)
        self.assertTrue(dodge['catch_blocked'])
        self.assertFalse(dodge['catch_blocked_after_turn'])
        acquire = {
            item['name']: item for item in result.abilities[2].scenarios
        }
        selected = acquire['owner-p1-selects-one-of-two']
        self.assertEqual(len(selected['option_ids']), 2)
        self.assertEqual(len(selected['hand_ids']), 1)
        self.assertFalse(selected['token_offered'])
        self.assertTrue(acquire['zero-candidates-skips-safely']['choice_skipped'])
        self.assertFalse(acquire['qna-441-later-combo-damage-is-too-late']['decision'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

