    def test_primary_card_conditions_cover_three_opponent_situations(self):
        definition = build_effect_draft(
            'CONDITIONAL-OPPONENT',
            '①판정 전 상대 공격 기술이 7속도 이하 손 판정 기술인 경우 '
            '자신은 2FP를 얻는다.',
        )
        condition = definition['abilities'][0]['condition']
        state = base_state([], [])

        self.assertTrue(condition_matches(condition, state, {
            'controller': 'p1', 'opponent_speed': 7,
            'opponent_card': {'type': '공격', 'body': '손'},
        }))
        self.assertFalse(condition_matches(condition, state, {
            'controller': 'p1', 'opponent_speed': 8,
            'opponent_card': {'type': '공격', 'body': '손'},
        }))
        self.assertFalse(condition_matches(condition, state, {
            'controller': 'p1', 'opponent_speed': 7,
            'opponent_card': {'type': '수비', 'body': '발'},
        }))

    def test_inline_bullet_conditions_remain_independent(self):
        definition = build_effect_draft(
            'SPEED-BRANCHES',
            '①방어 시, 이하의 효과를 적용한다.\n'
            '-상대 기술의 속도가 7속도 이하라면 이번 턴 캐치할 수 없다.\n'
            '-상대 기술의 속도가 8속도 이상이라면 300데미지를 받는다.',
        )
        effects = definition['abilities'][0]['effects']
        branches = [effect for effect in effects if effect.get('op') == 'conditional']

        self.assertEqual(len(branches), 2)
        state = base_state([], [])
        low = {'controller': 'p1', 'opponent_speed': 7, 'opponent_card': {}}
        high = {'controller': 'p1', 'opponent_speed': 8, 'opponent_card': {}}
        middle = {'controller': 'p1', 'opponent_speed': 7.5, 'opponent_card': {}}
        matches = lambda context: [
            condition_matches(branch['condition'], state, context)
            for branch in branches
        ]
        self.assertEqual(matches(low), [True, False])
        self.assertEqual(matches(high), [False, True])
        self.assertEqual(matches(middle), [False, False])

