    def test_combo_card_can_break_all_predecessors_and_ignore_its_penalty(self):
        source = attack('combo-source', 'p1', frame=4, damage=500)
        predecessor = attack('combo-first', 'p1', frame=5, damage=500)
        current = attack('combo-breaker', 'p1', code='CB01-AT-032', frame=6, damage=500)
        definition = build_effect_draft(
            'CB01-AT-032',
            '①콤보 시, 이 기술 앞에 사용한 기술을 모두 브레이크할 수 있다. '
            '그 경우, 이 기술은 데미지 보정을 적용하지 않는다.',
        )
        state = base_state([predecessor, current], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        release = ruleset(source, predecessor, current)
        release['cards']['CB01-AT-032']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='combo-break-predecessors')
        engine.state['phase'] = 'battle'
        engine.grant_combo('p1', source=source['instance_id'])

        proposal = next(
            item for item in engine._combo_actions(
                'p1', engine.engine_state['combo'],
            )
            if item['type'] == 'play_combo_pair'
            and item['payload']['card_instance_ids'] == [
                predecessor['instance_id'], current['instance_id'],
            ]
        )
        self.submit_initial_combo_pair(engine, 'p1', proposal)
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')

        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})

        self.assertIsNotNone(engine._find_card(source['instance_id'], owner='p1', zone='break'))
        self.assertIsNotNone(engine._find_card(predecessor['instance_id'], owner='p1', zone='break'))
        self.assertIsNotNone(engine._find_card(current['instance_id'], owner='p1', zone='list'))
        self.assertEqual(engine.state['players']['p2']['hp'], 4100)
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_lumen_break_trigger_acquires_from_list_and_increases_hand_limit(self):
        definition = build_effect_draft(
            'CB02-AT-002',
            '①이 기술이 루멘 존에 있는 동안 이하의 효과를 적용한다. '
            '- 자신의 기술이 브레이크 될 때마다 리스트에서 1장을 획득할 수 있다. '
            '이 효과는 콤보 타임 중에는 적용하지 않는다. '
            '- 패 매수 상한이 1장 늘어난다.',
        )
        lumen = attack('lumen-passive', 'p1', code='CB02-AT-002')
        victim = attack('break-victim', 'p1')
        combo_victim = attack('combo-break-victim', 'p1')
        candidate = attack('list-acquire', 'p1')
        state = base_state([victim, combo_victim], [])
        state['players']['p1']['character'] = {'id': 7, 'name': 'current'}
        state['players']['p1']['zones']['lumen'] = [lumen]
        state['players']['p1']['zones']['list'] = [candidate]
        release = ruleset(lumen, victim, combo_victim, candidate)
        release['characters'] = {
            '7': {'id': 7, 'name': 'released', 'datas': {'hand': {'6200': 5}}},
        }
        release['cards']['CB02-AT-002']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='lumen-break-acquire')

        engine.break_card(victim['instance_id'], reason='test')
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
