    def test_revealed_defense_to_lumen_blocks_grab_negation_for_turn(self):
        text = (
            '①사용 시, 패의 수비 기술 1장을 공개하고 뒷면으로 루멘 존에 보낸다. '
            '그 후, 이번 턴 그랩 무효를 할 수 없다.'
        )
        definition = build_effect_draft('DFR-AT-047', text)
        commands = definition['abilities'][0]['effects']
        self.assertEqual([command['op'] for command in commands], ['request_choice'])
        followup = commands[0]['then'][-1]
        self.assertEqual(followup['op'], 'conditional')
        self.assertEqual(followup['then'][0]['kind'], 'grab_negation')

        source = attack('source', 'p2', code='DFR-AT-047')
        hidden_defense = defense('hidden-defense', 'p2')
        hand_grab = attack('hand-grab', 'p2', special='그랩')
        opposing_grab = attack('opposing-grab', 'p1', special='그랩')
        state = base_state([], [hidden_defense, hand_grab])
        state['players']['p2']['zones']['battle'] = [source]
        release = ruleset(source, hidden_defense, hand_grab, opposing_grab)
        release['cards']['DFR-AT-047']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='grab-negation-block')

        engine._fire('use', {
            'controller': 'p2', 'source_card': source,
            'source_card_instance_id': 'source',
        })
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'effect_choice')
        self.act(engine, 'p2', 'submit_decision', {'selected': ['hidden-defense']})
        moved = engine._find_card('hidden-defense', owner='p2', zone='lumen')
        self.assertIsNotNone(moved)
        self.assertFalse(moved['face_up'])
        self.assertTrue(engine._rule_blocked('grab_negation', 'p2'))

        engine.engine_state['battle'] = {
            'p1': {'card': opposing_grab, 'instance_id': 'opposing-grab'},
            'p2': {'card': source, 'instance_id': 'source'},
        }
        self.assertFalse(engine._offer_grab_negation())
        self.assertIsNone(engine.engine_state['pending_decision'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_full_blocking_review_covers_all_four_rule_groups(self):
        text = (
            '이 기술은 게임 중 1번만 사용할 수 있다.\n'
            '①사용 시, 패의 수비 기술 1장을 공개하고 뒷면으로 루멘 존에 '
            '보낸다. 그 후, 이번 턴 그랩 무효를 할 수 없다.\n'
            '②판정 후, 상대 기술이 수비일 경우 상대는 4FP를 얻는다.\n'
            '③사용 후, 이 기술을 브레이크하고 이번 턴 캐치할 수 없다.'
        )
        definition = build_effect_draft('DFR-AT-047', text)
        review = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'DFR-AT-047', 'name': '풀 블로킹',
                'type': '수비', 'text': text, 'damage': None,
                'g_top': '방어', 'g_mid': '방어', 'g_bot': '방어',
            },
        )

        self.assertTrue(review.passed)
        self.assertEqual(
            [len(ability.scenarios) for ability in review.abilities],
            [3, 7, 5, 5],
        )
        groups = {
            ability.ability_id: {
                scenario['name']: scenario for scenario in ability.scenarios
            }
            for ability in review.abilities
        }
        self.assertFalse(
            groups['dfr-at-047-function']['owner-p1-game-once'][
                'after_same_owner'
            ],
        )
        late = groups['dfr-at-047-n1'][
            'late-protection-restores-hidden-hand'
        ]
        self.assertEqual(late['selected_location'], 'hand')
        self.assertFalse(late['selected_face_up'])
        self.assertFalse(late['grab_negation_blocked'])
        self.assertEqual(late['move_ignored'], 1)
        self.assertEqual(
            groups['dfr-at-047-n2'][
                'owner-p2-opponent-defense-gains-four'
            ]['opponent_fp'],
            6,
        )
        protected_break = groups['dfr-at-047-n3'][
            'break-prevented-still-blocks-catch'
        ]
        self.assertEqual(protected_break['source_zone'], 'battle')
        self.assertTrue(protected_break['catch_blocked'])

        mutated = copy.deepcopy(definition)
        use_effect = next(
            ability for ability in mutated['abilities']
            if ability['id'] == 'dfr-at-047-n1'
        )
        conditional = use_effect['effects'][0]['then'][-1]
        conditional['condition']['left']['selection_key'] = (
            'dfr_at_047_lumen_defense'
        )
        self.assertFalse(review_automatic_definition(
            mutated, card_has_text=True,
            card_snapshot={
                'code': 'DFR-AT-047', 'name': '풀 블로킹',
                'type': '수비', 'text': text,
            },
        ).passed)

    def test_swift_flip_pays_dynamic_defense_cost_before_dodge(self):
        text = (
            '이 기술은 <10속도 이하>기술만 회피한다.\n'
            '이 기술은 상대 기술 속도 이상의 기술을 버려야만 회피할 수 있다.\n'
            '①회피 시, 상대 기술 속도-1만큼 FP를 얻는다.\n'
            '②사용 후, 이번 턴 콤보 타임 시 3콤보까지만 이을 수 있다.'
        )
        definition = build_effect_draft('DFR-AT-048', text)
        rule = definition['defense_rules'][0]
        self.assertEqual((rule['judgment'], rule['max_speed']), ('dodge', 10))
        self.assertEqual(rule['cost']['operation'], 'discard')
        self.assertEqual(
            rule['cost']['selector']['where'],
            {
                'is_technique': True,
                'frame_gte': {'path': 'context.opponent_speed'},
            },
        )

        opposing = attack('swift-opponent', 'p1', frame=7, damage=400)
        source = defense(
            'swift-flip', 'p2', top='회피', bottom='회피',
        )
        source['code'] = 'DFR-AT-048'
        below = attack('swift-below', 'p2', frame=6)
        exact = attack('swift-exact', 'p2', frame=7)
        above = attack('swift-above', 'p2', frame=10)
        non_technique = attack('swift-trait', 'p2', frame=12)
        non_technique['type'] = '특성'
        state = base_state(
            [opposing], [source, below, exact, above, non_technique],
            p1_fp=5,
        )
        release = ruleset(
            opposing, source, below, exact, above, non_technique,
        )
        release['cards']['DFR-AT-048']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(
            state, release, seed='swift-flip-defense-cost',
        )

        self.ready_both(engine)
        decision = engine.engine_state['pending_decision']
        self.assertEqual(decision['kind'], 'defense_cost')
        self.assertEqual(decision['owner'], 'p2')
        self.assertEqual(
            [option['id'] for option in decision['options']],
            ['swift-above', 'swift-exact'],
        )
        # FP changes the final battle Speed, not this reference-Speed cost.
        self.assertNotIn('swift-below', {
            option['id'] for option in decision['options']
        })
        self.assertNotIn('swift-trait', {
            option['id'] for option in decision['options']
        })

        self.act(
            engine, 'p2', 'submit_decision',
            {'selected': ['swift-exact']},
        )
        judged = next(
            event for event in engine.events if event['type'] == 'battle_judged'
        )
        self.assertEqual(judged['payload']['result']['p2'], 'dodge')
        self.assertIsNotNone(
            engine._find_card('swift-exact', owner='p2', zone='list'),
        )
        self.assertEqual(engine.state['players']['p2']['fp'], 6)
        self.assertTrue(any(
            event['type'] == 'defense_cost_paid' for event in engine.events
        ))
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

