        self.assertEqual(ability['effects'][0]['repeat']['else'], 2)
        snapshot = {
            'code': 'DFR-AT-040', 'name': '스핀 드릴',
            'type': '공격', 'text': text, 'frame': 7, 'damage': 200,
            'pos': '상단', 'body': '손', 'hit': '2',
            'guard': '-5', 'counter': '3',
        }
        review = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(review.passed)
        self.assertEqual([len(item.scenarios) for item in review.abilities], [7])
        scenarios = {
            item['name']: item for item in review.abilities[0].scenarios
        }
        self.assertEqual(
            scenarios['owner-p1-hit-without-arm-deals-twice']['damage_count'],
            2,
        )
        self.assertEqual(
            scenarios['combo-with-two-arm-techniques-deals-three-times'][
                'damage_count'
            ],
            3,
        )
        self.assertEqual(
            scenarios['arm-token-does-not-satisfy-technique-count'][
                'damage_count'
            ],
            2,
        )

        mutated = copy.deepcopy(definition)
        mutated['abilities'][0]['effects'][0]['repeat']['else'] = 0
        self.assertFalse(review_automatic_definition(
            mutated, card_has_text=True, card_snapshot=snapshot,
        ).passed)

