    def test_short_clutch_projects_battle_only_speed_and_counter_for_combo(self):
        text = (
            '①[[state:down_stance]]: 이 기술의 속도가 1 빨라지고\n'
            '카운터 판정이 <콤보>로 변경된다.'
        )
        detail_text = (
            '①효과: 조건(자신이 [[state:down_stance]] 상태)을 만족한 경우, '
            '유발되는 타이밍 없이 상시 적용되는 효과입니다. 패에서는 적용되지 않고, '
            '사용하여 배틀 존에 존재할 때만 적용됩니다.'
        )
        short = attack(
            'short-clutch', 'p1', code='ST3-001', frame=5,
            damage=400, position='중단', hit='1', counter='3',
        )
        support = attack(
            'combo-source', 'p1', code='COMBO-SOURCE', frame=3,
            damage=300, hit='콤보', counter='1',
        )
        opposing = attack('combo-opponent', 'p2', code='COMBO-OPPONENT')
        release = ruleset(short, support, opposing)
        release['cards']['ST3-001']['effect_definition'] = build_effect_draft(
            'ST3-001', text, qna_ids=[314, 651], detail_text=detail_text,
        )
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['hand'] = [short]
        state['players']['p1']['zones']['battle'] = [support]
        state['players']['p2']['zones']['battle'] = [opposing]
        state['players']['p1']['passive_state']['down_stance'] = {'value': True}
        engine = AutomaticGameEngine(
            state, release, seed='short-clutch-real-combo',
            now=datetime(2026, 6, 1, tzinfo=timezone.utc),
        )
        engine.engine_state['battle'] = {
            'p1': {'instance_id': support['instance_id'], 'card': copy.deepcopy(support)},
            'p2': {'instance_id': opposing['instance_id'], 'card': copy.deepcopy(opposing)},
        }
        engine.engine_state['combo'] = {
            'owner': 'p1', 'source': support['instance_id'],
            'special': False,
            'used': ['resolved-two', 'resolved-three'],
            'next_penalty': 300, 'max_combo': 4,
            'proposal_submitted': False,
        }
        engine.engine_state['step'] = 'combo'

        actions = [
            action for action in engine._combo_actions(
                'p1', engine.engine_state['combo'],
            )
            if (action.get('payload') or {}).get('card_instance_id')
            == short['instance_id']
        ]
        self.assertTrue(actions)
        self.assertEqual(
            {(action.get('payload') or {}).get('combo_speed') for action in actions},
            {4},
        )

        engine._start_combo_card('p1', [short['instance_id']], [4])
        pipeline = engine.engine_state['pipeline']
        self.assertEqual(pipeline['card']['counter'], '콤보')
        self.assertEqual(engine.card_stat(pipeline['card'], 'frame', 'p1'), 4)
        self.assertEqual(
            engine.engine_state['battle']['p1']['card']['counter'],
            support['counter'],
        )

