    def test_raging_punch_review_uses_real_hand_choice_and_single_combo_waiver(self):
        text = (
            '①손 판정 기술 상쇄 시 자신의 패에서 1장을 브레이크한다.\n'
            '②콤보 시 이 기술이 1콤보인 경우 콤보 타임 중 사용하는 기술 중 '
            '1장을 골라 데미지 보정을 적용하지 않을 수 있다. 그 경우 이번 '
            '자신의 겟 페이즈를 스킵한다.'
        )
        detail_text = (
            '①효과: 상대 배틀 존 기술의 신체 판정이 손인 경우 자신의 패 '
            '1장을 반드시 브레이크합니다. 패가 없다면 상쇄는 그대로 처리하고 '
            '브레이크만 처리하지 않습니다.\n'
            '②효과: 이 기술이 1콤보인 콤보 타임 중 원하는 시점에 한 기술의 '
            '데미지 보정을 적용하지 않을 수 있습니다. 실제 적용한 경우에만 '
            '이번 자신의 겟 페이즈를 스킵합니다.'
        )
        definition = build_effect_draft(
            'ST3-008', text, qna_ids=[288, 583, 650],
            detail_text=detail_text,
        )
        snapshot = {
            'code': 'ST3-008', 'name': '레이징 펀치', 'type': '공격',
            'text': text, 'detail_text': detail_text,
            'frame': 12, 'damage': 500, 'pos': '중단', 'body': '손',
            'special': '중단 상쇄', 'hit': '콤보', 'guard': '-9',
            'counter': '1', 'g_top': None, 'g_mid': '상쇄',
            'g_bot': None,
        }
        review = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(review.passed, review.as_dict())
        self.assertEqual(
            [len(item.scenarios) for item in review.abilities], [11, 8],
        )
        by_id = {item.ability_id: item for item in review.abilities}
        clash_scenarios = {
            item['name']: item for item in by_id['st3-008-n1'].scenarios
        }
        selected = clash_scenarios[
            'owner-p1-selects-second-hand-card-and-replenishes'
        ]
        self.assertEqual(selected['decision_kinds'], [
            'effect_choice', 'break_replenish',
        ])
        self.assertEqual(
            selected['break_ids'], ['p1-raging-punch-hand-2'],
        )
        self.assertEqual(selected['list_ids'], ['p1-raging-punch-side'])
        no_hand = clash_scenarios[
            'qna-583-empty-hand-keeps-clash-and-fizzles'
        ]
        self.assertEqual(no_hand['battle_owner_result'], 'clash')
        self.assertEqual(no_hand['choice_skipped_count'], 1)
        protected = clash_scenarios[
            'one-protected-card-leaves-only-legal-option'
        ]
        self.assertEqual(
            protected['first_option_ids'], ['p1-raging-punch-hand-2'],
        )

        combo_scenarios = {
            item['name']: item for item in by_id['st3-008-n2'].scenarios
        }
        later_choice = combo_scenarios[
            'qna-650-owner-p1-can-choose-second-card-later'
        ]
        self.assertEqual(later_choice['damage_amounts'], [400, 500])
        self.assertEqual(later_choice['get_skip_event_count'], 1)
        self.assertTrue(later_choice['get_skipped'])
        declined = combo_scenarios[
            'declining-waiver-keeps-both-normal-penalties'
        ]
        self.assertEqual(declined['damage_amounts'], [400, 300])
        self.assertEqual(declined['get_skip_event_count'], 0)
        self.assertFalse(declined['get_skipped'])
        special_first = combo_scenarios[
            'special-combo-raging-as-one-combo-previews-followup'
        ]
        self.assertEqual(special_first['ignore_patterns'], [
            [False, False], [False, True],
        ])
        self.assertEqual(special_first['damage_amounts'], [500, 500])
        normal_second = combo_scenarios[
            'raging-used-as-two-combo-does-not-grant-waiver'
        ]
        self.assertEqual(normal_second['ignore_patterns'], [[False, False]])
        self.assertEqual(normal_second['resolved_count'], 0)

        mutated = copy.deepcopy(definition)
        mutated['abilities'][1]['effects'][0]['skip_get_on_use'] = False
        self.assertFalse(review_automatic_definition(
            mutated, card_has_text=True, card_snapshot=snapshot,
        ).passed)

