    def test_dynamic_exact_count_choices_fill_lumen_and_trim_hand(self):
        text = (
            '①게임 중 1번 루멘 페이즈 시, 자신의 체력이 2000 이하라면 '
            '루멘 존의 [[token:calling_card]]이 3장이 되도록 사이드 덱에서 골라 '
            '루멘 존에 배치할 수 있다. 그 경우, 패가 5장 이상이라면 4장이 되도록 버린다.'
        )
        definition = build_effect_draft('DFR-AT-018', text)
        command = definition['abilities'][0]['effects'][0]
        self.assertEqual(command['op'], 'request_choice')
        self.assertIsInstance(command['selector']['min'], dict)

        hand = [attack(f'hand-{index}', 'p1') for index in range(5)]
        tokens = [{
            'instance_id': f'calling-{index}', 'kind': 'token', 'owner': 'p1',
            'code': 'PMP-CS-009', 'name': '예지', 'type': '토큰',
            'token_key': 'calling_card', 'face_up': False,
        } for index in range(3)]
        state = base_state(hand, [])
        state['players']['p1']['zones']['side'] = tokens
        release = ruleset(*hand, *tokens)
        engine = AutomaticGameEngine.initialize(state, release, seed='exact-count-choice')
        engine.resolver.execute_effects([command], {'controller': 'p1', 'ability_id': 'fill'})

        decision = engine.engine_state['pending_decision']
        self.assertEqual((decision['minimum'], decision['maximum']), (3, 3))
        self.act(engine, 'p1', 'submit_decision', {
            'selected': ['calling-0', 'calling-1', 'calling-2'],
        })
        decision = engine.engine_state['pending_decision']
        self.assertEqual((decision['minimum'], decision['maximum']), (1, 1))
        self.act(engine, 'p1', 'submit_decision', {'selected': ['hand-0']})

        self.assertEqual(len(engine._zone('p1', 'lumen')), 3)
        self.assertEqual(len(engine._zone('p1', 'hand')), 4)
        self.assertIsNotNone(engine._find_card('hand-0', owner='p1', zone='list'))
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_combo_bonus_after_source_and_second_use_penalty_exception(self):
        source_text = (
            '콤보 시, [[state:charge]]효과가 있는 기술을 이 기술 다음에 이을 경우 '
            '그 기술의 데미지+100'
        )
        command = infer_effect_commands(source_text)[0]
        self.assertEqual(command['damage_bonus'], 100)
        self.assertTrue(command['after_source'])

        repeated = build_effect_draft(
            'CB02-AT-026',
            '이 기술이 한 턴에 두 번 이상 사용되었을 경우, '
            '이 기술은 데미지 보정을 적용하지 않는다.',
        )
        repeated_rule = next(
            rule for rule in repeated['combo_rules']
            if rule.get('ignore_damage_penalty')
        )
        self.assertTrue(repeated_rule['ignore_damage_penalty'])
        self.assertEqual(repeated_rule['condition']['op'], 'used_card')

        source = attack('combo-source', 'p1', code='UNC-AT-017', hit='콤보')
        charged = attack('charged', 'p1', code='CHARGED', frame=6, damage=500)
        charged_followup = attack('charged-followup', 'p1', frame=7, damage=400)
        charged['text'] = '[[state:charge]]'
        release = ruleset(source, charged, charged_followup)
        engine = AutomaticGameEngine.initialize(
            base_state([charged, charged_followup], []), release,
            seed='combo-damage-bonus',
        )
        engine.state['phase'] = 'battle'
        engine.state['players']['p1']['zones']['battle'] = [source]
        engine.resolver.execute_effects(
            [command],
            {'controller': 'p1', 'source_card_instance_id': 'combo-source'},
        )
        engine.grant_combo('p1', source='combo-source')
        self.act(engine, 'p1', 'play_combo_pair')
        used = next(event for event in engine.events if event['type'] == 'combo_card_used')
        self.assertEqual(used['payload']['damage'], 500)

        repeated_card = attack('repeated', 'p1', code='CB02-AT-026', frame=6, damage=500)
        repeated_followup = attack('repeated-followup', 'p1', frame=7, damage=400)
        repeat_release = ruleset(source, repeated_card, repeated_followup)
        repeat_release['cards']['CB02-AT-026']['effect_definition'] = repeated
        repeat_engine = AutomaticGameEngine.initialize(
            base_state([repeated_card, repeated_followup], []), repeat_release,
            seed='second-use-combo',
        )
        repeat_engine.state['phase'] = 'battle'
        repeat_engine.state['players']['p1']['zones']['battle'] = [source]
        repeat_engine._mark_card_used(repeated_card, 'p1', 'ready')
        repeat_engine.grant_combo('p1', source='combo-source')
        self.act(repeat_engine, 'p1', 'play_combo_pair')
        used = next(event for event in repeat_engine.events if event['type'] == 'combo_card_used')
        self.assertEqual(used['payload']['damage'], 500)
        self.assertEqual(validate_effect_definition(repeated, card_has_text=True), [])

