    def test_charge_activation_expires_and_skips_only_its_owners_next_lumen(self):
        text = (
            '①루멘 페이즈 시 이번 턴까지 자신에게 [[state:charge]]상태를 부여할 수 있다.\n'
            '②[[state:charge]]: 자신은 레디 페이즈에 공격 기술만 레디한다.\n'
            '레디한 기술 사용 시, 2속도가 느려지며 기술 데미지+200\n'
            '③[[state:charge]]상태 해제 시, 다음 자신 루멘 페이즈를 스킵한다.'
        )
        definition = build_effect_draft('ST2-PS1', text)
        passive = attack('charge-duration-passive', 'p1', code='ST2-PS1')
        passive.update({'type': '특성', 'frame': None, 'damage': None})
        normal = attack('charge-duration-attack', 'p1', frame=5, damage=400)
        fixed = attack('charge-fixed-attack', 'p1', code='FIXED-SIX', frame=9, damage=300)
        defense_card = defense('charge-duration-defense', 'p1')
        state = base_state([normal, fixed, defense_card], [])
        state['players']['p1']['zones']['passive'] = [passive]
        release = ruleset(passive, normal, fixed, defense_card)
        release['cards']['ST2-PS1']['effect_definition'] = definition
        release['cards']['FIXED-SIX']['effect_definition'] = build_effect_draft(
            'FIXED-SIX', '이 기술은 6속도로 고정된다.',
        )
        engine = AutomaticGameEngine.initialize(state, release, seed='charge-duration')

        engine.state['phase'] = 'lumen'
        engine.engine_state['step'] = 'phase_actions'
        engine._fire('phase_start', {'phase': 'lumen'})
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.assertTrue(engine.state['players']['p1']['passive_state']['charge']['value'])

        engine.state['phase'] = 'ready'
        engine.engine_state['step'] = 'ready_actions'
        ready_ids = {
            item['payload']['card_instance_id'] for item in engine.legal_actions('p1')
            if item['type'] == 'ready_card'
        }
        self.assertEqual(ready_ids, {normal['instance_id'], fixed['instance_id']})
        engine._fire('use', {
            'controller': 'p1', 'source_card': normal,
            'source_card_instance_id': normal['instance_id'],
        })
        self.assertEqual(engine.card_stat(normal, 'frame', 'p1'), 7)
        self.assertEqual(engine.card_stat(normal, 'damage', 'p1'), 600)
        engine._fire('use', {
            'controller': 'p1', 'source_card': fixed,
            'source_card_instance_id': fixed['instance_id'],
        })
        self.assertEqual(engine.card_stat(fixed, 'frame', 'p1'), 6)

        engine.state['phase'] = 'recovery'
        engine.engine_state['step'] = 'phase_actions'
        engine._fire('phase_end', {'phase': 'recovery'})
        self.assertFalse(engine.state['players']['p1']['passive_state']['charge']['value'])
        self.assertTrue(engine.engine_state['skip_phases']['p1']['lumen'])
        engine._advance_phase()
        self.assertEqual(engine.state['phase'], 'lumen')
        self.assertEqual(engine.engine_state['phase_passes'], ['p1'])
        self.assertNotIn('pass_phase', {item['type'] for item in engine.legal_actions('p1')})
        self.assertIn('pass_phase', {item['type'] for item in engine.legal_actions('p2')})
        self.act(engine, 'p2', 'pass_phase')
        self.assertEqual(engine.state['phase'], 'ready')
        self.assertEqual(definition['trait_state_keys'], ['charge'])
        self.assertEqual(definition['trait_state_preserve_on_negation'], ['charge'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_charge_and_intimidation_resolve_by_priority_and_trait_negation_tracks_origin(self):
        charge_text = (
            '①루멘 페이즈 시 이번 턴까지 자신에게 [[state:charge]]상태를 부여할 수 있다.\n'
            '②[[state:charge]]: 자신은 레디 페이즈에 공격 기술만 레디한다.\n'
            '레디한 기술 사용 시, 2속도가 느려지며 기술 데미지+200\n'
            '③[[state:charge]]상태 해제 시, 다음 자신 루멘 페이즈를 스킵한다.'
        )
        intimidation_text = (
            '자신의 공격 기술이 상대에게 데미지를 줄 때마다 [[token:howling]]카운터를 1개 얻는다.\n'
            '루멘 페이즈 시 [[token:howling]]카운터를 5개 제거하는 것으로 '
            '자신에게 겟 페이즈 종료 시까지 [[state:intimidation]]상태를 부여할 수 있다.\n'
            '[[state:intimidation]]상태 시 레디 페이즈 시에 자신은 공격 기술만 낼 수 있으며 '
            '상대는 수비 기술만 낼 수 있다.'
        )
        charge_passive = attack('charge-conflict-passive', 'p1', code='ST2-PS1')
        charge_passive.update({'type': '특성', 'frame': None, 'damage': None})
        intimidation_passive = attack('intimidation-conflict-passive-2', 'p2', code='ST5-PS1')
        intimidation_passive.update({'type': '특성', 'frame': None, 'damage': None})
        p1_attack = attack('charge-conflict-attack', 'p1')
        p1_defense = defense('charge-conflict-defense', 'p1')
        state = base_state([p1_attack, p1_defense], [])
        state['priority_player'] = 'p1'
        state['players']['p1']['zones']['passive'] = [charge_passive]
        state['players']['p2']['zones']['passive'] = [intimidation_passive]
        state['players']['p2']['passive_state']['howling'] = {'count': 5}
        release = ruleset(charge_passive, intimidation_passive, p1_attack, p1_defense)
        release['cards']['ST2-PS1']['effect_definition'] = build_effect_draft(
            'ST2-PS1', charge_text,
        )
        release['cards']['ST5-PS1']['effect_definition'] = build_effect_draft(
            'ST5-PS1', intimidation_text,
        )
        engine = AutomaticGameEngine.initialize(state, release, seed='charge-conflict')
        engine.state['phase'] = 'lumen'
        engine.engine_state['step'] = 'phase_actions'
        engine._fire('phase_start', {'phase': 'lumen'})
        self.assertEqual(engine.engine_state['pending_decision']['owner'], 'p1')
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.assertIsNone(engine.engine_state.get('pending_decision'))
        self.assertTrue(engine.state['players']['p1']['passive_state']['charge']['value'])
        self.assertFalse(
            (engine.state['players']['p2']['passive_state'].get('intimidation') or {}).get('value', False),
        )
        self.assertEqual(engine.state['players']['p2']['passive_state']['howling']['count'], 5)

        charm = attack('charge-negation-charm', 'p2', code='AWL-SP-003')
        charm.update({'type': '특수', 'frame': None, 'damage': None})
        engine.state['players']['p2']['zones']['lumen'].append(charm)
        engine.ruleset['cards']['AWL-SP-003'] = {
            **charm,
            'effect_definition': build_effect_draft(
                'AWL-SP-003', '②이 특수기가 존재하는 동안 서로의 특성을 무효로 한다.',
            ),
        }
        engine._reconcile_trait_states()
        self.assertFalse(engine.state['players']['p1']['passive_state']['charge']['value'])
        engine.state['phase'] = 'ready'
        engine.engine_state['step'] = 'ready_actions'
        ready_ids = {
            item['payload']['card_instance_id'] for item in engine.legal_actions('p1')
            if item['type'] == 'ready_card'
        }
        self.assertEqual(ready_ids, {p1_attack['instance_id'], p1_defense['instance_id']})
        engine.set_passive('p1', 'charge', value=False)
        self.assertFalse((engine.engine_state.get('skip_phases') or {}).get('p1', {}).get('lumen', False))

