    def test_charm_deploys_at_exact_count_preserves_technique_state_and_pays_upkeep(self):
        text = (
            '①루멘 페이즈 시, [[token:hidden_bond]]카운터가 3개일 경우, '
            '사이드 덱에서 루멘 존에 배치할 수 있다.\n'
            '②이 특수기가 존재하는 동안 서로의 특성을 무효로 한다.\n'
            '③리커버리 페이즈 시, [[token:hidden_bond]]카운터 1개를 소모한다. '
            '[[token:hidden_bond]]카운터가 없다면 이 기술을 브레이크한다.'
        )
        qna_ids = [139, 140, 143, 220, 225, 376, 383, 439, 564]
        definition = build_effect_draft('AWL-SP-003', text, qna_ids=qna_ids)
        passive = attack('charm-passive', 'p1', code='ST2-PS1')
        passive.update({'type': '특성', 'frame': None, 'damage': None})
        technique = attack('charm-technique', 'p1')
        charm = attack('charm', 'p2', code='AWL-SP-003')
        charm.update({'type': '특수', 'frame': None, 'damage': None})
        state = base_state([technique], [])
        state['players']['p1']['zones']['passive'] = [passive]
        state['players']['p2']['zones']['side'] = [charm]
        state['players']['p2']['passive_state']['hidden_bond'] = {
            'count': 3, 'label': 'hidden_bond',
        }
        release = ruleset(passive, technique, charm)
        release['cards']['AWL-SP-003']['effect_definition'] = definition
        release['cards']['ST2-PS1']['effect_definition'] = {
            'schema_version': 1, 'abilities': [],
            'trait_state_keys': ['charge'],
            'trait_state_preserve_on_negation': ['charge'],
        }
        engine = AutomaticGameEngine.initialize(state, release, seed='charm-core')
        engine.resolver.execute_effect({'op': 'gain_state', 'state': 'charge'}, {
            'controller': 'p1', 'source_card': passive,
            'source_card_instance_id': passive['instance_id'],
        })
        self.assertTrue(
            engine.state['players']['p1']['passive_state']['charge']['trait_origin']
        )

        # Initialization opens the first Lumen phase trigger.
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p2', 'submit_decision', {'selected': ['accept']})

        self.assertIsNotNone(engine._find_card(charm['instance_id'], owner='p2', zone='lumen'))
        self.assertTrue(engine._traits_negated())
        self.assertFalse(engine.state['players']['p1']['passive_state']['charge']['value'])

        engine.resolver.execute_effect({'op': 'gain_state', 'state': 'charge'}, {
            'controller': 'p1', 'source_card': technique,
            'source_card_instance_id': technique['instance_id'],
        })
        engine._reconcile_trait_states()
        charge = engine.state['players']['p1']['passive_state']['charge']
        self.assertTrue(charge['value'])
        self.assertFalse(charge['trait_origin'])

        engine.state['phase'] = 'recovery'
        engine._fire('phase_start', {'phase': 'recovery'})
        self.assertEqual(
            engine.state['players']['p2']['passive_state']['hidden_bond']['count'], 2,
        )
        self.assertIsNotNone(engine._find_card(charm['instance_id'], owner='p2', zone='lumen'))
        engine._fire('phase_start', {'phase': 'recovery'})
        self.assertEqual(
            engine.state['players']['p2']['passive_state']['hidden_bond']['count'], 1,
        )
        engine._fire('phase_start', {'phase': 'recovery'})
        self.assertEqual(
            engine.state['players']['p2']['passive_state']['hidden_bond']['count'], 0,
        )
        self.assertIsNotNone(engine._find_card(charm['instance_id'], owner='p2', zone='break'))
        self.assertFalse(engine._traits_negated())
        self.assertEqual(
            definition['abilities'][0]['source_refs']['qna_ids'], qna_ids,
        )
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_light_lumen_applies_each_damage_reduction_blessings_and_derived_states(self):
        text = (
            '루멘 페이즈 시, 자신의 체력이 1000 이하일 경우 사이드 덱에서 '
            '루멘 존에 배치할 수 있다.\n'
            '이 기술이 루멘 존에 있는 동안 아래의 효과를 적용한다.\n'
            '이 기술은 상대 기술의 영향을 받지 않는다.\n'
            '-자신은 모든 레기온의 축복 효과와 상태를 적용한다.\n'
            '-자신이 받는 모든 데미지-100\n'
            '-[[state:saintess]]효과가 있는 기술 데미지+100'
        )
        qna_ids = [72, 220, 221, 409, 413, 483, 525, 539, 597]
        definition = build_effect_draft('LMI-AT-001', text, qna_ids=qna_ids)
        light = attack('light-lumen', 'p1', code='LMI-AT-001')
        light.update({'type': '특수', 'frame': None, 'damage': None})
        saintess = attack('saintess-technique', 'p1', damage=400)
        saintess['text'] = '[[state:saintess]] 효과가 있는 기술'
        ordinary = attack('ordinary-technique', 'p1', damage=400)
        opponent_card = attack('light-opponent', 'p2')
        charm = attack('light-charm', 'p2', code='AWL-SP-003')
        charm.update({'type': '특수', 'frame': None, 'damage': None})
        state = base_state([saintess, ordinary], [opponent_card])
        state['players']['p1']['zones']['lumen'] = [light]
        state['players']['p2']['zones']['lumen'] = [charm]
        release = ruleset(light, saintess, ordinary, opponent_card, charm)
        release['cards']['LMI-AT-001']['effect_definition'] = definition
        release['cards']['AWL-SP-003']['effect_definition'] = {
            'schema_version': 1, 'abilities': [],
            'trait_negation': {'players': 'both', 'active_zones': ['lumen']},
        }
        engine = AutomaticGameEngine.initialize(state, release, seed='light-lumen-core')
        engine._refresh_continuous_rules()

        for state_key in ('guardian', 'assassin', 'paladin'):
            self.assertTrue(condition_matches({
                'op': 'has_state', 'player': 'p1', 'state': state_key,
            }, engine.state, {}))
        self.assertTrue(engine._traits_negated())
        self.assertEqual(engine.card_stat(saintess, 'damage', 'p1'), 500)
        self.assertEqual(engine.card_stat(ordinary, 'damage', 'p1'), 400)

        hp_before = engine.state['players']['p1']['hp']
        for _index in range(3):
            self.assertEqual(engine.deal_damage('p1', 100, source='effect'), 0)
        self.assertEqual(engine.state['players']['p1']['hp'], hp_before)
        self.assertEqual(
            [
                event['payload']['amount'] for event in engine.events
                if event.get('type') == 'damage_dealt'
                and event.get('payload', {}).get('target') == 'p1'
            ][-3:],
            [0, 0, 0],
        )

        engine._fire('guard', {'controller': 'p1'})
        self.assertEqual(engine.state['players']['p1']['fp'], 2)
        opponent_hp = engine.state['players']['p2']['hp']
        engine._fire('counter', {'controller': 'p1'})
        self.assertEqual(engine.state['players']['p2']['hp'], opponent_hp - 100)

        self.assertEqual(definition['state_grants'][0]['states'], [
            'guardian', 'assassin', 'paladin',
        ])
        self.assertEqual(
            definition['abilities'][0]['source_refs']['qna_ids'], qna_ids,
        )
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

        deploy = attack('light-deploy', 'p1', code='LMI-AT-001')
        deploy.update({'type': '특수', 'frame': None, 'damage': None})
        deploy_state = base_state([], [], hp=1000)
        deploy_state['players']['p1']['zones']['side'] = [deploy]
        deploy_release = ruleset(deploy)
        deploy_release['cards']['LMI-AT-001']['effect_definition'] = definition
        deploy_engine = AutomaticGameEngine.initialize(
            deploy_state, deploy_release, seed='light-lumen-deploy',
        )
        self.assertEqual(
            deploy_engine.engine_state['pending_decision']['kind'], 'optional_effect',
        )
        self.act(deploy_engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.assertIsNotNone(
            deploy_engine._find_card(deploy['instance_id'], owner='p1', zone='lumen')
        )

