    def test_get_phase_can_shuffle_opponent_list_face_down(self):
        text = (
            '[[state:dark_night]]: 히트/카운터/콤보 시, 이번 턴 겟 페이즈 동안 '
            '상대는 리스트를 섞어 뒷면으로 배치한다.'
        )
        definition = build_effect_draft('CB01-AT-022', text)
        ability = next(
            item for item in definition['abilities']
            if item.get('id') == 'cb01-at-022-n2'
        )
        schedule = ability['effects'][0]
        self.assertEqual(schedule['effect']['op'], 'sequence')
        shuffle = schedule['effect']['effects'][0]
        self.assertEqual(shuffle['op'], 'shuffle_zone')

        cards = [attack(f'list-{index}', 'p2') for index in range(3)]
        state = base_state([], [])
        state['players']['p2']['zones']['list'] = cards
        engine = AutomaticGameEngine.initialize(state, ruleset(*cards), seed='face-down-list')
        before = [card['instance_id'] for card in engine._zone('p2', 'list')]
        engine.resolver.execute_effects([shuffle], {'controller': 'p1'})
        after = [card['instance_id'] for card in engine._zone('p2', 'list')]

        self.assertCountEqual(after, before)
        self.assertTrue(all(not card['face_up'] for card in engine._zone('p2', 'list')))
        engine.state['phase'] = 'get'
        engine.move_card(after[0], 'hand', reason='get')
        self.assertTrue(engine._find_card(after[0], owner='p2', zone='hand')['face_up'])
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_resonance_damage_trigger_consumes_token_and_is_per_card_limited(self):
        text = (
            '기술당 한번, <잔향>판정의 기술로 상대에게 데미지를 주었을 때 '
            '루멘 존의 [[token:spider]]토큰 1장을 제거하고 '
            '상대에게 200데미지를 줄 수 있다.'
        )
        definition = build_effect_draft('PMP-PS-001', text)
        ability = definition['abilities'][0]
        self.assertEqual(ability['trigger']['event'], 'damage_after')
        self.assertTrue(ability['limit']['per_event_card'])

        passive = {
            'instance_id': 'spider-passive', 'kind': 'card', 'owner': 'p1',
            'code': 'PMP-PS-001', 'name': '거미 특성', 'type': '특성', 'face_up': True,
        }
        resonance = attack('resonance', 'p1', special='잔향')
        spider = {
            'instance_id': 'spider-token', 'kind': 'card', 'owner': 'p1',
            'code': 'PMP-AT-053', 'name': '거미', 'type': '토큰',
            'token_key': 'spider', 'face_up': True,
        }
        state = base_state([], [], hp=1000)
        state['players']['p1']['zones']['passive'] = [passive]
        state['players']['p1']['zones']['lumen'] = [spider]
        release = ruleset(passive, resonance, spider)
        release['cards']['PMP-PS-001']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='resonance-passive')
        engine._fire('damage_after', {
            'controller': 'p1', 'source_card': resonance,
            'source_card_instance_id': 'resonance', 'amount': 100,
        })
        self.assertEqual(engine.engine_state['pending_decision']['kind'], 'optional_effect')
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.act(engine, 'p1', 'submit_decision', {'selected': ['spider-token']})

        self.assertIsNone(engine._find_card('spider-token'))
