    def test_required_play_costs_gate_actions_and_resume_after_payment(self):
        state_cost_text = (
            '패에서 [[state:guardian]], [[state:assassin]], [[state:paladin]] '
            '효과가 있는 기술 2장을 버리지 않으면 사용할 수 없다.'
        )
        definition = build_effect_draft('TEST-AT-COST', state_cost_text)
        self.assertEqual(infer_play_costs(state_cost_text), definition['play_costs'])
        self.assertEqual(definition['play_costs'][0]['operation'], 'discard')

        source = attack('cost-source', 'p1', code='TEST-AT-COST')
        guardian = attack('guardian-cost', 'p1')
        guardian['text'] = '[[state:guardian]]'
        paladin = attack('paladin-cost', 'p1')
        paladin['text'] = '[[state:paladin]]'
        release = ruleset(source, guardian, paladin)
        release['cards']['TEST-AT-COST']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(
            base_state([source, guardian, paladin], []), release, seed='play-cost',
        )
        engine.state['phase'] = 'ready'
        engine.engine_state['step'] = 'ready_actions'
        action = next(
            item for item in engine.legal_actions('p1')
            if item['type'] == 'ready_card'
            and item['payload']['card_instance_id'] == 'cost-source'
        )
        engine.submit_action('p1', action['action_id'], {}, command_id='choose-cost-card')

        decision = engine.engine_state['pending_decision']
        self.assertEqual(decision['kind'], 'play_cost')
        self.assertEqual((decision['minimum'], decision['maximum']), (2, 2))
