    def test_pmp_at_009_token_cost_hp_loss_and_combo_heal_runtime(self):
        text = (
            '루멘 존의 [[token:spider]]토큰 4장을 제거해야만 사용할 수 있다.\n'
            '①사용 시, 체력 400을 지불한다.\n'
            '②콤보 타임 종료 시, 콤보에 사용한 기술 1장당 체력 100을 회복한다.'
        )
        definition = build_effect_draft('PMP-AT-009', text, qna_ids=[627])
        self.assertNotIn('condition', definition['abilities'][1])
        self.assertEqual(definition['abilities'][2]['active_zones'], ['battle'])
        self.assertEqual(definition['abilities'][2]['effects'][0]['amount'], {
            'op': 'multiply',
            'values': [100, {'path': 'context.combo_used_count'}],
        })

        source = attack('pmp-nine', 'p1', code='PMP-AT-009', frame=13, damage=700)
        spiders = [
            attack(f'spider-{index}', 'p1', code='SPIDER-TOKEN')
            for index in range(5)
        ]
        for spider in spiders:
            spider['token_key'] = 'spider'
            spider['type'] = '특수'
        state = base_state([source], [])
        state['players']['p1']['zones']['lumen'] = spiders
        release = ruleset(source, spiders[0])
        release['cards']['PMP-AT-009']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='pmp-at-009-cost')
        engine.state['phase'] = 'ready'
        engine.engine_state['step'] = 'ready_actions'
        ready_action = next(
            action for action in engine.legal_actions('p1')
            if action['type'] == 'ready_card'
            and action['payload']['card_instance_id'] == source['instance_id']
        )
        engine.submit_action(
            'p1', ready_action['action_id'], {}, command_id='pmp-nine-ready',
        )
        decision = engine.engine_state['pending_decision']
        self.assertEqual(decision['kind'], 'play_cost')
        self.assertEqual((decision['minimum'], decision['maximum']), (4, 4))
        option_ids = sorted(option['id'] for option in decision['options'])
        self.assertEqual(len(option_ids), 5)
        self.act(engine, 'p1', 'submit_decision', {'selected': option_ids[:4]})
        self.assertIsNotNone(engine._find_card('pmp-nine', owner='p1', zone='battle'))
        self.assertEqual(len(engine.state['players']['p1']['zones']['lumen']), 1)
        self.assertEqual(
            engine.state['players']['p1']['zones']['lumen'][0]['instance_id'],
            option_ids[4],
        )

        short_source = attack(
            'pmp-nine-short', 'p1', code='PMP-AT-009', frame=13, damage=700,
        )
        short_spiders = [
            attack(f'short-spider-{index}', 'p1', code='SPIDER-TOKEN')
            for index in range(3)
        ]
        for spider in short_spiders:
            spider.update({'token_key': 'spider', 'type': '특수'})
        short_state = base_state([short_source], [])
        short_state['players']['p1']['zones']['lumen'] = short_spiders
        short_release = ruleset(short_source, short_spiders[0])
        short_release['cards']['PMP-AT-009']['effect_definition'] = definition
        short_engine = AutomaticGameEngine.initialize(
            short_state, short_release, seed='pmp-at-009-short',
        )
        short_engine.state['phase'] = 'ready'
        short_engine.engine_state['step'] = 'ready_actions'
        self.assertFalse(any(
            action['type'] == 'ready_card'
            and action['payload']['card_instance_id'] == short_source['instance_id']
            for action in short_engine.legal_actions('p1')
        ))

        hp_source = attack(
            'pmp-nine-hp', 'p1', code='PMP-AT-009', frame=13, damage=700,
        )
        hp_state = base_state([], [])
        hp_state['players']['p1']['zones']['battle'] = [hp_source]
        hp_state['players']['p1']['hp'] = 300
        hp_release = ruleset(hp_source)
        hp_release['cards']['PMP-AT-009']['effect_definition'] = definition
        hp_engine = AutomaticGameEngine.initialize(
            hp_state, hp_release, seed='pmp-at-009-hp',
        )
        hp_engine._fire('use', {
            'controller': 'p1', 'source_card_instance_id': hp_source['instance_id'],
            'source_card': hp_engine._find_card(hp_source['instance_id']),
        })
        self.assertEqual(hp_engine.state['players']['p1']['hp'], 0)
        self.assertEqual(hp_engine.state['engine']['winner'], 'p2')

        heal_source = attack(
            'pmp-nine-heal', 'p1', code='PMP-AT-009', frame=13, damage=700,
        )
        heal_state = base_state([], [])
        heal_state['players']['p1']['zones']['battle'] = [heal_source]
        heal_state['players']['p1']['hp'] = 3000
        heal_release = ruleset(heal_source)
        heal_release['cards']['PMP-AT-009']['effect_definition'] = definition
        heal_engine = AutomaticGameEngine.initialize(
            heal_state, heal_release, seed='pmp-at-009-heal',
        )
        heal_engine.engine_state['combo'] = {
            'owner': 'p1', 'source': heal_source['instance_id'],
            'used': ['combo-2', 'combo-3', 'combo-4'], 'next_penalty': 400,
        }
        heal_engine.end_combo()
        heal_engine._continue()
        self.assertEqual(heal_engine.state['players']['p1']['hp'], 3300)

        review = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'PMP-AT-009', 'name': '피의 만찬', 'type': '공격',
                'text': text, 'frame': 13, 'damage': 700, 'pos': '하단',
            },
        )
        self.assertTrue(review.passed)
        cost_scenarios = {
            item['name']: item for item in review.abilities[0].scenarios
        }
        self.assertEqual(
            len(cost_scenarios['owner-p1-choose-four-of-five']['option_ids']), 5,
        )
        self.assertFalse(cost_scenarios['three-tokens-illegal']['legal'])
        hp_scenarios = {
            item['name']: item for item in review.abilities[1].scenarios
        }
        self.assertEqual(hp_scenarios['qna-627-owner-p2-loses']['after'], 0)
        self.assertEqual(hp_scenarios['qna-627-owner-p2-loses']['winner'], 'p1')
        heal_scenarios = {
            item['name']: item for item in review.abilities[2].scenarios
        }
        self.assertEqual(heal_scenarios['owner-p2-three-cards']['after'], 3300)
        self.assertEqual(heal_scenarios['opponent-combo-no-heal']['after'], 3000)

