    def test_linear_buster_review_covers_each_zone_and_zero_selection(self):
        text = (
            '①히트/카운터/콤보 시, 패/리스트/배틀 존에서 [리니어 버스터] '
            '이외의 기술을 각각 1장까지 브레이크할 수 있다. 그 경우, '
            '브레이크한 기술 1장당 이 기술 데미지+100'
        )
        definition = build_effect_draft('DFR-AT-041', text)
        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'DFR-AT-041', 'name': '리니어 버스터',
                'type': '공격', 'text': text, 'damage': 600,
            },
        )
        self.assertTrue(result.passed)
        scenarios = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        all_zones = scenarios['owner-p1-all-zones']
        self.assertEqual(len(all_zones['break_ids']), 3)
        self.assertEqual(all_zones['source_damage'], 900)
        self.assertEqual(
            [item['option_ids'] for item in all_zones['decisions'][1:]],
            [
                all_zones['candidate_ids']['hand'],
                all_zones['candidate_ids']['list'],
                all_zones['candidate_ids']['battle'],
            ],
        )
        two_zones = scenarios['owner-p2-two-zones']
        self.assertEqual(
            [item['option_ids'] for item in two_zones['decisions'][1:]],
            [
                two_zones['candidate_ids']['hand'],
                two_zones['candidate_ids']['list'],
            ],
        )
        self.assertEqual(two_zones['source_damage'], 800)
        zero = scenarios['accepts-zero-cards']
        self.assertFalse(zero['break_ids'])
        self.assertEqual(zero['source_damage'], 600)
        initially_protected = scenarios['initial-protection-excludes-hand']
        self.assertNotIn(
            initially_protected['initially_protected_id'],
            [
                option_id
                for decision in initially_protected['decisions']
                for option_id in decision['option_ids']
            ],
        )
        self.assertEqual(initially_protected['source_damage'], 800)
        protected_after_choice = scenarios[
            'late-protection-counts-only-successes'
        ]
        self.assertNotIn(
            protected_after_choice['protected_after_choice_id'],
            protected_after_choice['break_ids'],
        )
        self.assertEqual(protected_after_choice['ignored_count'], 1)
        self.assertEqual(protected_after_choice['source_damage'], 800)
        self.assertFalse(scenarios['numbered-effect-negated']['decisions'])

        mutated = copy.deepcopy(definition)
        damage = (
            mutated['abilities'][0]['effects'][0]['then'][0]['then'][0]
            ['then'][-1]
        )
        damage['amount']['values'][0] = 200
        self.assertFalse(review_automatic_definition(
            mutated, card_has_text=True,
            card_snapshot={
                'code': 'DFR-AT-041', 'name': '리니어 버스터',
                'type': '공격', 'text': text, 'damage': 600,
            },
        ).passed)

    def test_fry_swing_review_uses_only_the_immediate_combo_predecessor(self):
        text = (
            '①콤보 시, 2~3콤보에 사용했다면 이 기술 앞에 사용한 기술을 '
            '브레이크할 수 있다. 그 경우, 이 기술 데미지+200'
        )
        definition = build_effect_draft(
            'UNC-AT-048', text, qna_ids=[593],
        )
        result = review_automatic_definition(
            definition, card_has_text=True,
            card_snapshot={
                'code': 'UNC-AT-048', 'name': '프라이 스윙',
                'type': '공격', 'text': text, 'damage': 400,
            },
        )
        self.assertTrue(result.passed)
        scenarios = {
            item['name']: item for item in result.abilities[0].scenarios
        }
        second = scenarios['owner-p1-second-combo']
        self.assertEqual(
            second['decisions'][1]['option_ids'], [second['previous_id']],
        )
        self.assertTrue(all(
            card_id in second['battle_ids'] for card_id in second['older_ids']
        ))
        self.assertEqual(second['source_damage'], 600)
        third = scenarios['owner-p2-third-combo']
        self.assertEqual(
            third['decisions'][1]['option_ids'], [third['previous_id']],
        )
