    def test_publication_schema_requires_three_deterministic_scenarios_per_ability(self):
        definition = {
            'schema_version': 1, 'reviewed': True,
            'source_refs': {'rulebook_pages': [36], 'qna_ids': []},
            'abilities': [{
                'id': 'reviewed-use', 'kind': 'effect', 'mode': 'mandatory',
                'trigger': {'event': 'use'}, 'timing': 'use',
                'effects': [{'op': 'change_fp', 'amount': 1}],
            }],
            'review_evidence': {
                'method': 'automatic-effect-v2', 'passed': True,
                'scenario_count': 3,
                'abilities': [{
                    'ability_id': 'reviewed-use', 'passed': True,
                    'scenarios': [
                        {
                            'name': f'use-{index}', 'passed': True,
                            'deterministic': True,
                        }
                        for index in range(3)
                    ],
                }],
            },
        }
        self.assertEqual(validate_effect_definition(
            definition, require_coverage=True,
        ), [])

        missing = copy.deepcopy(definition)
        missing.pop('review_evidence')
        self.assertIn('missing_review_evidence', {
            issue.code for issue in validate_effect_definition(
                missing, require_coverage=True,
            )
        })

        insufficient = copy.deepcopy(definition)
        insufficient['review_evidence']['abilities'][0]['scenarios'].pop()
        insufficient['review_evidence']['scenario_count'] = 2
        self.assertIn('insufficient_review_scenarios', {
            issue.code for issue in validate_effect_definition(
                insufficient, require_coverage=True,
            )
        })

        nondeterministic = copy.deepcopy(definition)
        nondeterministic['review_evidence']['abilities'][0][
            'scenarios'
        ][1]['deterministic'] = False
        self.assertIn('nondeterministic_review_scenario', {
            issue.code for issue in validate_effect_definition(
                nondeterministic, require_coverage=True,
            )
        })

        wrong_id = copy.deepcopy(definition)
        wrong_id['review_evidence']['abilities'][0][
            'ability_id'
        ] = 'different-ability'
        self.assertIn('missing_ability_review', {
            issue.code for issue in validate_effect_definition(
                wrong_id, require_coverage=True,
            )
        })

