    def test_same_timing_effect_order_is_player_choice_and_alternates_by_priority(self):
        def passive_card(instance_id, owner, code, ability_id, effect):
            card = attack(instance_id, owner, code=code)
            card.update({'type': '패시브', 'frame': None, 'damage': None, 'face_up': True})
            definition = {
                'schema_version': 1, 'reviewed': True, 'no_effect': False,
                'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [597]},
                'abilities': [{
                    'id': ability_id, 'label': ability_id,
                    'kind': 'function', 'mode': 'mandatory',
                    'timing': 'function', 'visibility': 'public',
                    'active_zones': ['passive'],
                    'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [597]},
                    'trigger': {'event': 'phase_start'},
                    'effects': [effect],
                }],
            }
            return card, definition

        p1_reset, p1_reset_definition = passive_card(
            'p1-order-reset', 'p1', 'ORDER-P1-RESET', 'p1-reset',
            {'op': 'reset_fp', 'player': {'controller': True}},
        )
        p1_gain, p1_gain_definition = passive_card(
            'p1-order-gain', 'p1', 'ORDER-P1-GAIN', 'p1-gain',
            {'op': 'change_fp', 'player': {'controller': True}, 'amount': 5},
        )
        p2_first, p2_first_definition = passive_card(
            'p2-order-first', 'p2', 'ORDER-P2-FIRST', 'p2-first',
            {'op': 'change_fp', 'player': {'controller': True}, 'amount': 1},
        )
        p2_second, p2_second_definition = passive_card(
            'p2-order-second', 'p2', 'ORDER-P2-SECOND', 'p2-second',
            {'op': 'change_fp', 'player': {'controller': True}, 'amount': 2},
        )
        cards = [p1_reset, p1_gain, p2_first, p2_second]
        definitions = {
            p1_reset['code']: p1_reset_definition,
            p1_gain['code']: p1_gain_definition,
            p2_first['code']: p2_first_definition,
            p2_second['code']: p2_second_definition,
        }
        state = base_state([], [], p1_fp=3, p2_fp=0)
        state['priority_player'] = 'p1'
        state['players']['p1']['zones']['passive'] = [p1_reset, p1_gain]
        state['players']['p2']['zones']['passive'] = [p2_first, p2_second]
        release = ruleset(*cards)
        for card in cards:
            release['cards'][card['code']]['effect_definition'] = definitions[card['code']]
        engine = AutomaticGameEngine(state, release, seed='same-timing-order')

        engine._fire('phase_start', {'phase': 'lumen'})

        first = engine.engine_state['pending_decision']
        self.assertEqual(first['kind'], 'effect_order')
        self.assertEqual(first['owner'], 'p1')
        self.assertEqual(
            {option['ability_id'] for option in first['options']},
            {'p1-reset', 'p1-gain'},
        )
        self.assertTrue(all(
            option['effect_mode'] == 'mandatory'
            and option['source_zone'] == 'passive'
            and option['active_zones'] == ['passive']
            and option['card_instance_id'] in {
                'p1-order-reset', 'p1-order-gain',
            }
            for option in first['options']
        ))
        p2_observation = engine.observe('p2')['pending_decision']
        self.assertEqual(p2_observation['owner'], 'p1')
        self.assertNotIn('options', p2_observation)
        gain_option = next(
            option['id'] for option in first['options']
            if option['ability_id'] == 'p1-gain'
        )
        engine._submit_decision('p1', first['id'], [gain_option])
        engine._continue()

        second = engine.engine_state['pending_decision']
        self.assertEqual(second['kind'], 'effect_order')
        self.assertEqual(second['owner'], 'p2')
        first_p2_option = next(
            option['id'] for option in second['options']
            if option['ability_id'] == 'p2-first'
        )
        engine._submit_decision('p2', second['id'], [first_p2_option])
        engine._continue()

        history = engine.engine_state['ability_resolution_history']
        self.assertEqual(
            [(item['player'], item['ability_id']) for item in history],
            [
                ('p1', 'p1-gain'), ('p2', 'p2-first'),
                ('p1', 'p1-reset'), ('p2', 'p2-second'),
            ],
        )
        self.assertEqual(engine.state['players']['p1']['fp'], 0)
        self.assertEqual(engine.state['players']['p2']['fp'], 3)
        self.assertEqual(engine.engine_state['resolution_order_groups'], {})

    def test_effect_order_timeout_uses_stable_first_option(self):
        first = attack('timeout-order-a', 'p1', code='TIMEOUT-ORDER-A')
        second = attack('timeout-order-b', 'p1', code='TIMEOUT-ORDER-B')
        for card in (first, second):
            card.update({'type': '패시브', 'frame': None, 'damage': None, 'face_up': True})
        state = base_state([], [])
        state['players']['p1']['zones']['passive'] = [first, second]
        release = ruleset(first, second)
        for index, card in enumerate((first, second)):
            release['cards'][card['code']]['effect_definition'] = {
                'schema_version': 1, 'reviewed': True,
                'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [597]},
                'abilities': [{
                    'id': f'timeout-order-{index}', 'label': f'순서 {index}',
                    'kind': 'function', 'mode': 'mandatory',
                    'timing': 'function', 'visibility': 'public',
                    'active_zones': ['passive'],
                    'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [597]},
                    'trigger': {'event': 'phase_start'},
                    'effects': [{
                        'op': 'change_fp', 'player': {'controller': True},
                        'amount': index + 1,
                    }],
                }],
            }
        engine = AutomaticGameEngine(
            state, release,
            seed='effect-order-timeout',
            now=datetime(2026, 8, 19, tzinfo=timezone.utc),
        )
        engine._fire('phase_start', {'phase': 'lumen'})
        decision = copy.deepcopy(engine.engine_state['pending_decision'])
        self.assertEqual(decision['kind'], 'effect_order')

        engine.now = datetime.fromisoformat(
            engine.engine_state['clock']['deadline'],
        ) + timedelta(seconds=1)
        engine.reconcile_clock()

        history = engine.engine_state['ability_resolution_history']
        self.assertEqual(history[0]['ability_id'], 'timeout-order-0')
        self.assertEqual(len(history), 2)
        self.assertIsNone(engine.engine_state['pending_decision'])

