    def test_sudden_death_rebuild_uses_current_hand_limit_and_lumen_pool(self):
        p1_cards = [attack(f'p1-{index}', 'p1') for index in range(15)]
        p2_cards = [attack(f'p2-{index}', 'p2') for index in range(15)]
        engine = self.make_engine(p1_cards, p2_cards)
        for side in ('p1', 'p2'):
            player = engine.state['players'][side]
            player['character'] = {'hand_table': {'1000': 2, '5000': 5}}
            lumen_card = player['zones']['hand'].pop()
            player['zones']['lumen'].append(lumen_card)

        engine._start_sudden_death()

        for side in ('p1', 'p2'):
            zones = engine.state['players'][side]['zones']
            self.assertEqual(len(zones['hand']), 2)
            self.assertEqual(len(zones['list']), 9)
            self.assertEqual(len(zones['lumen']), 0)

