    def test_attached_and_break_zone_catch_phrases_compile_with_after_use_break(self):
        attached_definition = build_effect_draft(
            'CB03-AT-033',
            '②방어 시, 200데미지를 받는다. 그 후 세트된 '
            '<8속도 이하> 기술로 캐치할 수 있다.',
        )
        attached_grant = next(
            effect for effect in attached_definition['abilities'][0]['effects']
            if effect.get('op') == 'grant_catch'
        )

        self.assertTrue(attached_grant['source_attached'])
        self.assertEqual(attached_grant['max_speed'], 8)
        self.assertEqual(validate_effect_definition(attached_definition, card_has_text=True), [])

        break_definition = build_effect_draft(
            'PMP-AT-045',
            '①판정 후, 자신이 데미지를 받지 않았다면 패 1장을 '
            '브레이크할 수 있다. 그 경우, 브레이크 존의 '
            '<8속도 이하 [[character:rin]]> 기술로 캐치할 수 있다. '
            '캐치한 기술은 사용 후, 브레이크한다.',
        )
        break_choice = break_definition['abilities'][0]['effects'][0]
        break_grant = break_choice['then'][1]['then'][0]

        self.assertEqual(break_grant['allow_zones'], ['break'])
        self.assertEqual(break_grant['max_speed'], 8)
        self.assertEqual(break_grant['where'], {'character_key': 'rin'})
        self.assertTrue(break_grant['break_after_use'])
        self.assertEqual(validate_effect_definition(break_definition, card_has_text=True), [])

    def test_granted_catch_can_break_the_catch_card_after_use(self):
        source = defense('catch-source', 'p1')
        catch_card = attack('catch-card', 'p1', frame=8, damage=500)
        state = base_state([catch_card], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        engine = AutomaticGameEngine.initialize(
            state, ruleset(source, catch_card), seed='catch-break-after-use',
        )
        engine.resolver.execute_effects([{
            'op': 'grant_catch', 'player': {'controller': True},
            'allow_zones': ['hand'], 'max_speed': 8, 'break_after_use': True,
        }], {
            'controller': 'p1', 'source_card_instance_id': source['instance_id'],
        })
        catch = engine.engine_state['granted_catches'].pop()
        engine.engine_state['catch'] = catch

