    def test_card_catch_rule_breaks_only_after_hit_damage_and_after_use(self):
        text = (
            '①히트 시, 이 기술의 데미지+100\n'
            '②캐치 시, 9속도로 사용할 수 있다.\n'
            '그 경우, 이 기술을 브레이크한다.'
        )
        definition = build_effect_draft('UNC-AT-050', text)
        catch_card = attack(
            'rolling-spinner', 'p1', code='UNC-AT-050', frame=12,
            damage=500, hit='콤보',
        )
        state = base_state([catch_card], [], hp=5000)
        state['phase'] = 'battle'
        release = ruleset(catch_card)
        release['cards']['UNC-AT-050']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(
            state, release, seed='card-catch-rule-after-use',
        )
        catch = {'owner': 'p1', 'max_speed': 9}

        self.assertIn(
            catch_card['instance_id'],
            {
                card['instance_id']
                for card in engine._legal_catch_cards('p1', catch)
            },
        )
        engine.engine_state['catch'] = catch
        hp_before = engine.state['players']['p2']['hp']
        engine._play_catch('p1', catch_card['instance_id'])
        engine._continue()

        self.assertEqual(hp_before - engine.state['players']['p2']['hp'], 600)
        self.assertIsNotNone(engine._find_card(
            catch_card['instance_id'], owner='p1', zone='break',
        ))
        self.assertFalse(any(
            event['type'] == 'catch_interrupted' for event in engine.events
        ))
        damage_index = next(
            index for index, event in enumerate(engine.events)
            if event['type'] == 'damage_dealt'
        )
        break_index = next(
            index for index, event in enumerate(engine.events)
            if event['type'] == 'card_broken'
            and event['payload'].get('reason') == 'card_catch_rule_after_use'
        )
        self.assertLess(damage_index, break_index)
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])


    def test_phase_scoped_amount_choice_removes_howling_and_opponent_fp(self):
        text = (
            '①이 기술이 얼티밋 존에 있는 동안 이하의 효과를 적용한다. '
            '루멘 페이즈 시, 임의의 [[token:howling]]카운터를 제거할 수 있다. '
            '그 경우, 제거한 카운터 1개당 상대는 1FP를 잃는다.'
        )
        definition = build_effect_draft('CB01-AT-016', text)
        source = attack('howling-ultimate', 'p1', code='CB01-AT-016')
        state = base_state([], [], p2_fp=5)
        state['players']['p1']['zones']['ultimate'] = [source]
        release = ruleset(source)
        release['cards']['CB01-AT-016']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='howling-amount')
        engine.change_counter('p1', 'howling', 3)

        engine.state['phase'] = 'recovery'
        engine._fire('phase_start', {'phase': 'recovery'})
        self.assertIsNone(engine.engine_state['pending_decision'])

        engine.state['phase'] = 'lumen'
        engine._fire('phase_start', {'phase': 'lumen'})
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
