        state['players']['p1']['zones']['battle'] = [previous, current]
        release = ruleset(previous, current)
        release['cards']['UNC-AT-048']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='combo-previous')
        engine.engine_state['combo'] = {
            'owner': 'p1', 'source': previous['instance_id'],
            'used': [current['instance_id']],
        }

        engine._fire('combo', {
            'controller': 'p1', 'source_card': current,
            'source_card_instance_id': current['instance_id'],
            'combo': True, 'combo_number': 2, 'source_only_event': True,
        })
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        decision = engine.engine_state['pending_decision']
        self.assertEqual([option['id'] for option in decision['options']], [previous['instance_id']])
        self.act(engine, 'p1', 'submit_decision', {'selected': [previous['instance_id']]})

        self.assertIsNotNone(engine._find_card(previous['instance_id'], owner='p1', zone='break'))
        self.assertEqual(engine.card_stat(current, 'damage', 'p1'), 600)
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])


