    def test_choice_branch_pays_two_daggers_before_repeated_damage(self):
        definition = build_effect_draft(
            'CB02-AT-029',
            '①히트/카운터/콤보 시, 이하의 효과 중 하나를 적용할 수 있다. '
            '-루멘 존의 [[token:dagger]]토큰 2장을 브레이크하고 '
            '상대에게 100데미지를 2번 준다. '
            '-패 혹은 리스트의 [[card:AWL-AT-009]]를 사이드 덩으로 보내고 '
            '상대에게 500 데미지를 준다.',
        )
        source = attack('branch-source', 'p1', code='CB02-AT-029')
        daggers = [
            {
                'instance_id': f'dagger-{index}', 'kind': 'token', 'owner': 'p1',
                'code': f'DAGGER-{index}', 'name': 'Dagger', 'type': '토큰',
                'token_key': 'dagger', 'face_up': True,
            }
            for index in range(2)
        ]
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        state['players']['p1']['zones']['lumen'] = daggers
        release = ruleset(source, *daggers)
        release['cards']['CB02-AT-029']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='choice-daggers')

        engine._fire('hit', {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
        })
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.assertEqual(
            [option['id'] for option in engine.engine_state['pending_decision']['options']],
            ['daggers'],
        )
        self.act(engine, 'p1', 'submit_decision', {'selected': ['daggers']})
        self.act(engine, 'p1', 'submit_decision', {
            'selected': [card['instance_id'] for card in daggers],
        })

        self.assertEqual(engine.state['players']['p2']['hp'], 4800)
        self.assertTrue(all(
            engine._find_card(card['instance_id'], owner='p1', zone='break')
            for card in daggers
        ))
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_calling_card_exchange_invalidates_opponent_and_restarts_ready(self):
        definition = build_effect_draft(
            'AWL-AT-033',
            '이 기술은 [[state:advance_notice]]상태 일 때만 사용할 수 있다. '
            '①판정 전, 루멘 존의 [[token:calling_card]]을 사이드 덩의 '
            '[[token:calling_card]]과 교체한다. 교체 시, 이 기술을 브레이크 후 '
            '상대 기술을 무효로 하고 패로 올린다. 그 후, 자신은 2FP를 얻고 '
            '다시 레디 페이즈를 진행한다.',
        )
        source = attack('exchange-source', 'p1', code='AWL-AT-033')
        opponent_card = attack('exchange-opponent', 'p2')
        old_token = {
            'instance_id': 'calling-old', 'kind': 'token', 'owner': 'p1',
            'code': 'CALLING-OLD', 'name': 'Calling Card', 'type': '토큰',
            'token_key': 'calling_card', 'face_up': True,
        }
        new_token = {
            **old_token, 'instance_id': 'calling-new', 'code': 'CALLING-NEW',
            'face_up': False,
        }
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        state['players']['p2']['zones']['battle'] = [opponent_card]
        state['players']['p1']['zones']['lumen'] = [old_token]
        state['players']['p1']['zones']['side'] = [new_token]
        release = ruleset(source, opponent_card, old_token, new_token)
        release['cards']['AWL-AT-033']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='calling-exchange')
        engine.state['phase'] = 'battle'
        engine.engine_state['battle'] = {
            'p1': {'card': source}, 'p2': {'card': opponent_card},
        }

        engine._fire('before_judgment', {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
            'opponent_card': opponent_card,
        })
        self.act(engine, 'p1', 'submit_decision', {'selected': [old_token['instance_id']]})
        self.act(engine, 'p1', 'submit_decision', {'selected': [new_token['instance_id']]})

        self.assertIsNotNone(engine._find_card(old_token['instance_id'], owner='p1', zone='side'))
        self.assertIsNotNone(engine._find_card(new_token['instance_id'], owner='p1', zone='lumen'))
        self.assertFalse(engine._find_card(old_token['instance_id'])['face_up'])
        self.assertTrue(engine._find_card(new_token['instance_id'])['face_up'])
        self.assertIsNotNone(engine._find_card(source['instance_id'], owner='p1', zone='break'))
        self.assertIsNotNone(engine._find_card(opponent_card['instance_id'], owner='p2', zone='hand'))
        self.assertEqual(engine.state['players']['p1']['fp'], 2)
        self.assertEqual(engine.state['phase'], 'ready')
        self.assertIsNone(engine.engine_state.get('pipeline'))
        self.assertFalse(any(
            event.get('type') == 'battle_end' for event in engine.events
        ))
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_dodge_combo_cost_grants_combo_and_limits_hidden_bond_gain(self):
        definition = build_effect_draft(
            'UNC-AT-036',
            '이 기술은 판정에 <콤보>가 있는 기술만 회피할 수 있다. '
            '①회피 시, 자신의 패나 리스트에서 판정에 <콤보>가 있는 '
            '기술을 브레이크할 수 있다. 그 경우, 자신은 콤보 타임을 할 수 '
            '있고 이하의 효과를 적용한다. -이번 턴, 자신은 3콤보까지만 이을 수 있다. '
            '-이번 턴, 자신은 1개의 [[token:hidden_bond]]카운터만 얻을 수 있다.',
        )
        source = defense('combo-dodge-source', 'p1')
        source['code'] = 'UNC-AT-036'
        cost = attack('combo-judgment-cost', 'p1', hit='콤보')
        state = base_state([cost], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        release = ruleset(source, cost)
        release['cards']['UNC-AT-036']['effect_definition'] = definition
        engine = AutomaticGameEngine.initialize(state, release, seed='dodge-combo-cost')

        engine._fire('dodge', {
            'controller': 'p1', 'source_card': source,
            'source_card_instance_id': source['instance_id'],
        })
        self.act(engine, 'p1', 'submit_decision', {'selected': ['accept']})
        self.act(engine, 'p1', 'submit_decision', {'selected': [cost['instance_id']]})

        self.assertIsNotNone(engine._find_card(cost['instance_id'], owner='p1', zone='break'))
        self.assertEqual(engine.engine_state['granted_combos'][0]['owner'], 'p1')
        engine.change_counter('p1', 'hidden_bond', 3)
        self.assertEqual(engine.state['players']['p1']['passive_state']['hidden_bond']['count'], 1)
        engine.change_counter('p1', 'hidden_bond', 1)
        self.assertEqual(engine.state['players']['p1']['passive_state']['hidden_bond']['count'], 1)
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

    def test_granted_catch_can_break_both_catch_and_source_cards(self):
        definition = build_effect_draft(
            'ST3-017',
            '①카운터 시 리스트에서 5속도 기술로 캐치할 수 있다. '
            '그 후 캐치한 기술과 이 기술을 브레이크한다.',
        )
        grant = definition['abilities'][0]['effects'][0]
        self.assertEqual((grant['min_speed'], grant['max_speed']), (5, 5))
        self.assertTrue(grant['break_after_use'])
        self.assertTrue(grant['break_source_after_use'])

        source = attack('catch-break-source', 'p1', code='ST3-017')
        catch_card = attack('catch-break-card', 'p1', frame=5, damage=500)
        state = base_state([], [])
        state['phase'] = 'battle'
        state['players']['p1']['zones']['battle'] = [source]
        state['players']['p1']['zones']['list'] = [catch_card]
        engine = AutomaticGameEngine.initialize(
            state, ruleset(source, catch_card), seed='catch-break-both',
        )
        engine.resolver.execute_effects([grant], {
            'controller': 'p1', 'source_card_instance_id': source['instance_id'],
        })
        engine.engine_state['catch'] = engine.engine_state['granted_catches'].pop()
        engine._play_catch('p1', catch_card['instance_id'])
        engine._continue()

        self.assertIsNotNone(engine._find_card(source['instance_id'], owner='p1', zone='break'))
        self.assertIsNotNone(engine._find_card(catch_card['instance_id'], owner='p1', zone='break'))
        self.assertEqual(validate_effect_definition(definition, card_has_text=True), [])

        dfr = build_effect_draft(
            'DFR-AT-047',
            '③사용 후, 이 기술을 브레이크하고 이번 턴 캐치할 수 없다.',
        )
        self.assertEqual(
            [effect['op'] for effect in dfr['abilities'][0]['effects']],
            ['break_card', 'prevent'],
        )

    def test_source_break_catch_exemption_waives_rule_and_all_card_spends(self):
        source = attack('nightmare-jete', 'p1', code='UNC-AT-037')
        catcher = attack(
            'leg-doll', 'p1', code='ST6-008', frame=12, damage=500,
            hit='+0',
        )
        catcher['text'] = '[[state:hidden_bond]] 카운터를 소모한다.'
        source_definition = {
            'schema_version': 1, 'abilities': [],
        }
        catcher_definition = {
            'schema_version': 1,
            'catch_rules': [{
                'optional_fixed_speed': 9,
                'counter_cost': {'counter': 'hidden_bond', 'amount': 1},
            }],
            'abilities': [
                {
                    'id': f'leg-doll-{event}-spend',
                    'kind': 'effect', 'mode': 'mandatory',
                    'trigger': {'event': event}, 'timing': event,
                    'effects': [{
                        'op': 'change_counter',
                        'player': {'controller': True},
                        'counter': 'hidden_bond', 'amount': -1, 'min': 0,
                    }],
                }
                for event in ('use', 'catch', 'hit', 'after_use')
            ],
        }
        grant = {
            'owner': 'p1', 'source': source['instance_id'],
            'allow_zones': ['list'],
            'where': {
                'is_technique': True,
                'text_contains': '[[state:hidden_bond]]',
            },
            'counter_exemption_on_source_break': {
                'counter': 'hidden_bond',
            },
        }

        def make_engine(count, *, source_break_forbidden=False):
            state = base_state([], [])
            state['phase'] = 'battle'
            state['players']['p1']['zones']['battle'] = [copy.deepcopy(source)]
            state['players']['p1']['zones']['list'] = [copy.deepcopy(catcher)]
            state['players']['p1']['passive_state']['hidden_bond'] = {
                'count': count, 'label': '은연',
            }
            release = ruleset(source, catcher)
            release['cards']['UNC-AT-037']['effect_definition'] = copy.deepcopy(
                source_definition,
            )
            if source_break_forbidden:
                release['cards']['UNC-AT-037']['effect_definition'][
                    'break_rules'
                ] = {'forbidden_zones': ['battle']}
            release['cards']['ST6-008']['effect_definition'] = copy.deepcopy(
                catcher_definition,
            )
            engine = AutomaticGameEngine.initialize(
                state, release,
                seed=f'catch-counter-exemption:{count}:{source_break_forbidden}',
            )
            engine.state['phase'] = 'battle'
            engine.engine_state['catch'] = copy.deepcopy(grant)
            engine.engine_state['step'] = 'catch'
            return engine

        exempt = make_engine(0)
        exempt_action = next(
            action for action in exempt.legal_actions('p1')
            if action.get('type') == 'play_catch_card'
            and (action.get('payload') or {}).get('catch_rule_index') == 0
            and (action.get('payload') or {}).get(
                'source_break_counter_exemption'
            ) == 'hidden_bond'
        )
        exempt.submit_action(
            'p1', exempt_action['action_id'], command_id='catch-exempt',
        )
        self.assertEqual(
            exempt.state['players']['p1']['passive_state'][
                'hidden_bond'
            ]['count'],
            0,
        )
        self.assertIsNotNone(exempt._find_card(
            source['instance_id'], owner='p1', zone='break',
        ))
        self.assertEqual(sum(
            event.get('type') == 'catch_counter_cost_waived'
            for event in exempt.events
        ), 1)
        self.assertEqual(sum(
            event.get('type') == 'counter_spend_waived'
            for event in exempt.events
        ), 4)

        paid = make_engine(5)
        paid_action = next(
            action for action in paid.legal_actions('p1')
            if action.get('type') == 'play_catch_card'
            and (action.get('payload') or {}).get('catch_rule_index') == 0
            and 'source_break_counter_exemption'
            not in (action.get('payload') or {})
        )
        paid.submit_action(
            'p1', paid_action['action_id'], command_id='catch-paid',
        )
        self.assertEqual(
            paid.state['players']['p1']['passive_state'][
                'hidden_bond'
            ]['count'],
            0,
        )
        self.assertEqual(sum(
            event.get('type') == 'catch_counter_cost_paid'
            for event in paid.events
        ), 1)
        self.assertFalse(any(
            event.get('type') == 'counter_spend_waived'
            for event in paid.events
        ))

        protected = make_engine(0, source_break_forbidden=True)
        protected_actions = [
            action for action in protected.legal_actions('p1')
            if action.get('type') == 'play_catch_card'
        ]
        self.assertTrue(protected_actions)
        self.assertFalse(any(
            'source_break_counter_exemption' in (action.get('payload') or {})
            for action in protected_actions
        ))

        self.assertEqual(validate_effect_definition({
            'schema_version': 1, 'abilities': [{
                'id': 'grant', 'kind': 'effect', 'mode': 'mandatory',
                'trigger': {'event': 'hit'}, 'timing': 'hit_counter',
                'effects': [{
                    'op': 'grant_catch', 'allow_zones': ['list'],
                    'counter_exemption_on_source_break': {
                        'counter': 'hidden_bond',
                    },
                }],
            }],
        }), [])

    def test_lmi_at_011_reviews_exceed_protocol_all_rules(self):
        text = (
            '이 카드는 다른 기술의 영향을 받지 않는다.\n'
            '①게임 중 처음 [[state:over_limit]]상태가 된 턴의 배틀 페이즈 종료 시, '
            '사이드 덱에서 루멘 존에 배치할 수 있다.\n'
            '이 카드가 루멘 존에 있는 동안 이하의 효과를 적용한다.\n'
            '-[[state:over_limit]]의 해제 조건이 8장에서 11장 이상이 된다.\n'
            '-자신은 루멘 존의 <[[character:nya]]> 기술을 브레이크할 수 없다.\n'
            '-겟 페이즈 시, 루멘 존에서 <[[character:nya]]> 기술 1장을 획득할 수 있다.\n'
            '-콤보 시, 루멘 존의 <[[character:nya]]> 기술을 1장까지 콤보에 사용할 수 있다.\n'
            '그 경우, 사용한 그 기술을 브레이크한다.\n'
            '-[[state:over_limit]] 해제 시, 자신은 500데미지를 받는다.'
        )
        detail_text = (
            '첫 문장은 번호 없는 기능이다. ①의 루멘 존 지속 규칙은 번호 있는 '
            '효과이며, 일반 Get을 모두 처리한 뒤 추가 획득을 처리한다.'
        )
        qna_ids = [88, 414, 417, 494, 530, 597, 603, 649, 663]
        definition = build_effect_draft(
            'LMI-AT-011', text, detail_text=detail_text, qna_ids=qna_ids,
        )
        snapshot = {
            'code': 'LMI-AT-011', 'name': '프로토콜: 익시드',
            'type': '특수', 'text': text, 'detail_text': detail_text,
            'frame': None, 'damage': None, 'pos': None, 'body': '',
            'special': None, 'hit': None, 'guard': None, 'counter': None,
            'character_id': 2,
        }

        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 5)
        by_id = {ability.ability_id: ability for ability in result.abilities}
        self.assertEqual(
            {ability_id: len(ability.scenarios) for ability_id, ability in by_id.items()},
            {
                'lmi-at-011-function': 4,
                'lmi-at-011-n1': 8,
                'lmi-at-011-lumen-rules': 11,
                'lmi-at-011-get': 10,
                'lmi-at-011-over-limit-lost': 6,
            },
        )
        scenarios = {
            item['name']: item
            for ability in result.abilities for item in ability.scenarios
        }
        self.assertEqual(
            scenarios['qna-649-opponent-move-effect-is-ignored-in-lumen']['zone'],
            'lumen',
        )
        self.assertEqual(
            scenarios['core-movement-is-not-another-technique-effect']['zone'],
            'break',
        )
        self.assertEqual(
            scenarios['owner-p1-first-over-limit-accepts-at-battle-end']['zone'],
            'lumen',
        )
        self.assertEqual(
            scenarios['owner-p2-first-over-limit-may-decline']['zone'],
            'side',
        )
        self.assertEqual(
            scenarios['lumen-threshold-is-eleven']['state_rule_value'], 11,
        )
        self.assertEqual(
            scenarios['qna-530-owner-effect-cannot-break-own-nya']['target_zone'],
            'lumen',
        )
        self.assertEqual(
            scenarios['opponent-effect-may-break-nonimmune-nya']['target_zone'],
            'break',
        )
        combo = scenarios['lumen-nya-combo-is-used-once-and-breaks']
        self.assertTrue(combo['nya_legal'])
        self.assertFalse(combo['neutral_legal'])
        self.assertFalse(combo['two_lumen_pair_legal'])
        self.assertEqual(combo['used_zone'], 'break')
        self.assertFalse(
            scenarios['qna-88-cannon-plus-five-other-techniques-is-illegal']
            ['cannon_legal'],
        )
        self.assertTrue(
            scenarios['qna-88-cannon-plus-six-other-techniques-is-legal']
            ['cannon_legal'],
        )
        self.assertEqual(
            scenarios['qna-417-603-skipped-get-has-no-protocol-trigger']
            ['decision_kinds'],
            [],
        )
        self.assertEqual(
            scenarios['owner-p2-selects-second-of-multiple-nya']['selected_zone'],
            'hand',
        )
        self.assertTrue(
            scenarios['move-immune-candidate-is-not-offered']
            ['protected_not_offered'],
        )
        self.assertEqual(
            scenarios['movement-protection-added-after-choice-is-rechecked']
            ['selected_zone'],
            'lumen',
        )
        self.assertEqual(
            scenarios['owner-p1-over-limit-loss-takes-five-hundred']['damage'],
            500,
        )
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

        mutations = []
        wrong_immunity = copy.deepcopy(definition)
        wrong_immunity['effect_immunity']['active_zones'] = ['lumen']
        mutations.append(wrong_immunity)
        function_rules = copy.deepcopy(definition)
        function_rules['abilities'][2]['kind'] = 'function'
        mutations.append(function_rules)
        unrestricted_break = copy.deepcopy(definition)
        unrestricted_break['abilities'][2]['effects'][1].pop('controller_only')
