    def test_lmi_at_008_reviews_chained_costs_get_locks_and_list_combo(self):
        text = (
            '①[[state:paladin]]: 판정 전, 패에서 '
            '[[state:guardian]]효과가 있는 기술을 1장 버린다면 '
            '이 기술의 데미지+200\n '
            '추가로 [[state:assassin]]효과가 있는 기술을 1장 버릴 경우, '
            '상대는 이 기술을 회피할 수 없고 자신은 2FP를 얻는다.\n '
            '이 효과로 버린 기술은 이번 턴, 겟 페이즈에서 가져올 수 없다.\n '
            '②[[state:paladin]]: 콤보 시, 리스트에서 '
            '[[state:saintess]]효과가 있는 기술 1장을 사용할 수 있다.'
        )
        definition = build_effect_draft(
            'LMI-AT-008', text, qna_ids=[242, 442, 536],
        )
        snapshot = {
            'code': 'LMI-AT-008', 'name': '약속된 승리를 위하여',
            'type': '공격', 'text': text, 'detail_text': '',
            'frame': 12, 'damage': 500, 'pos': '상단', 'body': '',
            'special': None, 'hit': '콤보', 'guard': '-6',
            'counter': '콤보', 'g_top': None, 'g_mid': None,
            'g_bot': None, 'character_id': 9,
        }

        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 2)
        by_id = {ability.ability_id: ability for ability in result.abilities}
        self.assertEqual(
            {key: len(value.scenarios) for key, value in by_id.items()},
            {'lmi-at-008-n1': 15, 'lmi-at-008-n2': 10},
        )
        scenarios = {
            scenario['name']: scenario
            for ability in result.abilities for scenario in ability.scenarios
        }
        paid = scenarios['owner-p1-pays-both-real-card-costs']
        self.assertEqual(paid['guardian_options'], [
            'p1-promise-guardian-1', 'p1-promise-guardian-2',
        ])
        self.assertEqual(paid['assassin_options'], [
            'p1-promise-assassin-1', 'p1-promise-assassin-2',
        ])
        self.assertEqual(paid['guardian_zone'], 'list')
        self.assertEqual(paid['assassin_zone'], 'list')
        self.assertEqual(paid['damage'], 700)
        self.assertEqual(paid['fp'], 2)
        self.assertEqual(paid['effective_speed'], 10)
        self.assertTrue(paid['dodge_blocked'])
        self.assertTrue(paid['guardian_get_blocked'])
        self.assertTrue(paid['assassin_get_blocked'])
        qna_442 = scenarios['qna-442-assassin-alone-cannot-pay']
        self.assertIsNone(qna_442['first_kind'])
        self.assertEqual(qna_442['damage'], 500)
        self.assertEqual(qna_442['fp'], 0)
        late_guardian = scenarios[
            'late-guardian-protection-blocks-whole-chain'
        ]
        self.assertEqual(late_guardian['guardian_zone'], 'hand')
        self.assertIsNone(late_guardian['assassin_choice_kind'])
        self.assertEqual(late_guardian['damage'], 500)
        late_assassin = scenarios[
            'late-assassin-protection-denies-followups'
        ]
        self.assertEqual(late_assassin['guardian_zone'], 'list')
        self.assertEqual(late_assassin['assassin_zone'], 'hand')
        self.assertEqual(late_assassin['damage'], 700)
        self.assertEqual(late_assassin['fp'], 0)
        expiry = scenarios['turn-end-releases-both-qna-get-locks']
        self.assertTrue(expiry['guardian_get_blocked'])
        self.assertTrue(expiry['assassin_get_blocked'])
        self.assertFalse(expiry['after_turn_guardian_blocked'])
        self.assertFalse(expiry['after_turn_assassin_blocked'])
        qna_536 = scenarios['qna-536-mid-combo-still-requires-speed-13']
        self.assertTrue(qna_536['source_action_found'])
        self.assertTrue(qna_536['fast_legal'])
        self.assertFalse(qna_536['slow_legal'])
        one_card = scenarios['permission-applies-to-only-immediate-next-card']
        self.assertTrue(one_card['played_fast'])
        self.assertFalse(one_card['second_legal_after_fast'])
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

        def ability(document, ability_id):
            return next(
                item for item in document['abilities']
                if item['id'] == ability_id
            )

        def guardian_request(document):
            return ability(document, 'lmi-at-008-n1')['effects'][0]

        def guardian_conditional(document):
            return guardian_request(document)['then'][1]

        def guardian_success(document):
            return guardian_conditional(document)['then']

