    def test_lmi_at_005_reviews_use_gate_combo_cost_and_conditional_break(self):
        text = (
            '상대는 이 기술을 회피할 수 없다.\n '
            '이 기술은 [[state:assassin]]을 축복하지 않으면 사용할 수 없다.\n '
            '①[[state:assassin]]: 상대 체력이 1500 이하일 경우 이 기술의 '
            '데미지+300\n '
            '②[[state:assassin]]: 콤보 시, 패 3장을 버린다면 원하는 속도로 '
            '사용할 수 있다.\n '
            '③콤보 시, 이 기술은 데미지 보정을 적용하지 않을 수 있다.\n '
            '그 경우, 처리한 이 기술을 브레이크한다.'
        )
        definition = build_effect_draft(
            'LMI-AT-005', text, qna_ids=[588],
        )
        snapshot = {
            'code': 'LMI-AT-005', 'name': '이단처형', 'type': '공격',
            'text': text, 'detail_text': '', 'frame': 9, 'damage': 400,
            'pos': '상단', 'body': '손', 'special': None, 'hit': '4',
            'guard': '-6', 'counter': '5', 'g_top': None, 'g_mid': None,
            'g_bot': None, 'character_id': 9,
        }

        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 4)
        by_id = {ability.ability_id: ability for ability in result.abilities}
        self.assertEqual(
            {key: len(value.scenarios) for key, value in by_id.items()},
            {
                'lmi-at-005-function': 5,
                'lmi-at-005-n1': 6,
                'lmi-at-005-n2': 8,
                'lmi-at-005-n3': 5,
            },
        )
        scenarios = {
            scenario['name']: scenario
            for ability in result.abilities for scenario in ability.scenarios
        }
        no_state = scenarios[
            'qna-588-no-assassin-denies-use-but-function-remains'
        ]
        self.assertFalse(no_state['use_allowed'])
        self.assertTrue(no_state['dodge_blocked'])
        boundary = scenarios['owner-p1-assassin-at-1500-gains-300-damage']
        self.assertEqual(boundary['damage'], 700)
        paid = scenarios['owner-p1-pays-three-for-speed-five']
