    def test_lmi_at_023_reviews_steel_swing_borrow_and_acquisition(self):
        text = (
            '①[[state:advance_notice]]: 콤보 시, 상대 리스트에서 <10속도 이하>'
            '기술 1장을 효과를 무효로 하고 속도에 상관없이 이 기술 다음에 '
            '이을 수 있다.(콤보 타임 종료 시, 해당 기술은 상대 리스트로 보낸다.)\n'
            '②콤보 시, 패가 2장 이하일 경우, 이 기술 외 콤보에 사용한 자신의 '
            '<[[character:kiss]]> 기술 1장을 획득한다.'
        )
        detail_text = (
            '①은 예고 상태에서 선택한다. 상대 리스트의 인쇄 10속도 이하 공격 '
            '기술을 바로 다음 콤보로 사용하며 번호 효과만 무효로 하고 기능은 '
            '유지한다. 발동했다면 반드시 그 기술을 사용하고 콤보 종료 시 원래 '
            '상대 리스트로 돌려보낸다. ②는 패가 2장 이하라면 현재 카드보다 '
            '먼저 사용 후 처리를 마친 자신의 키스 기술 하나를 선택해 배틀 존에서 '
            '패로 직접 옮긴다. 함께 제시했지만 아직 처리하지 않은 뒤쪽 기술은 '
            '선택할 수 없다.'
        )
        definition = build_effect_draft(
            'LMI-AT-023', text, detail_text=detail_text,
            qna_ids=[20, 84, 420, 421, 423, 643],
        )
        snapshot = {
            'code': 'LMI-AT-023', 'name': '스틸 스윙', 'type': '공격',
            'text': text, 'detail_text': detail_text,
            'frame': 12, 'damage': 400, 'pos': '상단', 'body': '',
            'special': None, 'hit': '4', 'guard': '-6', 'counter': '6',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 5,
        }

        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 2)
        by_id = {ability.ability_id: ability for ability in result.abilities}
        self.assertEqual(
            {key: len(value.scenarios) for key, value in by_id.items()},
            {'lmi-at-023-n1': 12, 'lmi-at-023-n2': 10},
        )
        scenarios = {
            scenario['name']: scenario
            for ability in result.abilities for scenario in ability.scenarios
        }
        forced = scenarios[
            'owner-p1-source-only-accept-reopens-and-forces-borrow'
        ]
        self.assertEqual(forced['followup_ids'], [['p1-steel-target']])
        self.assertFalse(forced['end_combo_offered'])
        self.assertEqual(forced['borrow_damage'], 400)
        self.assertEqual(forced['borrowed_effect_resolved'], 0)
        self.assertTrue(forced['returned'])
        self.assertTrue(forced['borrow_flags_cleared'])
        fourth = scenarios[
            'three-combo-can-extend-one-borrowed-card-to-four-combo'
        ]
        self.assertIn(
            ['steel-prior-two', 'p1-steel-swing', 'steel-plain'],
            fourth['borrowed_followups'],
        )
        resumed_speed = scenarios[
            'after-borrowed-card-normal-ascending-speed-resumes'
        ]
        self.assertTrue(any(
            sequence[-2:] == ['steel-speed-five', 'steel-speed-six-next']
            for sequence in resumed_speed['sequences']
        ))
        self.assertFalse(any(
            sequence[-2:] == ['steel-speed-five', 'steel-speed-five-next']
            for sequence in resumed_speed['sequences']
        ))
        acquired = scenarios['owner-p1-chooses-completed-one-combo-card']
        self.assertEqual(acquired['option_ids'], ['p1-steel-opener'])
        self.assertTrue(acquired['opener_in_hand'])
        future = scenarios[
            'joint-three-combo-card-is-not-yet-an-acquisition-candidate'
        ]
        self.assertFalse(future['future_offered'])
        late_block = scenarios[
            'late-hand-move-block-rechecks-after-selection'
        ]
        self.assertFalse(late_block['opener_in_hand'])
        self.assertTrue(late_block['opener_in_battle'])
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

        numbered_combo = build_effect_draft(
            'REVIEW-NUMBERED-COMBO',
            '①콤보 시, 3콤보 후에만 사용할 수 있다.',
        )
        self.assertTrue(
            numbered_combo['combo_rules'][0]['numbered_effect']
        )

        def ability(document, ability_id):
            return next(
                item for item in document['abilities']
                if item['id'] == ability_id
            )

        def borrow_rule(document):
            return ability(document, 'lmi-at-023-n1')['effects'][0]

        def acquire_request(document):
            return ability(document, 'lmi-at-023-n2')['effects'][0]

        mutations = []
        no_required_followup = copy.deepcopy(definition)
        borrow_rule(no_required_followup)['requires_followup'] = False
        mutations.append(no_required_followup)
        effects_not_negated = copy.deepcopy(definition)
        borrow_rule(effects_not_negated)['negate_effects'] = False
        mutations.append(effects_not_negated)
        wrong_speed = copy.deepcopy(definition)
        borrow_rule(wrong_speed)['where']['frame_lte'] = 11
        mutations.append(wrong_speed)
        own_list = copy.deepcopy(definition)
        borrow_rule(own_list).pop('borrow_from')
        mutations.append(own_list)
        missing_return = copy.deepcopy(definition)
        borrow_rule(missing_return).pop('return_to_owner_zone_on_combo_end')
        mutations.append(missing_return)
        mandatory_first = copy.deepcopy(definition)
        ability(mandatory_first, 'lmi-at-023-n1')['mode'] = 'mandatory'
        mutations.append(mandatory_first)
        wrong_history = copy.deepcopy(definition)
        acquire_request(wrong_history)['selector']['history'] = 'combo_used'
        mutations.append(wrong_history)
        missing_operation = copy.deepcopy(definition)
        acquire_request(missing_operation)['selector'].pop('as_operation')
        mutations.append(missing_operation)
        no_proposal_exclusion = copy.deepcopy(definition)
        ability(no_proposal_exclusion, 'lmi-at-023-n2')['condition'][
            'exclude_combo_proposed'
        ] = False
        mutations.append(no_proposal_exclusion)
        optional_acquisition = copy.deepcopy(definition)
        ability(optional_acquisition, 'lmi-at-023-n2')['mode'] = 'optional'
        mutations.append(optional_acquisition)
        missing_qna = copy.deepcopy(definition)
        missing_qna['source_refs']['qna_ids'].remove(423)
        mutations.append(missing_qna)
        missing_detail = copy.deepcopy(definition)
        missing_detail['source_refs']['detail_text'] = False
        mutations.append(missing_detail)
        for mutated in mutations:
            self.assertFalse(review_automatic_definition(
                mutated, card_has_text=True, card_snapshot=snapshot,
            ).passed)

        malformed_followup = copy.deepcopy(definition)
        borrow_rule(malformed_followup)['requires_followup'] = 'yes'
        self.assertTrue(validate_effect_definition(
            malformed_followup, card_has_text=True,
        ))

        for key, value in (
            ('name', '다른 카드'), ('type', '수비'), ('frame', 11),
            ('damage', 500), ('pos', '중단'), ('body', '손'),
            ('special', ''), ('hit', '5'), ('guard', '-5'),
            ('counter', '7'), ('character_id', 4),
        ):
            wrong_snapshot = copy.deepcopy(snapshot)
            wrong_snapshot[key] = value
            self.assertFalse(review_automatic_definition(
                definition, card_has_text=True, card_snapshot=wrong_snapshot,
            ).passed)

    def test_lmi_at_024_reviews_zephyr_cost_live_limit_and_combo_end(self):
        text = (
            '①<8속도 [[character:kiss]]>기술의 히트 시, 패 1장을 버리고 '
            '히트 판정을 <콤보>로 변경한다.\n '
            '그 후, 콤보 타임 종료 후 이 [[token:calling_card]]을 사이드 덱으로 '
            '보낸다.\n '
            '②리커버리 페이즈 시, 자신의 패가 최대 제한과 같을 경우 이 '
            '[[token:calling_card]]을 사이드 덱으로 보낸다.\n '
            '③상대의 콤보 타임 종료 후, 이 [[token:calling_card]]을 브레이크한다.'
        )
