    def test_crs_at_054_reviews_side_break_and_required_slow_third_combo(self):
        text = (
            '이 기술은 3장까지 덱에 넣을 수 있다.\n'
            '①콤보 시, 사이드 덱에서 이 기술을 브레이크할 수 있다.'
            '(사이드 덱에서 브레이크할 경우, 사이드 덱에서 리스트로 '
            '카드를 놓지 않는다.)\n'
            '그 경우, 3콤보 기술을 속도를 무시하고 패에서 1장 이을 수 있다.\n'
            '그 기술의 사용 후, 콤보 타임을 종료한다.'
        )
        snapshot = {
            'code': 'CRS-AT-054', 'name': '드리프트 컨버전',
            'type': '특수', 'text': text, 'detail_text': '',
            'frame': None, 'damage': None, 'pos': None, 'body': None,
            'special': None, 'hit': None, 'guard': None, 'counter': None,
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 1, 'ultimate': False,
        }
        definition = build_effect_draft(
            'CRS-AT-054', text, qna_ids=[594],
        )
        result = review_automatic_definition(
            definition, card_has_text=True, card_snapshot=snapshot,
        )

        self.assertTrue(result.passed, result.as_dict())
        self.assertEqual(len(result.abilities), 2)
        self.assertEqual(result.as_dict()['scenario_count'], 13)
        by_id = {ability.ability_id: ability for ability in result.abilities}
        conversion = {
            item['name']: item
            for item in by_id['crs-at-054-n1'].scenarios
        }
        full_flow = conversion[
            'qna594-full-flow-uses-slow-third-and-ends-combo'
        ]
        self.assertFalse(full_flow['slow_before'])
        self.assertTrue(full_flow['slow_after'])
