        foot = counter['foot-attack-gains-default-100']
        self.assertEqual(foot['after_damage'] - foot['before_damage'], 100)
        defense = counter['hand-defense-gains-default-100']
        self.assertEqual(
            defense['after_damage'] - defense['before_damage'], 100,
        )

        wrong_replacement = copy.deepcopy(definition)
        wrong_replacement['abilities'][2]['effects'][0]['then'][0][
            'amount'
        ] = 300
        self.assertFalse(review_automatic_definition(
            wrong_replacement, card_has_text=True, card_snapshot=snapshot,
        ).passed)
        wrong_speed = copy.deepcopy(definition)
        wrong_speed['combo_rules'][0]['speed_options'] = [6]
        self.assertFalse(review_automatic_definition(
            wrong_speed, card_has_text=True, card_snapshot=snapshot,
        ).passed)
        self.assertEqual(
            validate_effect_definition(definition, card_has_text=True), [],
        )

