class RulesetPublicationTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.character = Character.objects.create(
            name='Publication Character',
            localization_key='publication_character',
            description='',
            group='Test',
            datas={'hand': {'5000': 5}},
            img='https://example.invalid/publication.png',
        )
        no_effect = {
            'schema_version': 1,
            'reviewed': True,
            'no_effect': True,
            'source_refs': {
                'rulebook_pages': [],
                'qna_ids': [],
            },
            'abilities': [],
        }
        Card.objects.bulk_create([
            Card(
                name=f'Publication Card {index}',
                code=f'PUB-{index:03d}',
                character=cls.character,
                type='공격',
                frame=5,
                damage=300,
                pos='상단',
                text='',
                effect_definition=no_effect,
            )
            for index in range(EXPECTED_CARD_COUNT)
        ], batch_size=200)

    def test_published_release_is_immutable_activates_and_pins_catalog(self):
        first, report = publish_ruleset_release('publication-v1')

        self.assertTrue(report.is_valid, report.errors)
        self.assertEqual(report.card_count, EXPECTED_CARD_COUNT)
        self.assertEqual(report.reviewed_card_count, EXPECTED_CARD_COUNT)
        self.assertEqual(report.no_effect_card_count, EXPECTED_CARD_COUNT)
        self.assertEqual(
            len(first.snapshot['cards']), EXPECTED_CARD_COUNT,
        )
        self.assertEqual(first.content_hash, _json_hash(first.snapshot))
        self.assertEqual(automatic_mode_release(), first)
        start_page = self.client.get(reverse('battlelog:simulatorStart'))
        self.assertContains(start_page, 'value="automatic"')
        self.assertContains(start_page, 'value="ai"')

        original_name = first.snapshot['cards']['PUB-000']['name']
        Card.objects.filter(code='PUB-000').update(name='Changed after publication')
        first.refresh_from_db()
        self.assertEqual(first.snapshot['cards']['PUB-000']['name'], original_name)

        first.snapshot = {'tampered': True}
        with self.assertRaises(ValidationError):
            first.save()

        first.refresh_from_db()
        second, second_report = publish_ruleset_release('publication-v2')
        first.refresh_from_db()

        self.assertTrue(second_report.is_valid, second_report.errors)
        self.assertNotEqual(second.id, first.id)
        self.assertFalse(first.is_active)
        self.assertTrue(second.is_active)
        self.assertEqual(
            second.snapshot['cards']['PUB-000']['name'],
            'Changed after publication',
        )
        self.assertEqual(automatic_mode_release(), second)

    def test_unreviewed_definition_blocks_publication_without_partial_release(self):
        Card.objects.filter(code='PUB-000').update(effect_definition={
            'schema_version': 1,
            'reviewed': False,
            'abilities': [],
        })

        with self.assertRaises(RulesetPublicationError) as raised:
            publish_ruleset_release('invalid-publication')

        self.assertIn(
            'unreviewed',
            {error.get('code') for error in raised.exception.report.errors},
        )
        self.assertFalse(RulesetRelease.objects.exists())
        self.assertIsNone(automatic_mode_release())
        start_page = self.client.get(reverse('battlelog:simulatorStart'))
        self.assertContains(start_page, 'value="manual"')
        self.assertNotContains(start_page, 'value="automatic"')
        self.assertNotContains(start_page, 'value="ai"')

    def test_missing_scenario_evidence_blocks_publication(self):
        Card.objects.filter(code='PUB-000').update(effect_definition={
            'schema_version': 1, 'reviewed': True,
            'source_refs': {'rulebook_pages': [36], 'qna_ids': []},
            'abilities': [{
                'id': 'publication-use', 'kind': 'effect',
                'mode': 'mandatory', 'timing': 'use',
                'trigger': {'event': 'use'},
                'effects': [{'op': 'change_fp', 'amount': 1}],
            }],
        })

        with self.assertRaises(RulesetPublicationError) as raised:
            publish_ruleset_release('missing-evidence-publication')

        self.assertIn(
            'missing_review_evidence',
            {error.get('code') for error in raised.exception.report.errors},
        )
        self.assertFalse(RulesetRelease.objects.exists())
        self.assertIsNone(automatic_mode_release())

    def test_source_change_invalidates_a_previously_reviewed_definition(self):
        card = Card.objects.get(code='PUB-000')
        card.text = '효과 없음으로 재정한 카드 문구'
        card.effect_definition = {
            'schema_version': 1,
            'reviewed': True,
            'no_effect': True,
            'source_refs': {
                'rulebook_pages': [],
                'qna_ids': [],
                'card_text': True,
            },
            'abilities': [],
        }
        card.save()
        card.effect_definition = {
            **card.effect_definition,
            'source_digest': effect_source_digest(card, []),
        }
        card.save(update_fields=['effect_definition'])

        current = validate_catalog([card], require_coverage=True)
        current_codes = {error.get('code') for error in current.errors}
        self.assertNotIn('missing_source_digest', current_codes)
        self.assertNotIn('stale_source_digest', current_codes)

        card.detail_text = '새로 추가된 에라타'
        card.save(update_fields=['detail_text'])
        stale = validate_catalog([card], require_coverage=True)

        stale_codes = {error.get('code') for error in stale.errors}
        self.assertIn('stale_source_digest', stale_codes)
        self.assertIn('missing_detail_text_reference', stale_codes)

    def test_general_qna_is_a_valid_unlinked_source_and_part_of_digest(self):
        card = Card.objects.get(code='PUB-000')
        qna = QNA.objects.create(
            title='General ruling', question='General question',
            answer='General answer',
        )
        card.text = 'General Q&A based ruling'
        card.effect_definition = {
            'schema_version': 1,
            'reviewed': True,
            'no_effect': True,
            'draft': False,
            'source_refs': {
                'rulebook_pages': [],
                'qna_ids': [],
                'general_qna_ids': [qna.pk],
                'card_text': True,
            },
            'abilities': [],
        }
        card.save()
        card.effect_definition = {
            **card.effect_definition,
            'source_digest': effect_source_digest(card),
        }
        card.save(update_fields=['effect_definition'])

        current = validate_catalog([card], require_coverage=True)
        current_codes = {error.get('code') for error in current.errors}
        self.assertNotIn('unrelated_qna', current_codes)
        self.assertNotIn('missing_qna', current_codes)
        self.assertNotIn('stale_source_digest', current_codes)
        self.assertFalse(QNARelation.objects.filter(card=card, qna=qna).exists())

        QNARelation.objects.create(card=card, qna=qna)
        linked = validate_catalog([card], require_coverage=True)
        self.assertNotIn(
            'missing_linked_qna_reference',
            {error.get('code') for error in linked.errors},
        )

        qna.answer = 'Changed general answer'
        qna.save()
        stale = validate_catalog([card], require_coverage=True)
        self.assertIn(
            'stale_source_digest',
            {error.get('code') for error in stale.errors},
        )


class AutomaticPersistenceTests(TestCase):
    def setUp(self):
        self.p1_card = attack('p1-card', 'p1', code='P1')
        self.p2_card = attack('p2-card', 'p2', code='P2')
        self.snapshot = ruleset(self.p1_card, self.p2_card)
        self.release = RulesetRelease.objects.create(
            version='test-ai-v1',
            snapshot=self.snapshot,
            content_hash='a' * 64,
            source_manifest={},
        )

    def make_session(self, *, p1_controller='human', p2_controller='ai'):
        policy = active_ai_policy()
        document = initialize_automatic_document(
            base_state([self.p1_card], [self.p2_card]),
            self.release,
            seed='db-ai-test',
        )
        document['ai_policy'] = ai_policy_payload(policy)
        return LumenSimulatorSession.objects.create(
            view_token='view-ai-test',
            player1_token='p1-ai-token',
            player2_token='p2-ai-token',
            mode=LumenSimulatorSession.MODE_AUTOMATIC,
            player1_controller=p1_controller,
            player2_controller=p2_controller,
            ruleset_release=self.release,
            ai_policy=policy,
            document=document,
        )

    def test_ai_session_advances_only_ai_legal_actions(self):
        session = self.make_session()

        advanced = advance_ai_session(session)

        self.assertGreater(advanced.version, session.version)
        self.assertIn('p2', advanced.document['state']['engine']['phase_passes'])
        self.assertNotIn('p1', advanced.document['state']['engine']['phase_passes'])

    def test_legacy_session_is_compacted_and_enters_ready_on_reconnect(self):
        session = self.make_session(p2_controller='human')
        document = copy.deepcopy(session.document)
        document['command_history'] = [{
            'command_id': 'legacy-rewind',
            'state_before': copy.deepcopy(document['state']),
            'event_count_before': 0,
        }]
        session.document = document
        session.save(update_fields=['document'])

        upgraded = reconcile_automatic_session(session)

        self.assertEqual(upgraded.document['command_history'], [])
        self.assertEqual(upgraded.document['state']['phase'], 'ready')
        settings = upgraded.document['state']['engine']['settings']
        self.assertTrue(settings['auto_advance_empty_phases'])
        self.assertFalse(settings['rewind_enabled'])

    def test_ai_session_without_pinned_policy_reports_and_falls_back(self):
        session = self.make_session()
        document = session.document
        document.pop('ai_policy', None)
        session.document = document
        session.ai_policy = None
        session.save(update_fields=['document', 'ai_policy'])

        recovered = advance_ai_session(session)

        self.assertEqual(recovered.mode, LumenSimulatorSession.MODE_MANUAL)
        self.assertTrue(recovered.automation_failure.get('report_id'))
        self.assertIn('검증된 정책', recovered.issue_reports.get().summary)

    def test_external_command_cannot_control_ai_seat(self):
        session = self.make_session(p1_controller='ai', p2_controller='human')
        engine = AutomaticGameEngine(
            session.document['state'], self.snapshot, version=session.version, events=session.document['events'],
        )
        action = next(item for item in engine.legal_actions('p1') if item['type'] == 'pass_phase')

        with self.assertRaises(PermissionDenied):
            perform_automatic_command(session, {
                'command_id': 'human-controls-ai',
                'expected_version': session.version,
                'action_id': action['action_id'],
                'seat': 'p1',
                'seat_token': session.player1_token,
            })

    def test_automatic_command_is_idempotent_and_accepts_still_legal_stale_action(self):
        session = self.make_session(p2_controller='human')
        engine = AutomaticGameEngine(
            session.document['state'], self.snapshot,
            version=session.version, events=session.document['events'],
        )
        action = next(item for item in engine.legal_actions('p1') if item['type'] == 'pass_phase')
        body = {
            'command_id': 'idempotent-pass',
            'expected_version': session.version,
            'action_id': action['action_id'],
            'seat': 'p1',
            'seat_token': session.player1_token,
        }

        first = perform_automatic_command(session, body)
        replayed = perform_automatic_command(first, body)

        self.assertEqual(replayed.version, first.version)
        self.assertEqual(len(replayed.document['command_log']), 1)

        current = AutomaticGameEngine(
            replayed.document['state'], self.snapshot,
            version=replayed.version, events=replayed.document['events'],
        )
        p2_action = next(item for item in current.legal_actions('p2') if item['type'] == 'pass_phase')
        advanced = perform_automatic_command(replayed, {
            'command_id': 'semantic-stale-pass',
            'expected_version': session.version,
            'action_id': p2_action['action_id'],
            'seat': 'p2',
            'seat_token': session.player2_token,
        })
        self.assertEqual(advanced.document['state']['phase'], 'ready')

        with self.assertRaises(StaleState):
            perform_automatic_command(advanced, {
                'command_id': 'obsolete-stale-pass',
                'expected_version': session.version,
                'action_id': action['action_id'],
                'seat': 'p1',
                'seat_token': session.player1_token,
            })

    def test_accepted_rewind_restores_previous_user_command_and_keeps_audit(self):
        session = self.make_session(p2_controller='human')
        document = copy.deepcopy(session.document)
        document['state']['engine']['settings']['rewind_enabled'] = True
        session.document = document
        session.save(update_fields=['document'])
        engine = AutomaticGameEngine(
            session.document['state'], self.snapshot,
            version=session.version, events=session.document['events'],
        )
        pass_action = next(item for item in engine.legal_actions('p1') if item['type'] == 'pass_phase')
        session = perform_automatic_command(session, {
            'command_id': 'rewind-target', 'expected_version': session.version,
            'action_id': pass_action['action_id'], 'seat': 'p1',
            'seat_token': session.player1_token,
        })
        engine = AutomaticGameEngine(
            session.document['state'], self.snapshot,
            version=session.version, events=session.document['events'],
        )
        request = next(item for item in engine.legal_actions('p1') if item['type'] == 'request_rewind')
        session = perform_automatic_command(session, {
            'command_id': 'rewind-request', 'expected_version': session.version,
            'action_id': request['action_id'], 'seat': 'p1',
            'seat_token': session.player1_token,
        })
        engine = AutomaticGameEngine(
            session.document['state'], self.snapshot,
            version=session.version, events=session.document['events'],
        )
        accept = next(
            item for item in engine.legal_actions('p2')
            if item['type'] == 'answer_rewind' and item['payload']['accept']
        )

        restored = perform_automatic_command(session, {
            'command_id': 'rewind-accept', 'expected_version': session.version,
            'action_id': accept['action_id'], 'seat': 'p2',
            'seat_token': session.player2_token,
        })

        self.assertNotIn('p1', restored.document['state']['engine']['phase_passes'])
        self.assertEqual(restored.document['audit_log'][-1]['type'], 'rewind_applied')
        target_log = next(
            item for item in restored.document['command_log']
            if item['command_id'] == 'rewind-target'
        )
        self.assertEqual(target_log['rewound_by'], 'rewind-accept')

    def test_ai_command_limit_returns_reported_manual_fallback(self):
        session = self.make_session()

        recovered = advance_ai_session(session, max_commands=0)

        self.assertEqual(recovered.mode, LumenSimulatorSession.MODE_MANUAL)
        self.assertTrue(recovered.automation_failure.get('report_id'))
        self.assertEqual(recovered.issue_reports.get().origin, AutomaticIssueReport.ORIGIN_ENGINE)

    def test_ai_policy_failure_returns_reported_manual_fallback(self):
        session = self.make_session()

        with patch(
            'battlelog.automatic_services.choose_action',
            side_effect=RuntimeError('policy exploded'),
        ):
            recovered = advance_ai_session(session)

        self.assertEqual(recovered.mode, LumenSimulatorSession.MODE_MANUAL)
        self.assertEqual(
            recovered.automation_failure.get('error_type'),
            'RuntimeError',
        )
        report = recovered.issue_reports.get()
        self.assertEqual(report.origin, AutomaticIssueReport.ORIGIN_ENGINE)
        self.assertIn('policy exploded', report.summary)

    def test_engine_failure_creates_report_and_user_can_append_details(self):
        session = self.make_session()

        failed = _fallback_to_manual(session.id, RuntimeError('resolver exploded'), 'bad-command')
        report = AutomaticIssueReport.objects.get(public_id=failed.automation_failure['report_id'])
        add_issue_report(failed, 'p1', '배틀 판정 직후 화면이 멈췄습니다.')

        self.assertEqual(failed.mode, LumenSimulatorSession.MODE_MANUAL)
        self.assertEqual(report.origin, AutomaticIssueReport.ORIGIN_ENGINE)
        self.assertEqual(report.comments.get().role, 'p1')

    def test_published_ai_policy_content_is_immutable(self):
        policy = SimulatorAIPolicy.objects.get(is_active=True)
        policy.weights = {'changed': True}

        with self.assertRaises(ValidationError):
            policy.save()


class AutomaticWebSocketTests(TransactionTestCase):
    def setUp(self):
        p1_card = attack('ws-p1-card', 'p1', code='WS-P1')
        p2_card = attack('ws-p2-card', 'p2', code='WS-P2')
        snapshot = ruleset(p1_card, p2_card)
        release = RulesetRelease.objects.create(
            version='websocket-rules-v1',
            snapshot=snapshot,
            content_hash='b' * 64,
            source_manifest={},
        )
        document = initialize_automatic_document(
            base_state([p1_card], [p2_card]),
            release,
            seed='websocket-command-test',
        )
        self.session = LumenSimulatorSession.objects.create(
            view_token='websocket-view',
            player1_token='websocket-p1',
            player2_token='websocket-p2',
            mode=LumenSimulatorSession.MODE_AUTOMATIC,
            ruleset_release=release,
            document=document,
        )

    @staticmethod
    async def _receive_type(communicator, message_type, attempts=8):
        for _index in range(attempts):
            message = await communicator.receive_json_from(timeout=2)
            if message.get('type') == message_type:
                return message
        raise AssertionError(f'{message_type} WebSocket 메시지를 받지 못했습니다.')

    def test_websocket_command_acknowledges_and_persists_automatic_action(self):
        async_to_sync(self._exercise_websocket_command)()

        self.session.refresh_from_db()
        self.assertEqual(self.session.version, 3)
        self.assertIn('p1', self.session.document['state']['engine']['ready_cards'])

    async def _exercise_websocket_command(self):
        communicator = WebsocketCommunicator(
            URLRouter(websocket_urlpatterns),
            '/ws/battlelog/simulator/websocket-view/'
            '?seat=p1&seat_token=websocket-p1',
        )
        connected, _subprotocol = await communicator.connect()
        self.assertTrue(connected)
        try:
            initial = await self._receive_type(communicator, 'state')
            envelope = initial['state']
            action = next(
                item for item in envelope['legal_actions']
                if item['type'] == 'ready_card'
            )
            await communicator.send_json_to({
                'type': 'command',
                'request_id': 'ws-command-request',
                'payload': {
                    'command_id': 'ws-command',
                    'expected_version': envelope['version'],
                    'action_id': action['action_id'],
                    'selections': {},
                },
            })

            acknowledged = await self._receive_type(communicator, 'command_ack')
            self.assertTrue(acknowledged['ok'])
            self.assertEqual(acknowledged['request_id'], 'ws-command-request')

            await communicator.send_json_to({
                'type': 'command',
                'request_id': 'ws-stale-request',
                'payload': {
                    'command_id': 'ws-stale-command',
                    'expected_version': envelope['version'],
                    'action_id': action['action_id'],
                    'selections': {},
                },
            })
            rejected = await self._receive_type(communicator, 'error')
            self.assertEqual(rejected['request_id'], 'ws-stale-request')
            self.assertEqual(rejected['code'], 'stale_state')
            self.assertGreater(rejected['state']['version'], envelope['version'])
        finally:
            await communicator.disconnect()


class EffectDraftCommandTests(TestCase):
    def setUp(self):
        self.character = Character.objects.create(
            name='Draft Character', localization_key='draft_character',
            description='', group='Test', datas={}, img='https://example.invalid/draft.png',
        )
        self.draft_card = Card.objects.create(
            name='Draft Card', code='DRAFT-001', character=self.character,
            text='①사용 시, 2FP를 얻는다.', type='공격',
        )
        self.textless_card = Card.objects.create(
            name='Textless Card', code='DRAFT-002', character=self.character,
            text='', type='공격',
        )
        self.reviewed_card = Card.objects.create(
            name='Reviewed Card', code='DRAFT-003', character=self.character,
            text='①사용 시, 1FP를 얻는다.', type='공격',
            effect_definition={
                'schema_version': 1, 'reviewed': True,
                'source_refs': {'card_text': True, 'rulebook_pages': [], 'qna_ids': []},
                'review_evidence': {
                    'method': 'automatic-effect-v2', 'passed': True,
                    'scenario_count': 3,
                    'abilities': [{
                        'ability_id': 'reviewed', 'passed': True,
                        'scenarios': [
                            {
                                'name': f'reviewed-{index}', 'passed': True,
                                'deterministic': True,
                            }
                            for index in range(3)
                        ],
                    }],
                },
                'abilities': [{
                    'id': 'reviewed', 'kind': 'effect', 'mode': 'mandatory',
                    'trigger': {'event': 'use'}, 'timing': 'use',
                    'effects': [{'op': 'change_fp', 'amount': 1}],
                }],
            },
        )

    def test_seed_effect_drafts_updates_only_unreviewed_cards(self):
        original_reviewed = self.reviewed_card.effect_definition
        output = StringIO()

        call_command('seed_automatic_effect_drafts', stdout=output)

        self.draft_card.refresh_from_db()
        self.textless_card.refresh_from_db()
        self.reviewed_card.refresh_from_db()
        self.assertTrue(self.draft_card.effect_definition['draft'])
        self.assertEqual(len(self.draft_card.effect_definition['abilities']), 1)
        self.assertEqual(
            self.draft_card.effect_definition['source_digest'],
            effect_source_digest(self.draft_card, []),
        )
        self.assertTrue(self.textless_card.effect_definition['reviewed'])
        self.assertTrue(self.textless_card.effect_definition['no_effect'])
        self.assertEqual(self.reviewed_card.effect_definition, original_reviewed)
        self.assertIn('cards=2', output.getvalue())

    def test_seed_effect_drafts_can_target_exact_card_codes(self):
        original_textless = self.textless_card.effect_definition
        original_reviewed = self.reviewed_card.effect_definition
        output = StringIO()

        call_command(
            'seed_automatic_effect_drafts',
            '--card-code', self.draft_card.code,
            '--card-code', self.reviewed_card.code,
            '--overwrite-unreviewed',
            stdout=output,
        )

        self.draft_card.refresh_from_db()
        self.textless_card.refresh_from_db()
        self.reviewed_card.refresh_from_db()
        self.assertTrue(self.draft_card.effect_definition['draft'])
        self.assertEqual(self.textless_card.effect_definition, original_textless)
        self.assertEqual(self.reviewed_card.effect_definition, original_reviewed)
        self.assertIn('cards=1', output.getvalue())
        self.assertIn('skipped_reviewed=1', output.getvalue())

    def test_seed_effect_drafts_rejects_unknown_card_code(self):
        with self.assertRaisesMessage(CommandError, 'Unknown card code(s): MISSING-001'):
            call_command(
                'seed_automatic_effect_drafts',
                '--card-code', 'MISSING-001',
            )

    def test_review_effect_drafts_applies_three_scenario_evidence_atomically(self):
        output = StringIO()

        call_command('review_automatic_effect_drafts', '--apply', stdout=output)

        self.draft_card.refresh_from_db()
        self.textless_card.refresh_from_db()
        self.reviewed_card.refresh_from_db()
        self.assertTrue(self.draft_card.effect_definition['reviewed'])
        self.assertEqual(
            self.draft_card.effect_definition['review_evidence']['scenario_count'], 3,
        )
        self.assertTrue(self.textless_card.effect_definition['reviewed'])
        self.assertEqual(
            self.textless_card.effect_definition['review_evidence']['scenario_count'], 3,
        )
        self.assertEqual(
            self.reviewed_card.effect_definition['abilities'][0]['id'],
            'reviewed',
        )
        report = json.loads(output.getvalue())
        self.assertEqual(report['automatic_reviewed'], 2)
        self.assertEqual(report['preserved_reviewed'], 1)
        self.assertEqual(report['normalized_reviewed'], 1)
        self.assertFalse(self.reviewed_card.effect_definition['draft'])
        self.assertFalse(
            self.reviewed_card.effect_definition['abilities'][0]['draft'],
        )
        self.assertNotIn('pending', report)

    def test_review_command_refuses_passed_result_missing_real_ability_id(self):
        fake_result = SimpleNamespace(
            passed=True,
            reason='',
            as_dict=lambda: {
                'method': 'test-review',
                'passed': True,
                'scenario_count': 3,
                'abilities': [{
                    'ability_id': 'different-ability-id',
                    'passed': True,
                    'scenarios': [
                        {
                            'name': f'fake-{index}',
                            'passed': True,
                            'deterministic': True,
                        }
                        for index in range(3)
                    ],
                }],
            },
        )
        output = StringIO()

        with patch(
            'battlelog.management.commands.review_automatic_effect_drafts.review_automatic_definition',
            return_value=fake_result,
        ):
            call_command(
                'review_automatic_effect_drafts', '--apply',
                '--card-code', self.draft_card.code,
                stdout=output,
            )

        self.draft_card.refresh_from_db()
        report = json.loads(output.getvalue())
        self.assertFalse(self.draft_card.effect_definition['reviewed'])
        self.assertTrue(self.draft_card.effect_definition['draft'])
        self.assertEqual(report['invalid_review_evidence'], 1)
        self.assertEqual(report['pending_manual_review'], 1)

    def test_review_command_does_not_preserve_invalid_scenario_evidence(self):
        definition = copy.deepcopy(self.reviewed_card.effect_definition)
        definition.pop('review_evidence')
        self.reviewed_card.effect_definition = definition
        self.reviewed_card.save(update_fields=['effect_definition'])
        output = StringIO()

        call_command(
            'review_automatic_effect_drafts',
            '--card-code', self.reviewed_card.code,
            '--verbose', stdout=output,
        )

        report = json.loads(output.getvalue())
        self.reviewed_card.refresh_from_db()
        self.assertEqual(report['invalid_review_evidence'], 1)
        self.assertEqual(report['pending_manual_review'], 1)
        self.assertNotIn('preserved_reviewed', report)
        self.assertTrue(self.reviewed_card.effect_definition['reviewed'])
        self.assertIn('능력별 3개 결정적 상황', report['pending'][0]['reason'])

    def test_review_effect_drafts_can_target_exact_card_code(self):
        original_textless = self.textless_card.effect_definition

        call_command(
            'review_automatic_effect_drafts', '--apply',
            '--card-code', self.draft_card.code,
        )

        self.draft_card.refresh_from_db()
        self.textless_card.refresh_from_db()
        self.reviewed_card.refresh_from_db()
        self.assertTrue(self.draft_card.effect_definition['reviewed'])
        self.assertEqual(self.textless_card.effect_definition, original_textless)
        self.assertNotIn('draft', self.reviewed_card.effect_definition)

    def test_review_effect_drafts_can_revoke_a_stale_reviewed_interpretation(self):
        self.reviewed_card.text = (
            '①캐치 및 콤보 시, 이번 턴 리커버리 페이즈에 1FP를 얻는다.'
        )
        self.reviewed_card.effect_definition = {
            'schema_version': 1, 'reviewed': True, 'draft': False,
            'source_refs': {
                'card_text': True, 'rulebook_pages': [48, 49], 'qna_ids': [],
            },
            'abilities': [{
                'id': 'stale-recovery', 'kind': 'effect', 'mode': 'mandatory',
                'timing': 'combo', 'visibility': 'public',
                'draft_text': self.reviewed_card.text[1:],
                'source_refs': {
                    'card_text': True, 'rulebook_pages': [48, 49], 'qna_ids': [],
                },
                'trigger': {'event': 'catch', 'events': ['catch', 'combo']},
                'effects': [{
                    'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
                }],
            }],
        }
        self.reviewed_card.save(update_fields=['text', 'effect_definition'])
        output = StringIO()

        call_command(
            'review_automatic_effect_drafts', '--apply', '--recheck-reviewed',
            '--card-code', self.reviewed_card.code, stdout=output,
        )

        self.reviewed_card.refresh_from_db()
        report = json.loads(output.getvalue())
        self.assertFalse(self.reviewed_card.effect_definition['reviewed'])
        self.assertTrue(self.reviewed_card.effect_definition['draft'])
        self.assertEqual(report['recheck_failed'], 1)
        self.assertIn(
            '예약 효과가 즉시 효과',
            self.reviewed_card.effect_definition['review_evidence']['abilities'][0]['reason'],
        )

    def test_review_effect_drafts_can_rebuild_a_reviewed_definition(self):
        output = StringIO()

        call_command(
            'review_automatic_effect_drafts', '--apply', '--rebuild-reviewed',
            '--card-code', self.reviewed_card.code, stdout=output,
        )

        self.reviewed_card.refresh_from_db()
        report = json.loads(output.getvalue())
        self.assertTrue(self.reviewed_card.effect_definition['reviewed'])
        self.assertNotEqual(
            self.reviewed_card.effect_definition['abilities'][0]['id'],
            'reviewed',
        )
        self.assertEqual(report['rebuilt_reviewed'], 1)
        self.assertEqual(
            report['rebuilt_reviewed_codes'], [self.reviewed_card.code],
        )
        self.assertTrue(self.reviewed_card.effect_definition['source_digest'])

    def test_review_effect_drafts_rejects_conflicting_reviewed_modes(self):
        with self.assertRaisesMessage(
            CommandError,
            '--recheck-reviewed and --rebuild-reviewed cannot be used together.',
        ):
            call_command(
                'review_automatic_effect_drafts', '--recheck-reviewed',
                '--rebuild-reviewed', '--card-code', self.reviewed_card.code,
            )

    def test_review_effect_drafts_rejects_unknown_card_code(self):
        with self.assertRaisesMessage(CommandError, 'Unknown card code(s): MISSING-001'):
            call_command(
                'review_automatic_effect_drafts',
                '--card-code', 'MISSING-001',
            )


